// ==========================================
// ★ K 의 방 — B등급 직업 갈림길 · 감각
// 탐험가 · 사수 · 추적자 · 탐지술사 · 보물사냥꾼
// ==========================================

// ------------------------------------------
// 탐험가 (explorer) · 자원 없음
// ------------------------------------------
kJob('explorer', 'B', [
{ at:'B', t:'정전 — 초록 비상등 하나',
  x:`불이 한꺼번에 나갔다. 형광등이 다 꺼지고 비상등 하나만 남았다.<br><br>
    복도 끝, 초록. 문으로 달려가는 사람 그림이다.<br>
    뒤쪽 어둠에서 발소리가 난다. 서두르지 않는다. 서두를 필요가 없는 쪽의 걸음이다.<br><br>
    탐험가는 들어올 때 걸음을 세어 두었다. 어디를 가든 그렇게 한다.`,
  o:[
    { l:'① 세어 둔 걸음대로 어둠을 걷는다.', k:'sense', dc:20,
      ok:`문에서 열네 걸음. 왼쪽으로 꺾어 아홉 걸음. 거기 소화전이 있었다.<br><br>손을 뻗었다. 차가운 유리가 닿는다. 맞다.<br>일행 손을 줄줄이 잡게 하고 걸었다. 비상등 반대쪽으로. 아무도 불을 켜지 않았다.<br><br>뒤의 발소리는 초록 불빛 쪽으로 갔다. 그 밑에서 멈췄다. 거기서 기다리면 다 온다고 아는 걸음이었다.<br>눈이 쓸모없어지자 다리가 기억을 꺼냈다. 센 걸음이 벽이 되고 모퉁이가 됐다. 이제는 세지 않아도 세어진다.`,
      ng:`열두째 걸음에서 정강이에 무언가 걸렸다. 들어올 때는 없던 것이다.<br><br>쇠 수레다. 누가 옮겨 놓았다. 넘어지며 수레가 복도를 굴러갔다. 소리가 길게 울린다.<br>뒤의 발소리가 처음으로 빨라졌다. 기어서 모퉁이를 돌았다. 무릎에서 피가 난다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-24, mind:-12 }, wake:1 },
    { l:'② 비상등 쪽으로 곧장 간다.', k:'luck', dc:21,
      ok:`초록 불빛 밑 문을 밀었다. 열린다. 계단이다.<br><br>문틈에 신발 한 짝이 끼워져 있다. 닫히지 않게 누가 괴어 둔 것이다.<br>고마운 사람인지, 다시 오려던 사람인지는 모른다. 신발을 빼지 않고 지나갔다.`,
      ng:`비상등 밑에 누가 서 있다. 초록 불빛을 받아 얼굴이 초록이다.<br><br>움직이지 않는다. 이쪽이 올 줄 알았던 얼굴이다.<br>돌아서 뛰다가 벽에 어깨를 박았다. 뒤에서 웃는 소리는 나지 않았다. 그게 더 나빴다.`,
      win:{ exp:14, dream:2 }, lose:{ mind:-14, spirit:-16 } }
  ] },

{ at:'B1', t:'3번 창고 밑 — 바다로 가는 배수로',
  x:`창고 바닥 배수구 덮개를 들었다. 아래로 물이 흐른다. 빗물에 바닷물 냄새가 섞였다.<br><br>
    물은 바다로 간다. 바다 쪽에 방파제가 있다.<br>
    수로 벽에 따개비가 붙었다. 따개비는 바닷물이 닿는 높이까지만 산다.<br><br>
    따개비가 천장 바로 밑까지 붙어 있다.`,
  o:[
    { l:'① 물살 방향을 짚고 밀물 전에 지난다.', k:'sense', dc:21,
      ok:`물에 손을 담갔다. 아직 바다 쪽으로 흐른다. 힘이 약하다. 곧 돌아선다.<br><br>허리를 숙이고 걸었다. 따개비가 손바닥을 긁는다. 마흔 걸음 끝에 쇠사다리가 있다. 위는 맨홀이다.<br>머리로 밀어 올렸다. 야적장 끝, 탐조등이 닿지 않는 모서리다.<br><br>내려다보니 방금 걸어온 수로에 물이 거꾸로 차오르고 있다. 소리도 없이.`,
      doom:{ title:'거꾸로 드는 물', what:'밀물에 수로 안쪽으로 끌려갑니다', dc:17, sec:55,
        text:`스무 걸음째에 물살이 멈췄다. 한 박자 뒤 반대로 밀려온다.<br><br>무릎. 허리. 가슴. 수로 천장이 낮아진다. 물과 천장 사이가 손 한 뼘이다.<br>발이 바닥을 놓쳤다. 몸이 들어온 쪽으로, 창고 쪽으로 끌려간다.<br><br>천장을 긁는 손톱에 따개비가 박힌다.`,
        dieText:`새벽에 3번 창고 배수구가 넘쳤다.<br><br>회색 비옷이 와서 덮개를 열었다. 한참 들여다보다 닫았다.<br>나사를 새것으로 갈아 끼웠다. 나사 머리가 반짝였다.` },
      win:{ exp:23, dream:3 } },
    { l:'② 빗물 홈통을 타고 지붕으로 오른다.', k:'evade', dc:20,
      ok:`홈통 고정쇠가 사다리 노릇을 한다. 하나씩 디뎠다.<br><br>지붕 위는 비가 옆으로 친다. 양철 이음매를 따라 엎드려 기었다. 옆 창고 지붕까지 이어진다.<br>내려갈 자리에 천창이 있다. 유리가 깨끗하다. 이 비에.<br><br>누가 방금 닦았다. 안쪽에서.`,
      ng:`셋째 고정쇠가 빠졌다. 홈통째로 뒤로 젖혀진다.<br><br>마당 웅덩이에 등부터 떨어졌다. 숨이 한참 안 쉬어진다.<br>네온 간판 불빛이 웅덩이에 빨갛게 흔들린다. 그 불빛 너머에서 고무장화 한 켤레가 멈춰 섰다가 지나갔다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-28, spirit:-12 } }
  ] },

{ at:'B2', t:'병동 복도 — 새 종이의 피난 안내도',
  x:`복도 벽에 피난 안내도가 붙어 있다. 빨간 점이 현 위치. 비상계단은 복도 끝 왼쪽이다.<br><br>
    액자 유리에 손때가 묻었다. 계단 자리에만. 여러 손가락이 거기를 짚었다.<br>
    종이가 새것이다. 건물은 낡았는데 종이만 하얗다.<br><br>
    그림 말고 천장을 봤다.`,
  o:[
    { l:'① 들보 간격으로 계단 자리를 다시 센다.', k:'sense', dc:21,
      ok:`병원은 기둥을 같은 간격으로 세운다. 천장 들보를 셌다. 하나, 둘, 일곱.<br><br>안내도의 계단은 들보 하나만큼 어긋나 있다. 그 자리는 벽장이다. 들보 사이가 한 칸 넓어지는 데는 반대편 끝, 『린넨』이라고 붙은 문이다.<br>손잡이 아래 장판이 닳았다. 린넨실 문은 그렇게까지 닳지 않는다. 계단 문이다.<br><br>그림은 누가 바꿔 그릴 수 있다. 들보는 못 바꾼다. 지은 사람의 셈으로 건물을 읽었다. 그 셈이 손끝에 남았다.`,
      ng:`들보를 세는데 복도 끝에서 딸깍 소리가 났다. 계수기다.<br><br>세던 숫자가 날아갔다. 다시 셌다. 이번엔 하나가 많다.<br>간호사가 복도 끝에 서서 이쪽을 본다. 엄지가 움직인다. 딸깍. 이쪽도 세어졌다. 들보처럼.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-16, spirit:-14 }, wake:1 },
    { l:'② 안내도대로 복도 끝 왼쪽 문을 연다.', k:'luck', dc:22,
      ok:`문을 열었다. 계단이 아니다. 벽장이다. 걸레와 양동이.<br><br>선반 맨 위에 종이 상자가 있다. 약초 뭉치가 비닐에 싸여 들었다. 한방 처치실에서 쓰던 것을 누가 빼돌려 숨겼다.<br>벽장 안쪽 문짝에 손톱으로 그은 줄이 많다. 갇혔던 사람이 남긴 줄이다. 마지막 줄은 반만 그어졌다.`,
      ng:`문을 열자 안이 어둡다. 한 발 들였다. 등 뒤에서 문이 닫혔다. 바깥에서 잠기는 소리.<br><br>한참 두드렸다. 정각 점검이 지나가고서야 문이 열렸다.<br>열어 준 사람은 없다. 복도가 비어 있다. 문고리만 아직 따뜻하다.`,
      win:{ exp:14, dream:1, item:'약초 뭉치' }, lose:{ mind:-16, spirit:-18 } },
    { l:'③ 액자를 떼어 뒷면을 본다.', k:'gaze', dc:20,
      ok:`액자를 뒤집었다. 새 종이 밑에 옛 종이가 한 장 더 있다. 누렇다.<br><br>옛 안내도에는 계단이 둘이다. 하나에 볼펜으로 가위표가 쳐 있다. 다른 하나에는 아무 표시도 없다.<br>막은 사람은 막은 데만 표시한다. 표시가 없는 쪽이 지금도 열린 쪽이다.`,
      ng:`못에서 액자를 빼는데 유리가 미끄러졌다. 깨지는 소리가 복도 끝까지 갔다.<br><br>손바닥이 갈라졌다. 피가 종이에 떨어진다. 빨간 점 위에.<br>현 위치가 번졌다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-22, mind:-12 } }
  ] },

{ at:'B3', t:'연결 통로 — 사슬 감긴 앞문',
  x:`앞 칸으로 가는 문이 잠겼다. 손잡이에 사슬이 감겼다.<br><br>
    연결 통로 옆 문을 열면 바깥 발판이다. 손잡이 하나, 발판 하나. 그 너머는 빗속의 어둠이다.<br>
    발밑에서 선로가 빠르게 흐른다. 자갈이 튄다.<br><br>
    바깥으로 돌아갈 셈은 섰다. 빠진 게 하나 있다. 선로가 언제 꺾이느냐.`,
  o:[
    { l:'① 바퀴 소리로 굽은 길이 오는 때를 잰다.', k:'sense', dc:21,
      ok:`귀를 바닥에 댔다. 바퀴가 이음매를 넘는 소리가 고르다. 곧은 길이다.<br><br>고른 소리가 길게 이어질 때 나갔다. 손잡이, 발판, 다음 칸 손잡이. 일곱 걸음.<br>앞 칸 문을 열고 들어서자 바퀴 소리가 바뀌었다. 끼익. 열차가 크게 기운다.<br><br>창밖에서 무언가 선로 옆 기둥에 부딪쳐 부서졌다. 발판 손잡이에 걸려 있던 누군가의 우산이다.`,
      ng:`곧은 길이라고 들었다. 반쯤 나갔을 때 바퀴가 비명을 질렀다.<br><br>열차가 기울며 몸이 바깥으로 쏠린다. 손잡이에 팔꿈치를 걸었다. 어깨에서 뚝 소리가 났다.<br>겨우 앞 칸 문을 열었다. 팔이 올라가지 않는다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, spirit:-12 } },
    { l:'② 객차 벽에 몸을 붙이고 한 걸음씩 건넌다.', k:'steady', dc:20,
      ok:`바람이 옷을 뜯어 간다. 몸을 객차 벽에 붙였다. 빗물이 귀로 들어온다.<br><br>한 걸음에 숨 하나. 앞 칸 손잡이를 잡았다. 놓지 않았다.<br>안으로 들어와 보니 손가락이 굽은 채 펴지지 않는다.`,
      ng:`발판이 젖어 미끄럽다. 한쪽 발이 허공에 떴다.<br><br>손잡이에 매달려 한참 흔들렸다. 튄 자갈이 정강이를 두들긴다.<br>기어올라 왔을 때 바지가 찢기고 다리가 온통 멍이다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-26, mind:-12 } }
  ] },

{ at:'B', t:'비상구 — 사슬 두 바퀴',
  x:`비상구 문에 사슬이 두 바퀴 감겼다. 자물쇠는 새것이다.<br><br>
    뒤에서 문 여는 소리가 하나씩 다가온다. 방마다 열어 본다.<br>
    일행이 사슬을 당긴다. 안 풀린다.<br><br>
    탐험가는 사슬을 보지 않는다. 사람을 가둔 곳에도 일하는 사람이 다니는 길은 따로 있다.`,
  o:[
    { l:'① 일하는 사람이 다니는 길을 찾는다.', k:'sense', dc:21,
      ok:`바닥을 봤다. 손님 다니는 가운데는 고르다. 벽을 따라 한 줄만 바퀴 자국이 거뭇하다. 수레가 다니는 줄이다.<br><br>줄은 벽에 붙은 철판 앞에서 끝난다. 손잡이도 없다. 철판 밑을 밀었다. 위로 올라간다. 짐을 내리던 승강 통로가 뒤에 있다.<br>일행을 하나씩 밀어 넣고 마지막에 철판을 내렸다. 문 여는 소리가 바로 앞에서 멈췄다.<br><br>문보다 바닥을 먼저 봤다. 손님의 길과 일꾼의 길은 따로 난다. 어느 건물이든. 그걸 알고 나니 잠긴 문이 반만 잠겨 보인다.`,
      ng:`바퀴 자국을 따라갔는데 끝이 두 군데다. 하나를 골랐다.<br><br>막힌 벽이다. 벽에 수레가 기대 서 있다. 수레 위에 하얀 천이 덮였다. 천 밑이 사람 모양이다.<br>돌아섰을 때 문 여는 소리는 이미 이 복도에 들어와 있었다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-16, spirit:-18 }, wake:1 },
    { l:'② 소화기로 사슬 고리를 내리친다.', k:'break', dc:22,
      ok:`소화기를 들어 고리 한 군데만 계속 내리쳤다. 소리가 크다. 상관없다.<br><br>일곱째에 고리가 벌어졌다. 사슬이 바닥에 쏟아진다. 문이 열린다. 비 냄새.<br>뒤에서 오던 소리가 처음으로 뛰기 시작했다.`,
      ng:`열 번을 쳤다. 고리는 그대로다. 소화기 밑동만 찌그러졌다.<br><br>손바닥이 터졌다. 뒤에서 문 하나가 바로 옆에서 열렸다.<br>일행을 끌고 반대쪽으로 뛰었다. 피 묻은 손자국이 비상구 문에 남았다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-26, mind:-12 } }
  ] },

{ at:'B1', t:'컨테이너 야적장 — 쌓인 번호',
  x:`컨테이너가 네 단씩 쌓여 골목을 이룬다. 골목이 꺾이고 또 꺾인다.<br><br>
    비가 철판을 두드린다. 사방에서 같은 소리다. 방향을 잃기 좋다.<br>
    컨테이너마다 번호가 찍혀 있다. 칠이 벗겨진 것도 있다.<br><br>
    멀리서 크레인 탐조등이 돈다. 한 바퀴에 스무 박자.`,
  o:[
    { l:'① 번호가 쌓인 순서로 정문 쪽을 읽는다.', k:'sense', dc:21,
      ok:`번호는 아무렇게나 쌓이지 않는다. 배에서 내린 순서대로 놓인다. 먼저 내린 것이 정문에 가깝다.<br><br>앞자리 숫자가 줄어드는 쪽으로 꺾었다. 셋째 골목에서 바닥에 트럭 바퀴 자국이 나온다. 정문으로 나가는 자국이다.<br>그 위에 고무장화 자국이 겹쳐 있다. 정문 쪽에서 들어오는 방향이다.<br><br>방금이다. 빗물이 아직 자국 안으로 덜 찼다.`,
      ng:`번호를 읽다 칠 벗겨진 컨테이너 하나를 잘못 셌다. 골목이 막힌다.<br><br>돌아 나오는데 탐조등이 골목에 꽂힌다. 일행 모습이 철판에 길게 찍혔다.<br>멀리서 호루라기가 한 번 울렸다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-14, spirit:-16 } },
    { l:'② 탐조등 박자에 맞춰 일행을 움직인다.', k:'fix', dc:20,
      ok:`스무 박자. 불빛이 지나가면 열두 박자는 어둡다. 그 사이만 걸었다.<br><br>불빛이 오면 컨테이너 그늘에 붙고 지나가면 걸었다. 다들 박자를 탔다.<br>아무도 비치지 않았다.`,
      ng:`일행 하나가 박자를 놓쳤다. 불빛 한복판에 섰다.<br><br>끌어당기다 둘이 같이 넘어졌다. 철판 모서리에 이마를 찧었다.<br>불빛이 그 자리에 오래 머물렀다.`,
      win:{ exp:14, dream:1 }, lose:{ hp:-24, mind:-12 } },
    { l:'③ 문 열린 컨테이너 안에 숨는다.', k:'hide', dc:21,
      ok:`문이 반쯤 열린 컨테이너. 안에 마른 자루가 쌓였다.<br><br>자루 하나가 굵은 소금이다. 생선 절이는 소금. 단단하게 굳은 덩이를 하나 챙겼다.<br>문틈으로 탐조등이 지나간다. 셋을 세고 나왔다.`,
      ng:`들어서자 문이 바람에 닫혔다. 바깥 걸쇠가 저절로 걸렸다.<br><br>철판을 두드렸다. 비가 소리를 먹는다. 한참 뒤 걸쇠가 풀렸다.<br>바깥에 아무도 없다. 젖은 발자국이 문 앞까지 왔다가 돌아갔다.`,
      win:{ exp:14, dream:1, item:'소금 덩이' }, lose:{ mind:-16, spirit:-14 } }
  ] },

{ at:'B2', t:'환기 덕트 — 이음매 세기',
  x:`천장 환기구를 떼어 냈다. 덕트가 이어진다. 어깨가 겨우 들어간다.<br><br>
    안은 캄캄하다. 바람이 한쪽에서 분다. 먼지 냄새, 그리고 표백제 냄새.<br>
    덕트는 갈라지고 꺾인다. 어디로 나오는지는 알 수 없다.<br><br>
    손바닥으로 철판 이음매를 짚었다. 이음매마다 길이가 같다.`,
  o:[
    { l:'① 이음매를 세며 층과 방을 가늠한다.', k:'sense', dc:21,
      ok:`이음매 하나가 한 자. 열두 이음매마다 갈래가 난다. 병실 하나의 폭이다.<br><br>세며 기었다. 넷째 갈래에서 아래로 꺾이는 관이 있다. 거기서 바람이 따뜻하다. 아래층 보일러실 열기다.<br>그 관만 따라 내려갔다. 철망 너머로 계단참이 보인다.<br><br>보이지 않는 데서 손바닥이 자를 대신했다. 셈이 끊기지 않으면 어둠도 방 모양이 된다. 이 셈은 이제 손에서 떨어지지 않는다.`,
      ng:`세던 중에 앞에서 철판이 울렸다. 누가 이쪽으로 기어 온다.<br><br>뒤로 물러나다 셈을 잃었다. 엉뚱한 갈래로 빠졌다. 막혀 있다.<br>숨을 죽였다. 철판 울림이 바로 옆 관을 지나갔다. 한참 뒤에야 숨을 쉬었다. 팔꿈치가 다 벗겨졌다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-22, mind:-14 }, wake:1 },
    { l:'② 바람이 오는 쪽으로 무작정 기어간다.', k:'steady', dc:20,
      ok:`바람이 오는 데에 바깥이 있다. 그쪽으로 기었다.<br><br>먼지가 목에 붙는다. 기침을 삼켰다. 한참 뒤 철망 너머로 빗소리가 들린다. 바깥 벽 환기구다. 나갈 데는 아니다. 공기는 맑다.<br>철망 옆에 물병 하나가 세워져 있다. 맑은 물이다. 뚜껑에 이름을 적었다가 지운 자국이 있다.`,
      ng:`덕트가 좁아진다. 어깨가 끼었다.<br><br>앞으로도 뒤로도 안 간다. 숨을 다 뱉고서야 몸이 빠졌다. 갈비뼈가 욱신거린다.<br>그 사이 아래 방에서 누가 천장을 올려다봤다. 철망 사이로 눈이 마주쳤다.`,
      win:{ exp:14, dream:1, item:'맑은 물' }, lose:{ hp:-24, spirit:-14 } }
  ] },

{ at:'B3', t:'화물칸 — 열린 옆문',
  x:`화물칸 옆문이 열려 있다. 바람이 들어와 짐 꼬리표를 흔든다.<br><br>
    밖은 비와 어둠이다. 이따금 선로 옆 신호등이 빨갛게 지나간다.<br>
    안쪽 짐 더미 뒤에서 무언가 움직였다. 얼굴을 바꾸는 손님이 이 칸 어딘가에 있다.<br><br>
    문밖의 어둠을 읽었다. 어둠에도 생김새가 있다.`,
  o:[
    { l:'① 바깥 벽을 타고 짐 더미 뒤로 돌아간다.', k:'sense', dc:22,
      ok:`신호등 간격을 셌다. 빨강, 열여덟 박자, 빨강. 그 사이에는 선로 옆에 아무것도 없다.<br><br>문틀을 잡고 바깥 벽으로 나갔다. 창틀에 발을 걸고 세 칸. 짐 더미 뒤쪽 창으로 다시 들어갔다.<br>짐 더미 뒤에는 아무도 없다. 젖은 외투 한 벌이 상자에 걸쳐 있다. 주머니에 기차표. 행선지 칸이 비었다.<br><br>안쪽에서 누가 옆문을 닫았다. 이쪽이 나간 문을.`,
      doom:{ title:'선로 옆 기둥', what:'신호 기둥에 채여 열차 밖으로 끌려 나갑니다', dc:17, sec:50,
        text:`열여덟 박자라고 셌다. 열다섯째에 빨간 불빛이 왔다. 열차가 빨라진 것이다.<br><br>신호 기둥이 어깨를 쳤다. 손 하나가 창틀에서 떨어진다. 한 손만 남았다.<br>몸이 바깥으로 펄럭인다. 빗속에서 자갈 둑이 빠르게 흘러간다.<br><br>창 안쪽에서 누가 이쪽 손을 내려다본다.`,
        dieText:`신호등이 빨갛게 지나갔다. 하나, 또 하나.<br><br>화물칸 옆문은 그 뒤로 닫혀 있었다.<br>짐 꼬리표가 하나 늘었다. 행선지 칸이 비어 있다.` },
      win:{ exp:24, dream:3 } },
    { l:'② 일행과 등을 맞대고 짐 사이를 지난다.', k:'bond', dc:21,
      ok:`등을 맞대고 짐 사이를 걸었다. 앞은 이쪽이, 뒤는 일행이 봤다.<br><br>짐 더미 뒤에 아무도 없다. 젖은 발자국만 있다. 발자국은 짐 사이를 한 바퀴 돌아 일행 발자국 뒤에 붙어 끝났다.<br>돌아봤다. 일행을 하나씩 세었다. 맞다. 숫자는.`,
      ng:`짐 꼬리표 하나가 얼굴을 쳤다. 고개를 돌린 사이 등이 비었다.<br><br>차가운 손가락이 목덜미를 스쳤다. 돌아보니 일행이다.<br>일행이 맞는지 한참 들여다봤다. 일행도 이쪽을 그렇게 봤다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-16, spirit:-18 } }
  ] },

{ at:'B', t:'쫓기는 갈림길 — 닫힌 문 셋',
  x:`복도가 셋으로 갈린다. 문이 셋이다. 셋 다 닫혀 있다.<br><br>
    뒤에서 발소리가 뛴다. 이제는 서두르는 발소리다.<br>
    문 하나 고를 시간은 숨 셋.<br><br>
    문 말고 문틈을 봤다.`,
  o:[
    { l:'① 문틈 바람으로 바깥과 이어진 문을 고른다.', k:'sense', dc:21,
      ok:`셋 중 하나만 문틈 먼지가 안쪽으로 눕는다. 바람이 빨려 들어간다. 그 너머에 큰 빈 데가 있고, 큰 빈 데는 바깥과 닿는다.<br><br>그 문을 열고 일행을 밀어 넣었다. 계단이다. 아래에서 빗소리가 올라온다.<br>문을 닫았다. 다른 두 문이 차례로 열리는 소리. 이쪽 문이 세 번째로 열렸을 때 계단에는 아무도 없었다.<br><br>숨 셋 동안 문 셋을 다 읽었다. 숨을 쉬듯이. 몸이 먼저 고르고 머리가 나중에 알아들었다.`,
      ng:`먼지가 눕는 문을 골랐다. 바람이 빨려 든 데는 승강기 통로였다. 문 너머가 바로 허공이다.<br><br>문틀을 잡고 버텼다. 일행이 허리를 끌어당겼다.<br>발소리가 등 뒤에 와 있다. 옆 문으로 굴러 들어갔다. 어깨가 바닥에 먼저 닿았다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-28, mind:-14 }, wake:1 },
    { l:'② 일행을 갈라 세 문으로 흩어진다.', k:'bond', dc:22,
      ok:`셋으로 나눴다. 다시 만날 자리를 정했다. 아래층 계단참.<br><br>발소리가 갈림길에서 멈춘다. 무엇을 쫓을지 고르는 동안이다. 그 동안이면 충분했다.<br>계단참에서 다 만났다. 서로 얼굴을 하나씩 확인했다. 아무도 웃지 않았다.`,
      ng:`흩어졌다. 다시 만날 자리에 한 무리가 오지 않았다.<br><br>한참 기다렸다. 오긴 왔다. 늦게.<br>오는 내내 등 뒤에서 누가 같은 박자로 걸었다고 했다. 그 뒤로 한동안 아무도 말을 하지 않았다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-18, spirit:-16 } },
    { l:'③ 가운데 문을 열고 그냥 뛴다.', k:'evade', dc:21,
      ok:`가운데 문 너머는 긴 복도다. 그냥 뛰었다. 다리가 빠르면 고를 것이 줄어든다.<br><br>복도 끝 문을 열고 닫고 걸쇠를 걸었다.<br>걸쇠 너머에서 문고리가 한 번 돌았다. 두 번. 그리고 멈췄다.`,
      ng:`가운데 문 너머는 짧았다. 열 걸음 만에 벽이다.<br><br>돌아서는데 문간에 누가 섰다. 그 옆을 빠져나가다 팔을 잡혔다.<br>뿌리쳤다. 팔뚝에 손톱자국 넷이 길게 났다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-26, spirit:-14 } }
  ] },

{ at:'B', t:'벽 — 반듯한 분필 화살표',
  x:`벽에 분필 화살표가 있다. 먼저 온 누군가가 남긴 것이다.<br><br>
    화살표 끝이 반듯하다. 급한 사람의 표시가 아니다.<br>
    급하지 않은 사람이 이런 데 화살표를 남길 까닭은 많지 않다.<br><br>
    화살표는 복도 끝 문을 가리킨다.`,
  o:[
    { l:'① 화살표를 그은 손을 읽는다.', k:'gaze', dc:21,
      ok:`분필 가루가 화살표 밑에 고르게 쌓였다. 한 번에 그은 선이다. 서두르지 않았다.<br><br>화살표 꼬리마다 작은 점이 찍혀 있다. 하나, 둘, 셋. 앞의 화살표일수록 점이 많다. 지나간 사람 수를 세는 표시다.<br>복도 끝 문은 열지 않았다. 반대쪽으로 돌았다.<br><br>돌면서 꼬리의 점들을 손바닥으로 문질러 지웠다.`,
      ng:`읽다 보니 화살표가 하나 더 있다. 바로 등 뒤 벽에.<br><br>방금 그은 것처럼 가루가 날린다.<br>이쪽을 가리킨다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-16, spirit:-20 } },
    { l:'② 화살표 반대로 간다.', k:'sense', dc:20,
      ok:`남긴 사람이 바라는 대로 가지 않는다. 반대로 꺾었다.<br><br>반대쪽은 물 새는 복도다. 바닥 웅덩이에 비상등 불빛이 비친다. 웅덩이 가장자리에 발자국이 하나도 없다.<br>아무도 이쪽으로 오지 않았다. 그래서 이쪽이 낫다. 끝에 계단이 있다.`,
      ng:`반대로 갔다. 막다른 길이다. 벽에 또 화살표가 있다. 되돌아가라는 쪽이다.<br><br>되돌아오니 처음 화살표가 지워져 있다.<br>지운 손자국이 아직 젖었다.`,
      win:{ exp:15, dream:2 }, lose:{ mind:-14, spirit:-16 } }
  ] },

{ at:'B1', t:'냉동 창고 — 벽에 앉은 성에',
  x:`냉동 창고 문이 등 뒤에서 닫혔다. 안쪽 손잡이는 떼어져 있다.<br><br>
    입김이 하얗다. 갈고리마다 언 생선이 줄지어 걸렸다.<br>
    오래 있으면 손가락부터 말을 안 듣는다.<br><br>
    벽 곳곳에 성에가 앉았다. 두께가 다 다르다.`,
  o:[
    { l:'① 성에가 얇은 자리에서 바깥으로 닿는 틈을 찾는다.', k:'sense', dc:21,
      ok:`성에는 찬 데에 두껍게, 바깥 바람이 새는 데에 얇게 앉는다.<br><br>벽에 손등을 대고 걸었다. 구석 한 자리만 성에가 없다. 녹은 물이 줄을 긋는다. 배관 구멍이다. 단열재를 뜯어내자 팔 하나가 들어간다.<br>팔을 넣어 바깥 걸쇠를 더듬었다. 걸쇠가 아니다. 철사로 감아 놓았다. 철사를 풀었다.<br><br>문이 열린다. 문 앞에 하역부 장갑 한 켤레가 가지런히 놓여 있다. 누가 이쪽이 나올 줄 알았다. 아니면 안 나올 줄.`,
      ng:`얇은 자리를 찾다 손등이 벽에 붙었다. 떼어 내자 살갗이 남았다.<br><br>찾은 틈은 배관 구멍이 아니라 쥐구멍이었다.<br>손이 얼어 주먹이 안 쥐어진다. 다른 길을 찾는 사이 입술이 파래졌다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, mind:-12 } },
    { l:'② 갈고리 하나를 뜯어 문을 들어 올린다.', k:'break', dc:22,
      ok:`레일에 걸린 갈고리 하나를 뜯어냈다. 문틈에 끼우고 지렛대 삼아 눌렀다.<br><br>문이 한 뼘 들렸다. 그 틈으로 기어 나왔다.<br>나오면서 갈고리에 걸린 고기 한 덩이를 끌고 나왔다. 언 짐승 고기다. 녹이면 먹는다.`,
      ng:`갈고리가 뜯기며 레일이 움직였다. 줄지어 걸린 갈고리가 한꺼번에 미끄러져 온다.<br><br>언 생선이 몸을 때린다. 피하다 바닥 얼음에 넘어져 허리를 찧었다.<br>레일은 한참 뒤에야 멈췄다. 누가 멈춘 것처럼.`,
      win:{ exp:16, dream:1, item:'짐승 고기' }, lose:{ hp:-30, spirit:-12 } }
  ] },

{ at:'B2', t:'비상계단 — 다시 4층',
  x:`비상계단을 한 층 내려왔다. 문 위에 4라고 적혀 있다.<br><br>
    한 층 더 내려왔다. 4.<br>
    또 내려왔다. 4. 문 옆 소화기 자리가 똑같다. 긁힌 자국까지.<br><br>
    계단 수를 세고 있었다. 버릇이다.`,
  o:[
    { l:'① 층마다 계단 수가 어디서 다른지 찾는다.', k:'sense', dc:22,
      ok:`첫 층은 스물네 칸. 둘째도 스물넷. 셋째는 스물셋이었다. 한 칸이 모자랐다.<br><br>셋째 층참으로 돌아갔다. 모자란 자리를 찾았다. 계단 하나가 다른 것보다 조금 높다. 틈에 손가락을 넣자 계단 판이 들린다. 아래로 좁은 철계단이 이어진다. 관리용이다.<br>그리로 내려갔다. 문 위에 3.<br><br>같은 데를 도는 것처럼 보여도 걸음은 속지 않는다. 다른 것은 늘 하나 있다. 그 하나를 찾아내는 눈이 몸에 붙었다.`,
      ng:`세다가 셋째 층도 스물넷이라는 걸 알았다. 그럼 넷째도 같을 것이다. 다섯째도.<br><br>내려갈수록 다리가 무거워진다. 4를 다섯 번 더 봤다.<br>문 너머에서 누가 그 숫자를 따라 세고 있었다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-18, spirit:-16 }, wake:1 },
    { l:'② 난간을 넘어 한 층 아래 난간으로 매달려 내린다.', k:'evade', dc:21,
      ok:`난간 너머 아래를 봤다. 끝이 안 보인다. 난간을 넘어 매달렸다. 한 층 아래 난간에 발이 닿았다.<br><br>계단을 밟지 않고 내려가자 문 위 숫자가 바뀌었다. 3.<br>계단이 되돌려 보내는 것은 계단을 밟은 사람뿐이었다.`,
      ng:`난간을 넘었다. 아래 난간에 발이 닿기 전에 젖은 손이 미끄러졌다.<br><br>한 층을 떨어져 계단참에 부딪쳤다. 숨이 끊겼다 이어졌다.<br>고개를 드니 문 위에 4.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-30, mind:-12 } }
  ] },

{ at:'B3', t:'지붕 위 — 산이 다가온다',
  x:`객차 끝 사다리로 지붕에 올랐다. 기관실까지는 지붕을 타는 게 빠르다.<br><br>
    바람이 몸을 뒤로 민다. 비가 얼굴을 친다. 지붕 철판이 미끄럽다.<br>
    멀리 산이 검게 다가온다. 산이 있으면 터널이 있다.<br><br>
    터널 천장은 지붕에서 한 뼘 위다.`,
  o:[
    { l:'① 바람 소리가 바뀌는 순간 엎드린다.', k:'sense', dc:22,
      ok:`귀를 열었다. 바람은 들판에서 넓게 운다. 터널 앞에서는 소리가 먼저 좁아진다.<br><br>소리가 좁아지는 순간 납작 엎드렸다. 뺨을 철판에 댔다. 머리 위로 검은 천장이 지나간다. 숨을 쉬지 않았다.<br>터널을 빠져나와 몸을 일으켰다.<br><br>지붕 위에 이쪽 말고 발자국이 하나 더 있다. 젖은 철판 위에 맨발로. 앞쪽으로 간다.`,
      doom:{ title:'터널 천장', what:'터널 천장에 채여 객차 사이로 떨어집니다', dc:17, sec:50,
        text:`바람 소리가 좁아지는 걸 늦게 들었다.<br><br>엎드리는데 등에 돌이 닿는다. 터널 천장이 옷을 긁고 지나간다. 손이 지붕 끝을 놓친다.<br>객차 사이로 몸이 빠진다. 연결부 철판에 한 손이 걸렸다. 발밑에서 바퀴가 돈다.<br><br>터널 속은 아무것도 안 보인다. 소리만 크다.`,
        dieText:`열차가 터널을 빠져나왔다. 지붕은 비어 있다.<br><br>안내 방송이 다음 역을 부른다. 서지 않는 역이다.<br>객차 안 승객들은 고개를 창 쪽으로 기울인 채 계속 잔다. 한 사람이 늘었다.` },
      win:{ exp:25, dream:3 } },
    { l:'② 지붕을 버리고 객차 안으로 내려간다.', k:'hide', dc:20,
      ok:`사다리를 내려와 객차 안으로 들어갔다. 승객들이 잔다. 그 사이를 몸을 낮춰 지났다.<br><br>창밖이 갑자기 검어진다. 터널이다. 지붕에 있었다면.<br>객차 끝 선반에 작은 꿀단지가 놓였다. 식당칸 것이다. 누가 들고 와서 잊었다.`,
      ng:`승객들 사이를 지나는데 하나가 고개를 든다. 눈을 감은 채.<br><br>그 사람이 이쪽으로 손을 뻗는다. 피하다 선반 모서리에 이마를 찧었다.<br>승객은 다시 고개를 기울였다. 손은 계속 그 자리에 떠 있다.`,
      win:{ exp:14, dream:1, item:'꿀 한 줌' }, lose:{ hp:-22, spirit:-16 } }
  ] },

{ at:'B', t:'새는 천장 — 빗물 줄',
  x:`천장에서 빗물이 샌다. 한 줄이 아니다. 여러 줄이 바닥에 웅덩이를 판다.<br><br>
    빗물은 위에서 길을 따라 내려온다.<br>
    물 새는 자리는 위가 터진 자리다.<br><br>
    위가 터진 자리는 위로 나갈 수 있는 자리다.`,
  o:[
    { l:'① 빗물 줄로 지붕 틈을 짚는다.', k:'sense', dc:20,
      ok:`줄은 한 선 위에 늘어서 있다. 지붕 홈통이 지나는 선이다. 그런데 한 자리만 줄이 굵다. 거기가 터졌다.<br><br>의자를 쌓아 올라가 천장 판을 밀었다. 판이 빠진다. 위는 지붕 밑 다락이다. 빗소리가 가깝다.<br>다락 기둥 사이에 누가 지내던 자리가 있다. 담요와 말린 고기 한 묶음.<br><br>담요는 차다. 다행이다.`,
      ng:`굵은 줄을 짚었는데 천장 판이 통째로 무너졌다.<br><br>물을 머금은 판이 머리로 쏟아졌다. 눈에 가루가 들어가 한참 앞을 못 봤다.<br>그 사이 구멍 위에서 누가 내려다보는 기척이 있었다. 눈을 씻고 올려다봤을 때는 빗물만 떨어졌다.`,
      win:{ exp:16, dream:2, item:'말린 고기' }, lose:{ hp:-24, mind:-14 } },
    { l:'② 웅덩이 사이 마른 데만 밟고 지난다.', k:'luck', dc:21,
      ok:`물을 밟으면 철벅인다. 웅덩이 사이 마른 데만 골라 밟았다.<br><br>복도 끝까지 소리가 나지 않았다.<br>마지막 웅덩이 옆에 유리병이 굴러 있다. 맑은 물이 들었다. 마개가 꼭 닫혔다. 빗물이 아니다.`,
      ng:`마른 데라 생각한 자리가 기름이었다. 미끄러졌다. 웅덩이에 엎어졌다.<br><br>소리가 복도를 울렸다. 저쪽에서 문 하나가 열렸다.<br>아무도 나오지 않았다. 문은 열린 채로 있었다.`,
      win:{ exp:13, dream:1, item:'맑은 물' }, lose:{ hp:-22, spirit:-16 } }
  ] },

{ at:'B1', t:'어시장 경매장 — 수조의 관',
  x:`경매장 바닥에 수조가 줄지어 있다. 물이 흐리다. 바닥에서 무언가 움직인다.<br><br>
    수조마다 관이 이어져 있다. 바닷물을 끌어오는 관이다.<br>
    노란 비옷들이 경매판 앞에 모여 있다. 출구 쪽이다.<br><br>
    관을 따라가 본다. 바닷물을 끌어오는 관은 바다에 닿는다.`,
  o:[
    { l:'① 관을 따라 바다 쪽 펌프실을 찾는다.', k:'sense', dc:21,
      ok:`관은 수조 밑을 지나 바닥 아래로 들어간다. 바닥 철판 하나가 관 때문에 들려 있다.<br><br>들어 올렸다. 펌프실이다. 모터가 돈다. 그 소리가 일행 발소리를 덮는다. 벽에 바다로 난 쇠문이 있다. 걸쇠만 걸렸다.<br>문을 조금 열었다. 바다 냄새와 방파제 불빛. 나갈 길은 정해졌다.<br><br>건물에는 핏줄이 있다. 물이 흐르는 관, 바람이 흐르는 관. 핏줄을 따라가면 안에서 바깥이 보인다. 이제는 문보다 관을 먼저 본다.`,
      ng:`관을 따라가다 수조 하나에 손을 짚었다. 흐린 물속에서 무언가 손을 향해 올라왔다.<br><br>손을 뺐다. 손등이 길게 찢겼다. 짠물이 들어가 쓰리다.<br>경매판 앞 노란 비옷 하나가 고개를 돌렸다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-26, spirit:-14 }, wake:1 },
    { l:'② 수조 밑으로 엎드려 기어 지난다.', k:'hide', dc:20,
      ok:`수조 밑으로 엎드려 기었다. 바닥이 젖어 소리가 안 난다.<br><br>마지막 수조 밑에 통이 하나 있다. 장어 넣는 민물 통이다. 민물고기 몇 마리가 갇혀 있다. 하나를 건졌다.`,
      ng:`기어가다 수조 관을 발로 찼다. 관이 빠지며 물이 뿜어진다.<br><br>노란 비옷들이 일제히 돌아본다. 일행을 끌고 수조 사이를 뛰었다.<br>등 뒤로 갈고리 장대가 날아와 수조 유리를 깼다.`,
      win:{ exp:14, dream:1, item:'민물고기' }, lose:{ hp:-24, mind:-14 } }
  ] },

{ at:'B2', t:'세탁물 투입구 — 아래로 난 구멍',
  x:`벽에 세탁물 투입구가 있다. 철판 뚜껑을 밀면 아래로 통로가 떨어진다.<br><br>
    아래에서 세탁기 도는 소리가 올라온다. 그리고 표백제 냄새.<br>
    통로가 몇 층을 지나는지, 중간에 꺾이는지는 모른다.<br><br>
    뚜껑에 종이가 붙었다. 『사람 금지』. 누가 사람을 넣어 봤다는 뜻이다.`,
  o:[
    { l:'① 떨어뜨린 것의 소리로 깊이와 꺾임을 잰다.', k:'sense', dc:21,
      ok:`시트 한 장을 뭉쳐 던졌다. 세었다. 하나, 둘. 툭. 쓸리는 소리. 셋.<br><br>두 층 아래에서 한 번 꺾인다. 꺾인 데는 비탈이다. 바닥은 시트 더미다.<br>발부터 들어갔다. 꺾인 데서 등을 대고 미끄러졌다. 시트 더미 위로 떨어졌다. 세탁실이다.<br><br>세탁기 하나가 돈다. 안에서 흰 옷이 돈다. 옷마다 숫자가 찍혀 있다.`,
      ng:`던진 시트 소리가 중간에 끊겼다. 어딘가 걸린 것이다.<br><br>그래도 들어갔다. 꺾인 데에 걸린 시트에 몸이 같이 끼었다.<br>한참 버둥거렸다. 위에서 뚜껑 닫히는 소리가 났다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, mind:-16 } },
    { l:'② 시트를 엮어 줄을 만들어 내려간다.', k:'steady', dc:20,
      ok:`시트를 꼬아 엮었다. 투입구 경첩에 묶고 한 사람씩 내렸다.<br><br>팔이 떨렸지만 놓지 않았다. 아래는 세탁실이다.<br>다 내려왔다. 마지막에 줄을 끊어 아래로 당겨 내렸다. 위에 남기지 않았다.`,
      ng:`매듭 하나가 풀렸다. 한 층을 미끄러졌다.<br><br>손바닥이 시트에 쓸려 화끈거린다.<br>아래 바닥에 무릎부터 떨어졌다.`,
      win:{ exp:14, dream:1 }, lose:{ hp:-26, spirit:-12 } },
    { l:'③ 투입구 옆 선반을 뒤진다.', k:'luck', dc:21,
      ok:`선반에 접힌 시트가 쌓였다. 그 사이에 종이 봉지가 끼어 있다.<br><br>꿀 한 줌. 누가 간식을 아껴 숨겨 두었다.<br>봉지에 이름 대신 침대 번호가 적혀 있다.`,
      ng:`뒤지다 시트 더미가 무너졌다. 그 밑에 사람이 누워 있다. 눈을 뜨고.<br><br>숨은 쉰다. 이쪽을 본다. 아무 말 없다.<br>시트를 다시 덮어 주었다. 손이 한참 떨렸다.`,
      win:{ exp:13, dream:1, item:'꿀 한 줌' }, lose:{ mind:-16, spirit:-20 } }
  ] },

{ at:'B3', t:'우편칸 — 자루 사이로 난 길',
  x:`우편칸에 자루가 산처럼 쌓였다. 앞 칸으로 가는 문은 자루 더미 너머다.<br><br>
    자루마다 꼬리표가 달렸다. 받는 사람 칸이 다 비었다.<br>
    자루 사이로 길이 하나 나 있다. 몸을 옆으로 해야 지난다.<br><br>
    누가 낸 길인지를 봤다. 사람이 낸 길은 어깨 높이가 닳는다.`,
  o:[
    { l:'① 닳은 높이로 길을 낸 것의 키를 잰다.', k:'sense', dc:22,
      ok:`자루 겉이 닳은 높이가 무릎 아래다. 사람이 아니다. 기어서 다닌 길이다.<br><br>그 길로 들어가지 않았다. 자루 더미 위로 올라 천장 밑을 기었다. 아래 길에서 무언가 지나간다. 자루가 차례로 들썩인다.<br>앞문에 닿아 내려섰다. 문을 열고 나서야 숨을 쉬었다.`,
      doom:{ title:'자루 사이 길', what:'자루 더미 밑으로 끌려 들어갑니다', dc:17, sec:55,
        text:`닳은 자국을 사람 어깨 높이라고 읽었다. 몸을 옆으로 하고 길로 들어섰다.<br><br>반쯤 갔을 때 발목을 잡혔다. 아래에서. 바닥 높이에서.<br>손이 차고 세다. 당긴다. 무릎이 꺾인다. 자루가 위에서 내려앉는다.<br><br>숨이 자루 냄새로 막힌다. 종이 냄새, 젖은 삼베 냄새.`,
        dieText:`우편칸 자루가 하나 늘었다.<br><br>꼬리표의 받는 사람 칸은 여전히 비어 있다.<br>보내는 사람 칸에 이름이 하나 적혔다.` },
      win:{ exp:24, dream:3 } },
    { l:'② 자루를 끌어내려 문까지 뚫는다.', k:'break', dc:21,
      ok:`자루를 하나씩 끌어내렸다. 무겁다. 편지 무게가 아니다.<br><br>문까지 뚫었다.<br>마지막 자루를 내릴 때 안에서 무언가 바스락댔다. 열어 보지 않았다.`,
      ng:`끌어내린 자루 무게에 더미가 무너졌다. 어깨까지 묻혔다.<br><br>일행이 파냈다. 파내는 동안 자루 하나가 계속 꿈틀거렸다.<br>아무도 그 자루를 건드리지 않았다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-28, spirit:-14 } }
  ] },

{ at:'B', t:'돌아가는 길 — 바뀐 복도',
  x:`왔던 길로 돌아간다. 분명 이 복도다.<br><br>
    그런데 문이 하나 많다. 벽 색이 조금 다르다.<br>
    누가 바꿨다. 아니면 처음부터 잘못 기억했다.<br><br>
    탐험가는 제 기억을 먼저 의심하지 않는다. 그게 이 일의 밑천이다.`,
  o:[
    { l:'① 늘어난 문 하나를 짚어 본다.', k:'sense', dc:21,
      ok:`문 하나만 문틀에 먼지가 없다. 새로 단 문이다. 아니, 새로 세운 벽이다. 두드리자 속이 빈다. 합판이다.<br><br>합판을 발로 밀었다. 뒤에 원래 복도가 있다. 기억하던 그 복도다.<br>누가 길을 막고 문을 그려 놓았다.<br><br>막은 자리 뒤에 망치 하나가 놓여 있다. 손잡이가 아직 젖었다.`,
      ng:`문을 짚는 순간 문이 안에서 열렸다.<br><br>방 안은 어둡다. 의자에 누가 앉아 있다. 이쪽을 보고.<br>문을 닫았다. 손잡이가 안에서 돌아간다. 붙잡고 버티다 손목을 삐었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-22, mind:-16 } },
    { l:'② 일행 기억을 모아 길을 다시 맞춘다.', k:'fix', dc:20,
      ok:`각자 기억하는 것을 하나씩 말하게 했다. 소화전. 깨진 타일. 꺼진 형광등 둘.<br><br>맞춰 보니 바뀐 건 문 하나뿐이다. 나머지는 그대로다.<br>그 문만 피해 걸었다. 지나며 보니 그 문에는 손잡이가 바깥쪽에만 있다.`,
      ng:`다 다르게 기억한다. 누구는 소화전이 왼쪽, 누구는 오른쪽.<br><br>다투는 사이 시간이 갔다.<br>복도 끝 형광등이 하나씩 꺼지며 이쪽으로 온다.`,
      win:{ exp:14, dream:1 }, lose:{ mind:-18, spirit:-14 } }
  ] },

{ at:'B', t:'처지는 일행 — 앞장선 자리',
  x:`일행 하나가 다리를 전다. 아까 계단에서 접질렸다.<br><br>
    뒤에서 오는 것은 다리를 절지 않는다.<br>
    앞장선 사람이 길을 고른다. 빠른 길과 다친 사람이 갈 수 있는 길은 다르다.<br><br>
    탐험가는 둘 다를 셈한다.`,
  o:[
    { l:'① 다친 걸음으로도 닿는 길을 고른다.', k:'sense', dc:21,
      ok:`계단이 없는 길. 문이 무겁지 않은 길. 숨을 데가 셋은 있는 길. 지나온 데를 머릿속에서 하나씩 걸러 냈다.<br><br>하나가 남는다. 돌아가는 길이다. 멀다. 하지만 다 같이 닿는다.<br>그 길로 갔다. 다친 일행이 숨을 데마다 한 번씩 쉬었다. 뒤의 것은 빠른 길로 앞질러 갔다. 그 길 끝에서 기다리려고.<br><br>제 다리가 아니라 가장 느린 다리로 길을 골랐다. 셈이 넓어졌다. 이제 일행 걸음이 전부 셈에 들어온다.`,
      ng:`돌아가는 길을 골랐다. 너무 멀었다.<br><br>중간에 다친 일행이 주저앉았다. 업었다. 업은 채로 계단을 만났다. 기억에 없던 계단이다.<br>무릎이 꺾였다. 둘이 같이 굴렀다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-26, mind:-14 }, wake:1 },
    { l:'② 다친 사람을 부축해 빠른 길로 간다.', k:'bond', dc:21,
      ok:`어깨를 받쳤다. 셋째 걸음부터 박자가 맞았다.<br><br>빠른 길로 갔다. 빨리 닿았다.<br>닿은 문 앞에서 뒤를 봤다. 아무것도 따라오지 않았다. 아직은.`,
      ng:`박자가 안 맞는다. 둘이 같이 넘어졌다.<br><br>일으키는 사이 뒤에서 발소리가 모퉁이를 돌았다.<br>끌다시피 해서 문을 넘었다. 허리가 끊어질 것 같다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-24, spirit:-14 } },
    { l:'③ 시간을 들여 발목을 단단히 묶는다.', k:'heal', dc:20,
      ok:`천을 찢어 발목을 감았다. 단단히. 다친 일행이 일어선다. 덜 전다.<br><br>시간을 썼다. 그만큼 뒤의 것이 가까워졌다.<br>그래도 서는 다리가 하나 늘었다.`,
      ng:`감는 사이 발소리가 모퉁이까지 왔다.<br><br>다 감지 못하고 일으켰다. 매듭이 풀리며 일행이 다시 넘어졌다.<br>그 위로 엎드려 숨을 죽였다. 발소리가 바로 옆을 지나갔다.`,
      win:{ exp:14, dream:1, hp:8 }, lose:{ mind:-16, spirit:-14 } }
  ] },

{ at:'B', t:'마지막 갈림길 — 멈춘 벽시계',
  x:`복도 벽시계가 멈춰 있다. 네 시 사십 분.<br><br>
    거의 다 왔다는 뜻이다. 아니면 이미 늦었다는 뜻이다.<br>
    길이 둘이다. 하나는 아래로, 하나는 바깥 벽을 따라.<br><br>
    두 길 앞에서 공기를 맡았다.`,
  o:[
    { l:'① 비 냄새가 짙은 쪽을 고른다.', k:'sense', dc:21,
      ok:`아래쪽 길은 기름 냄새. 바깥 벽 길은 비 냄새. 비 냄새가 짙을수록 바깥이 가깝다.<br><br>그쪽으로 갔다. 창 하나가 열린다. 비가 쏟아져 들어온다. 창밖 철제 계단이 아래로 이어진다.<br>계단 첫 칸에 젖은 성냥개비가 하나 떨어져 있다.<br><br>타다 만 끝에서 아직 연기가 난다.`,
      ng:`비 냄새를 따랐다. 창은 열렸다. 계단이 없다. 창밖은 허공이다.<br><br>되돌아오는 사이 아래쪽 길에서 발소리가 올라왔다.<br>숨을 데를 찾다 문틈에 손가락이 끼었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, mind:-14 } },
    { l:'② 시계를 떼어 뒤를 본다.', k:'luck', dc:21,
      ok:`시계를 떼었다. 뒤 벽에 구멍이 파였다.<br><br>안에 기름종이 꾸러미가 있다. 말린 고기와 쪽지.<br>쪽지에 한 줄. 『아래로 가지 마.』 글씨가 반듯하다. 너무 반듯하다.`,
      ng:`시계를 떼자 초침이 움직이기 시작했다. 째깍. 째깍.<br><br>복도 어딘가에서 같은 소리가 따라 한다. 시계는 여기 하나뿐이다.<br>소리는 이쪽으로 걸어온다.`,
      win:{ exp:14, dream:1, item:'말린 고기' }, lose:{ mind:-16, spirit:-18 } }
  ] }
]);

// ------------------------------------------
// 사수 (marksman) · 자원: 무력
// ------------------------------------------
kJob('marksman', 'B', [
{ at:'B', t:'빗속 — 젖은 시위',
  x:`비가 그치지 않는다. 시위가 젖었다. 젖은 시위는 늘어지고, 늘어진 시위는 화살을 아래로 떨군다.<br><br>
    골목 끝에 가로등 하나. 그 밑에 우산 쓴 사람이 서 있다. 이쪽을 기다린다.<br>
    골목을 빠지려면 그 앞을 지나야 한다.<br><br>
    사수는 품 안에 마른 시위 하나를 넣어 두었다. 이런 밤을 위해.`,
  o:[
    { l:'① 마른 시위로 갈아 끼우고 한 발만 쏜다.', k:'sense', dc:21,
      ok:`처마 밑에서 시위를 갈았다. 손이 젖지 않게 소매로 감쌌다.<br><br>우산을 겨누지 않았다. 가로등을 겨눴다. 놓았다. 유리가 깨지고 골목이 꺼진다.<br>어둠 속에서 우산이 두리번거린다. 그 옆을 일행이 지났다. 아무도 숨소리를 내지 않았다.<br><br>사람이 아니라 불을 쏘았다. 무엇을 맞히느냐가 맞히는 것보다 먼저다. 손이 그 순서를 알고 시위를 당겼다.`,
      ng:`갈아 끼우는데 손가락이 곱았다. 시위가 튕겨 나가 웅덩이에 빠졌다.<br><br>건져 올렸을 때는 다 젖었다. 우산이 이쪽으로 돌아섰다. 천천히 걸어온다.<br>골목을 되돌아 뛰다 발목이 꺾였다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-24, mind:-12 }, wake:1 },
    { l:'② 무력으로 젖은 활을 끝까지 당긴다.', k:'break', dc:21, cost:{ might:22 },
      ok:`늘어진 시위를 팔 힘으로 버텼다. 끝까지. 화살이 처지는 만큼 위를 겨눴다.<br><br>우산이 꿰뚫려 날아갔다. 우산 밑 사람이 처음으로 움찔했다.<br>그 한 박자에 골목을 빠졌다.`,
      ng:`당기다 시위가 끊어졌다. 끊어진 끝이 뺨을 갈랐다.<br><br>우산이 소리 없이 다가온다.<br>활을 거꾸로 쥐고 뒷걸음질 쳤다. 피가 빗물에 섞여 턱으로 흐른다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-26, spirit:-12 } }
  ] },

{ at:'B1', t:'컨테이너 야적장 — 크레인 탐조등',
  x:`크레인 꼭대기 탐조등이 돈다. 불빛이 컨테이너 골목을 하나씩 훑는다.<br><br>
    불빛이 닿는 자리마다 호루라기가 운다. 노란 비옷들이 그쪽으로 몰린다.<br>
    탐조등까지는 백 걸음이 넘는다. 비가 옆으로 친다.<br><br>
    불빛이 도는 박자를 셌다.`,
  o:[
    { l:'① 불빛이 이쪽을 향하는 박자에 전구를 쏜다.', k:'sense', dc:22,
      ok:`한 바퀴에 스무 박자. 불빛이 이쪽을 볼 때 전구가 가장 크다. 눈부심 한가운데를 겨눴다.<br><br>눈을 감고 놓았다. 박자로 쏜 것이다. 퍽. 불빛이 꺼졌다. 야적장이 통째로 어두워졌다.<br>호루라기가 사방에서 운다. 어디를 비춰야 할지 모르는 소리다.<br><br>눈부신 것을 보지 않고 박자를 봤다. 보이는 것만 쏘던 손이 셈으로도 쏜다.`,
      ng:`박자는 맞았는데 빗줄기가 화살을 밀었다. 화살이 크레인 철골에 맞아 튕겼다.<br><br>불빛이 멈춘다. 이쪽에서. 눈이 하얘진다.<br>호루라기가 울고 발소리가 몰려온다. 컨테이너 사이로 굴러 들어가다 무릎을 찧었다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-24, mind:-14 }, wake:1 },
    { l:'② 불빛 뒤 어둠을 타고 크레인 밑까지 뛴다.', k:'evade', dc:21,
      ok:`불빛이 지나간 자리를 따라 뛰었다. 불빛 등 뒤가 가장 어둡다.<br><br>크레인 밑에 닿았다. 철골 그늘에 노란 비옷 하나가 앉아 졸고 있다.<br>그 옆을 지났다. 비옷 주머니에서 무전기가 지직거린다. 아무도 대답하지 않는다.`,
      ng:`불빛이 거꾸로 돌았다. 정면으로.<br><br>멈추지 못하고 뛰었다. 등 뒤에서 호루라기.<br>젖은 철판에 발이 미끄러져 옆구리를 컨테이너 모서리에 박았다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-26, spirit:-12 } }
  ] },

{ at:'B2', t:'간호사실 — 유리 너머 열쇠',
  x:`간호사실 유리창 너머 벽에 열쇠꾸러미가 걸려 있다. 못 하나에.<br><br>
    유리창 가운데 말하는 구멍이 뚫렸다. 동전만 하다. 화살 하나는 지난다.<br>
    간호사실 안에 아무도 없다. 의자가 아직 천천히 돈다.<br><br>
    구멍에서 못까지 일곱 걸음. 못에서 책상까지 한 뼘.`,
  o:[
    { l:'① 구멍으로 화살을 넣어 열쇠고리를 못에서 떨군다.', k:'sense', dc:22,
      ok:`구멍 가장자리를 스치면 끝이다. 숨을 다 뱉고 멈춘 자리에서 놓았다.<br><br>화살이 구멍을 지나 열쇠고리 안쪽을 쳤다. 꾸러미가 못에서 벗겨진다. 책상에 떨어져 미끄러지다 서류 구멍 앞에서 멈췄다.<br>손을 넣어 끌어냈다. 열쇠 하나에 『계단』이라고 적혀 있다.<br><br>책상 위 점검표가 보인다. 오늘 밤 인원 칸에 볼펜으로 고친 숫자. 고친 자리가 아직 번들거린다.`,
      ng:`화살이 구멍 가장자리를 스쳤다. 유리에 금이 간다.<br><br>금 가는 소리가 복도에 퍼졌다. 복도 끝에서 딸깍 소리가 멎었다.<br>그리고 이쪽으로 다시 시작한다. 딸깍, 딸깍.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-16, spirit:-16 } },
    { l:'② 무력으로 유리를 깨고 손을 넣는다.', k:'break', dc:21, cost:{ might:24 },
      ok:`활 끝으로 유리 모서리를 찍었다. 한 번에 금이 갔다. 두 번에 깨졌다.<br><br>팔을 넣어 열쇠를 낚았다. 소리가 컸다.<br>복도 끝에서 발소리가 뛰기 시작했을 때 이쪽은 이미 계단 문 앞이었다.`,
      ng:`깨진 유리가 팔뚝을 그었다. 길게.<br><br>열쇠를 낚기 전에 복도 불이 켜졌다.<br>팔을 빼며 유리에 한 번 더 베였다. 소매가 다 젖었다. 비가 아니다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-28, mind:-12 } }
  ] },

{ at:'B3', t:'식당칸 — 등을 돌린 빨간 외투',
  x:`식당칸 끝 통로에 빨간 외투가 서 있다. 이쪽을 등지고.<br><br>
    얼굴을 바꾸는 손님이 저 외투를 입었다는 말이 돌았다. 확실하지는 않다.<br>
    열차가 흔들린다. 이음매를 넘을 때마다 덜컹. 식탁 위 유리잔이 같이 운다.<br><br>
    앞 칸으로 가려면 그 옆을 지나야 한다.`,
  o:[
    { l:'① 덜컹임 사이 반 박자에 외투 자락을 벽에 꿴다.', k:'sense', dc:22,
      ok:`덜컹과 덜컹 사이에 고요가 있다. 반 박자. 그 반 박자에 놓았다.<br><br>화살이 외투 자락을 벽판에 꿰었다. 빨간 외투가 움직이지 못한다. 돌아보지도 않는다.<br>일행이 그 옆을 지났다. 지나며 보니 외투 안이 비었다. 옷걸이도 없이 외투만 서 있었다. 소매 끝에서 물이 떨어진다.<br><br>흔들리는 바닥에서 흔들리지 않는 반 박자를 찾았다. 바닥이 흔들려도 이제 손은 그 반 박자 위에 선다.`,
      ng:`덜컹. 화살이 빗나가 창에 박혔다. 창에 금이 간다.<br><br>빨간 외투가 천천히 돌아본다.<br>얼굴이 일행 중 하나의 얼굴이다. 그 일행은 지금 이쪽 바로 뒤에 서 있다.`,
      win:{ exp:23, dream:3 }, lose:{ mind:-18, spirit:-18 }, wake:1 },
    { l:'② 쏘기 전에 외투 발밑을 본다.', k:'gaze', dc:21,
      ok:`다들 젖었다. 비를 맞고 탔으니까. 외투 발밑만 말라 있다.<br><br>처음부터 안에 있던 것이다. 활을 내리지 않은 채 식탁 사이로 돌아갔다.<br>외투는 끝내 돌아보지 않았다. 돌아볼 필요가 없다는 듯이.`,
      ng:`발밑을 보려고 고개를 숙였다. 그 사이 외투가 한 걸음 가까워졌다.<br><br>다시 고개를 들었을 때 외투는 등을 돌린 채 바로 앞에 있다.<br>숨 냄새가 났다. 앞에서가 아니라 뒤에서.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-16, spirit:-20 } },
    { l:'③ 활을 내리고 식탁 밑으로 기어 지난다.', k:'steady', dc:20,
      ok:`식탁보가 바닥까지 내려와 있다. 그 밑으로 기었다.<br><br>빨간 외투 신발 앞을 지났다. 신발 끈이 젖지 않았다.<br>마지막 식탁 밑에 접시 하나가 떨어져 있다. 산나물 무침이 반쯤 남았다. 손수건에 싸서 챙겼다.`,
      ng:`식탁 밑을 기는데 열차가 크게 흔들렸다. 유리잔이 쏟아져 내린다.<br><br>손바닥에 유리 조각이 박혔다.<br>식탁보가 들리고 누가 아래를 들여다본다. 얼굴은 안 보인다. 빨간 소매만.`,
      win:{ exp:14, dream:1, item:'산나물' }, lose:{ hp:-24, spirit:-14 } }
  ] },

{ at:'B', t:'화살통 — 셋 남았다',
  x:`화살통을 셌다. 셋.<br><br>
    들어올 때는 열둘이었다. 아홉은 이 건물 어딘가에 박혀 있다.<br>
    밤은 아직 길다.<br><br>
    사수는 쏜 화살이 어디에 떨어졌는지 다 기억한다.`,
  o:[
    { l:'① 쏜 각도를 되짚어 화살을 찾으러 간다.', k:'sense', dc:20,
      ok:`문틀 위, 계단 난간 밑, 창틀 틈. 쏜 자리와 각도를 하나씩 되짚었다.<br><br>다섯을 되찾았다. 화살통이 다시 무거워졌다.<br>여섯째 화살이 있어야 할 자리에 화살이 없다. 구멍만 있다. 누가 뽑아 갔다. 깃털 하나가 떨어져 있다.`,
      ng:`첫 자리에 갔더니 화살이 뽑혀 있다. 둘째 자리도.<br><br>셋째 자리에 화살이 꽂혀 있다. 거꾸로. 촉이 이쪽을 향해.<br>뽑으려다 손을 베였다. 촉에 무언가 발라져 있다. 손끝이 오래 저렸다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-22, mind:-14 } },
    { l:'② 버려진 우산살을 꺾어 화살을 깎는다.', k:'fix', dc:21,
      ok:`복도에 우산이 버려져 있다. 살을 뽑아 곧게 폈다. 끝을 바닥에 갈았다.<br><br>깃은 없다. 멀리는 못 간다. 열 걸음이면 충분하다.<br>넷을 만들었다. 손에 익은 화살보다 가볍다. 셈을 다시 했다.`,
      ng:`살이 휜다. 펴면 다시 휜다.<br><br>갈던 끝이 미끄러져 손바닥을 찔렀다.<br>하나도 못 만들고 시간만 썼다. 복도 끝에서 문 하나가 열렸다 닫혔다.`,
      win:{ exp:14, dream:1 }, lose:{ hp:-22, spirit:-12 } }
  ] },

{ at:'B1', t:'경매장 — 2층 난간의 갈고리 장대',
  x:`경매장 2층 난간에 노란 비옷 하나가 서 있다. 긴 장대를 들었다. 끝에 갈고리.<br><br>
    아래를 지나는 상자를 걸어 올린다. 하나씩. 무엇이든.<br>
    일행이 그 아래를 지나야 출구다.<br><br>
    난간까지 서른 걸음. 비옷은 아래만 본다.`,
  o:[
    { l:'① 장대를 쥔 손등을 쏜다.', k:'sense', dc:22,
      ok:`장대가 내려오는 순간이 아니라 올라가는 순간을 기다렸다. 올라갈 때 손에 힘이 다 들어간다.<br><br>놓았다. 화살이 손등을 스치고 난간 기둥에 박혔다. 장대가 미끄러져 떨어진다. 아래 얼음 더미에 꽂혔다.<br>비옷이 손을 감싸 쥐고 주저앉았다. 그 사이 일행이 다 지났다.<br><br>얼음 더미 옆에 깨진 상자가 있다. 언 짐승 고기가 쏟아져 있다. 한 덩이를 집었다.`,
      doom:{ title:'갈고리 장대', what:'갈고리 장대에 걸려 끌려 올라갑니다', dc:17, sec:55,
        text:`화살이 장대에 맞고 튕겼다. 비옷이 고개를 든다. 이쪽을 본다.<br><br>장대가 내려온다. 빠르다. 갈고리가 외투 깃에 걸렸다.<br>몸이 들린다. 발이 바닥을 놓친다. 얼음 더미가 멀어진다.<br><br>깃이 목을 조인다. 난간이 가까워진다. 난간 너머에 비옷이 셋이다.`,
        dieText:`경매판에 분필로 새 줄이 적혔다. 번호 하나, 무게, 낙찰.<br><br>낙찰가 칸은 비었다.<br>갈고리 장대는 다시 아래로 내려와 다음 것을 기다렸다.` },
      win:{ exp:24, dream:3, item:'짐승 고기' } },
    { l:'② 무력으로 천장 조명 줄을 쏘아 떨군다.', k:'break', dc:21, cost:{ might:24 },
      ok:`난간 위 천장에 큰 조명이 사슬에 매달렸다. 사슬 고리 하나가 녹슬었다.<br><br>끝까지 당겨 그 고리를 쳤다. 조명이 기울며 난간을 덮친다. 비옷이 장대를 놓고 엎드렸다.<br>경매장 절반이 어두워졌다. 어둠 쪽으로 일행을 이끌었다.`,
      ng:`고리가 버텼다. 화살이 사슬에 맞고 튕겨 아래로 떨어졌다.<br><br>쨍 소리. 비옷들이 다 고개를 든다.<br>장대가 이쪽으로 휘둘러졌다. 피하다 수조 모서리에 옆구리를 박았다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-28, mind:-12 } }
  ] },

{ at:'B2', t:'처치실 복도 — 깜빡이는 형광등',
  x:`복도 형광등 하나가 깜빡인다. 켜졌다, 꺼졌다.<br><br>
    복도 끝에 흰 옷이 서 있다. 불이 켜질 때마다 한 걸음씩 가까워져 있다.<br>
    불이 켜져 있는 동안에는 움직이지 않는다.<br><br>
    깜빡이는 박자를 셌다. 박자가 고르지 않다.`,
  o:[
    { l:'① 불이 켜질 때마다 그것을 겨누며 뒷걸음질 친다.', k:'sense', dc:21,
      ok:`켜짐. 겨눔. 꺼짐. 한 걸음 뒤로. 켜짐. 겨눔.<br><br>화살 끝이 그것의 가슴을 겨누고 있는 동안 그것은 거리를 줄이지 못했다. 박자가 흐트러져도 겨눔은 흐트러지지 않았다.<br>등에 문이 닿았다. 일행이 문을 열었다. 넘어서 닫았다.<br><br>문 너머에서 불이 한 번 더 켜졌다. 유리창에 손바닥이 하나 찍혔다.`,
      ng:`셋째 박자가 길었다. 꺼진 채로 오래.<br><br>불이 켜졌을 때 그것은 바로 앞에 있었다. 흰 마스크. 웃는 눈.<br>뒤로 넘어지며 활이 손에서 떨어졌다. 다시 꺼졌다. 기어서 문을 찾았다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-18, spirit:-16 } },
    { l:'② 불이 꺼질 때 처치실 커튼 뒤로 숨는다.', k:'hide', dc:21,
      ok:`꺼지는 순간 커튼 뒤로 들어갔다. 침대 하나. 비어 있다.<br><br>숨을 죽였다. 커튼 밑으로 흰 신발이 지나간다. 한 박자에 한 걸음.<br>지나갔다. 침대 옆 수납장에 약초 뭉치가 든 거즈 봉지가 있다. 챙겼다.`,
      ng:`커튼 뒤 침대가 비어 있지 않았다. 누가 누워 있다. 시트를 머리까지 덮고.<br><br>시트가 숨에 맞춰 오르내린다. 이쪽 숨에 맞춰서.<br>뛰쳐나오다 커튼 봉을 쓰러뜨렸다. 쇠 소리가 복도를 울렸다.`,
      win:{ exp:14, dream:1, item:'약초 뭉치' }, lose:{ hp:-20, spirit:-18 } }
  ] },

{ at:'B3', t:'지붕 위 — 앞에서 기는 사람',
  x:`객차 지붕 위다. 맞바람이 분다. 비가 바늘처럼 박힌다.<br><br>
    앞 칸 지붕에 누가 엎드려 기어간다. 기관실 쪽으로. 이쪽보다 먼저.<br>
    저것이 먼저 닿으면 앞쪽 사다리를 걷어찰 것이다.<br><br>
    맞바람은 화살을 되돌려 보낸다. 거리는 스무 걸음.`,
  o:[
    { l:'① 바람이 숨을 고르는 순간 손 앞 철판을 쏜다.', k:'sense', dc:22,
      ok:`맞바람에도 결이 있다. 객차가 굽은 길에 들어서면 바람이 옆으로 비낀다. 그때 반 박자 잦아든다.<br><br>그 반 박자에 놓았다. 화살이 그것의 손 바로 앞 철판에 박혔다. 손이 멈춘다.<br>그것이 고개를 돌린다. 이쪽 얼굴이다. 이쪽 얼굴을 하고 이쪽을 본다.<br><br>그리고 객차 틈으로 미끄러져 사라졌다. 바람을 거스르지 않고 바람을 기다렸다. 기다리는 동안 활은 한 번도 흔들리지 않았다.`,
      ng:`잦아든다 싶어 놓았는데 바람이 다시 몰아쳤다. 화살이 되밀려 와 어깨를 스쳤다.<br><br>앞의 것이 돌아보지도 않고 계속 긴다.<br>뒤쫓다 철판에 미끄러져 지붕 끝에 매달렸다. 손톱이 들렸다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-26, mind:-12 }, wake:1 },
    { l:'② 활을 등에 메고 엎드려 바람을 버티며 기어간다.', k:'steady', dc:21,
      ok:`활을 등에 묶었다. 철판 이음매를 손가락으로 걸며 기었다.<br><br>앞의 것보다 늦었다. 그러나 사다리는 그대로 있다. 걷어차지 않았다.<br>사다리 첫 칸에 젖은 손자국이 있다. 손가락이 하나 많다.`,
      ng:`바람이 몸을 들었다. 한순간 지붕에서 떴다.<br><br>떨어지며 환기구 덮개를 잡았다. 덮개가 휘었다. 버텼다.<br>정신을 차렸을 때 앞의 것은 보이지 않는다. 사다리 쪽에서 쇠 부딪는 소리가 났다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-28, spirit:-12 } }
  ] },

{ at:'B', t:'추격 — 돌아서서 한 발',
  x:`쫓긴다. 계단을 둘 내려왔다. 발소리가 계속 붙어 온다.<br><br>
    일행이 숨이 찬다. 다음 계단참에서 누군가 넘어질 것이다.<br>
    돌아서서 쏘면 멈출지도 모른다. 멈추지 않을지도 모른다.<br><br>
    돌아서는 데 한 박자. 겨누는 데 한 박자. 그 두 박자가 다다.`,
  o:[
    { l:'① 계단참에서 돌아서서 발소리 높이로 쏜다.', k:'sense', dc:22,
      ok:`발소리는 계단 위쪽 난간에서 난다. 무겁다. 키가 크다. 눈높이를 셈했다.<br><br>돌아서는 동안 이미 겨눴다. 모퉁이에 그것이 나타나는 순간 놓았다.<br>화살이 그것의 어깨를 벽에 꿰었다. 그것이 비명을 지르지 않는다. 화살을 뽑으려고 천천히 손을 든다.<br><br>그 사이 두 층을 더 내려왔다. 발소리는 다시 붙지 않았다.`,
      doom:{ title:'모퉁이의 그것', what:'쫓아온 것에게 붙잡혀 끌려갑니다', dc:17, sec:50,
        text:`돌아섰다. 겨눴다. 모퉁이에 아무것도 없다.<br><br>발소리는 계단 위가 아니라 난간 바깥쪽, 계단통 빈 데에서 났던 것이다.<br>난간 너머로 긴 팔이 들어온다. 활을 쥔 손목을 잡는다.<br><br>당긴다. 난간이 허리에 걸린다. 발이 뜬다.`,
        dieText:`일행이 계단참에 닿았을 때 화살 하나가 떨어져 있었다.<br><br>계단통 아래로 무언가 오래 끌려가는 소리가 났다. 층마다 한 번씩 난간을 치며.<br>소리는 맨 아래층에서 멎었다.` },
      win:{ exp:24, dream:3 } },
    { l:'② 쏘지 않고 계단을 세 칸씩 뛰어 내린다.', k:'evade', dc:21,
      ok:`세 칸씩 뛰었다. 무릎이 비명을 지른다. 멈추지 않았다.<br><br>맨 아래 문을 열고 빗속으로 나왔다. 처마 밑에 붙었다.<br>문 안쪽 유리창에 그것이 와 섰다. 문을 열지 않는다. 비를 싫어한다.`,
      ng:`셋째 계단참에서 발을 헛디뎠다. 다섯 칸을 굴렀다.<br><br>활이 등 밑에 깔렸다. 활대에 금이 갔다.<br>일어났을 때 발소리가 한 층 위에 있다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-30, mind:-12 } },
    { l:'③ 일행을 먼저 보내고 계단참에서 막아선다.', k:'bond', dc:21,
      ok:`일행을 아래로 밀었다. 계단참에 서서 위를 겨눴다. 쏘지는 않았다.<br><br>발소리가 모퉁이 직전에서 멈춘다. 겨눈 화살 끝을 아는 것이다.<br>한참을 그렇게 서 있었다. 아래에서 일행이 문을 열었다는 신호가 왔다. 그때 뒷걸음질로 내려갔다.`,
      ng:`겨누고 서 있는데 발소리가 멈추지 않았다.<br><br>모퉁이에서 그것이 아니라 소화기가 굴러 내려왔다. 정강이를 쳤다.<br>넘어진 채 계단을 구르듯 내려와 일행에게 끌려 나갔다.`,
      win:{ exp:16, dream:2, mind:6 }, lose:{ hp:-26, spirit:-14 } }
  ] },

{ at:'B', t:'젖은 길바닥 — 거꾸로 비친 네온',
  x:`건물 사이 골목을 건너야 한다. 길바닥이 젖어 거울이 됐다.<br><br>
    웅덩이마다 네온이 거꾸로 비친다. 빨강, 초록. 『여관』의 『관』이 꺼졌다 켜진다.<br>
    위를 보면 어둡다. 아래를 보면 다 보인다.<br><br>
    웅덩이 속 비상계단에 사람 하나가 서 있다. 위를 보면 안 보이는 자리다.`,
  o:[
    { l:'① 웅덩이에 비친 자리를 보고 위를 쏜다.', k:'sense', dc:21,
      ok:`비친 것은 거꾸로다. 웅덩이 속 계단참이 세 칸 아래면 실제로는 세 칸 위다.<br><br>웅덩이를 보면서 위로 겨눴다. 그가 든 손전등을 쏘았다. 불빛이 꺼지고 손전등이 계단을 굴러 떨어진다.<br>그가 더듬는 사이 골목을 건넜다.<br><br>건너편 처마 밑에서 웅덩이를 다시 봤다. 계단참이 비어 있다. 그는 이미 내려오고 있었다.`,
      ng:`거꾸로 셈하다 한 칸을 틀렸다. 화살이 난간에 맞아 불꽃이 튀었다.<br><br>웅덩이 속에서 그가 이쪽을 내려다본다.<br>위에서 불빛이 쏟아진다. 골목을 뛰어 건너다 넘어져 손바닥이 다 갈렸다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, mind:-14 } },
    { l:'② 웅덩이에 비치지 않게 처마 밑을 따라 돈다.', k:'hide', dc:20,
      ok:`위에서 보는 사람은 아래를 보지 않는다. 웅덩이에 비치는 것을 본다.<br><br>웅덩이가 없는 처마 밑만 골라 돌았다. 멀다. 그래도 비치지 않았다.<br>골목 끝 가게 차양 밑에 빈 병이 굴러 있다. 맑은 물이 반쯤 남았다.`,
      ng:`처마가 끊긴 자리에 웅덩이가 넓다. 돌 데가 없다.<br><br>건너는 순간 네온이 켜졌다. 웅덩이에 이쪽이 빨갛게 비쳤다.<br>위에서 무언가 떨어졌다. 화분이다. 어깨를 스쳤다.`,
      win:{ exp:14, dream:1, item:'맑은 물' }, lose:{ hp:-26, spirit:-14 } }
  ] },

{ at:'B1', t:'방파제 수로 — 건너편 말뚝',
  x:`수로가 길을 끊었다. 건너편까지 열다섯 걸음. 물이 검고 빠르다.<br><br>
    건너편 판자길 끝에 말뚝이 박혀 있다. 배를 매던 말뚝이다.<br>
    화살통에 줄 하나를 감아 왔다. 가늘지만 질기다.<br><br>
    바다 쪽에서 해무호 고동이 한 번 운다. 아직 멀다. 가까워지고 있다.`,
  o:[
    { l:'① 줄 맨 화살을 말뚝 밑동에 박는다.', k:'sense', dc:21,
      ok:`줄 무게만큼 화살이 처진다. 바람이 바다 쪽에서 분다. 말뚝 위 한 뼘, 바다 반대쪽 반 뼘을 겨눴다.<br><br>화살이 말뚝 밑동에 박혀 깊이 들어갔다. 당겨 봤다. 버틴다.<br>이쪽 끝을 철기둥에 감았다. 일행이 줄을 잡고 하나씩 건넜다.<br><br>건너편 판자 밑 물속에 무언가 걸려 있다. 생선 자루다. 그 안에서 민물고기 두어 마리가 아직 뛴다. 강어귀에서 잡아 온 것이다.`,
      ng:`화살이 말뚝 옆 판자에 박혔다. 썩은 판자다.<br><br>당기자 판자가 통째로 뜯겨 물에 떨어졌다. 줄이 손바닥을 훑고 지나갔다.<br>손바닥에서 피가 난다. 줄은 물살에 끌려 사라졌다.`,
      win:{ exp:18, dream:2, item:'민물고기' }, lose:{ hp:-24, mind:-12 } },
    { l:'② 무력으로 줄을 팽팽히 당겨 매고 매달려 건넌다.', k:'steady', dc:21, cost:{ might:22 },
      ok:`화살이 박힌 줄을 온 힘으로 당겨 맸다. 활줄처럼 팽팽해졌다.<br><br>손과 발을 걸고 매달려 건넜다. 아래로 검은 물이 지나간다.<br>건너편에서 일행을 하나씩 받아 냈다. 팔이 저린 채로.`,
      ng:`당기다 줄이 말뚝에서 미끄러졌다. 화살이 빠졌다.<br><br>매달려 있던 몸이 물로 떨어졌다. 무릎까지. 물살이 다리를 당긴다.<br>철기둥을 잡고 겨우 올라왔다. 다리에 감각이 없다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-30, spirit:-12 } }
  ] },

{ at:'B2', t:'기록 보관실 — 창가의 경비원',
  x:`기록 보관실 창가에 경비원이 앉아 있다. 손전등을 무릎에 올렸다.<br><br>
    창밖 약국 간판이 초록으로 깜빡인다. 그 불빛에 경비원 얼굴이 반씩 보였다 사라진다.<br>
    출구 문은 경비원 바로 뒤다. 경비원 옆 벽에 전화가 붙어 있다.<br><br>
    눈은 감겼다. 자는지 모른다. 자는 척인지도.`,
  o:[
    { l:'① 그의 숨이 길어질 때까지 활을 겨누고 기다린다.', k:'sense', dc:21,
      ok:`쏘지 않았다. 겨누고 숨을 셌다. 그의 숨과 이쪽 숨을.<br><br>자는 척하는 사람은 숨이 고르다. 너무 고르다. 정말 잠든 사람은 숨이 한 번씩 길게 끊긴다.<br>열한 번째 숨에 그의 숨이 끊겼다 이어졌다. 그때 일행을 보냈다. 문이 소리 없이 닫혔다.<br><br>쏘지 않고 겨누는 동안 그 사람이 다 보였다. 시위를 당기는 것만 겨누기가 아니었다. 기다림도 화살 하나만큼 팽팽했다.`,
      ng:`숨을 세다 이쪽 숨이 먼저 흐트러졌다. 기침이 터졌다.<br><br>경비원이 눈을 떴다. 손전등을 들지 않는다. 전화기를 든다.<br>수화기 너머에서 누가 대답한다. 이쪽 이름을 부른다.`,
      win:{ exp:23, dream:3 }, lose:{ mind:-18, spirit:-16 }, wake:1 },
    { l:'② 서가 그늘을 따라 바닥을 기어 지난다.', k:'hide', dc:21,
      ok:`서가 그늘을 따라 기었다. 간판이 꺼지는 박자에만 움직였다.<br><br>경비원 의자 다리 옆을 지났다. 신발 끈이 풀려 있다. 묶어 주고 싶은 마음을 눌렀다.<br>문 앞에 닿았다. 등 뒤에서 경비원이 한 번 코를 골았다.`,
      ng:`기다 서가 맨 아래 칸 서류 상자를 건드렸다. 상자가 쏟아졌다.<br><br>경비원이 손전등을 켠다. 불빛이 이쪽 얼굴에서 멈춘다.<br>그가 웃는다. 그리고 다시 손전등을 끈다. 그 웃음이 한참 등 뒤에 붙어 있었다.`,
      win:{ exp:15, dream:2 }, lose:{ mind:-16, spirit:-18 } }
  ] },

{ at:'B3', t:'침대칸 — 부푸는 커튼',
  x:`침대칸 통로 양쪽에 커튼이 줄지어 쳐 있다. 다 닫혔다.<br><br>
    그중 하나가 숨 쉬듯 부풀었다 꺼진다. 창도 닫혔는데.<br>
    커튼 밑으로 신발 한 짝이 나와 있다. 젖은 구두다.<br><br>
    그 앞을 지나야 다음 칸이다.`,
  o:[
    { l:'① 커튼 고리를 쏘아 커튼을 떨군다.', k:'sense', dc:22,
      ok:`커튼은 위에서 고리 여섯 개로 걸렸다. 한가운데 고리를 쏘면 양쪽이 무게로 미끄러진다.<br><br>놓았다. 고리가 튀고 커튼이 주르륵 쏟아져 내렸다.<br>침대 위에 아무도 없다. 외투가 옷걸이에 걸려 있다. 외투 가슴이 오르내린다. 비어 있는데.<br><br>외투가 숨을 멈췄다. 그 사이 다음 칸 문까지 갔다.`,
      doom:{ title:'커튼 안', what:'커튼 안으로 끌려 들어갑니다', dc:17, sec:55,
        text:`화살이 고리를 빗나가 커튼 안으로 들어갔다. 안에서 아무 소리도 안 난다.<br><br>화살을 찾으려 커튼 틈에 손을 넣었다. 손목을 잡혔다.<br>당긴다. 어깨가 들어가고 머리가 들어간다. 커튼이 등 뒤에서 닫힌다.<br><br>안은 침대 하나만큼 좁다. 그런데 끝이 없다.`,
        dieText:`통로 커튼은 다시 다 닫혔다.<br><br>하나가 숨 쉬듯 부풀었다 꺼진다. 커튼 밑으로 신발 두 짝이 나와 있다.<br>하나는 젖은 구두. 하나는 이쪽 신발이다.` },
      win:{ exp:24, dream:3 } },
    { l:'② 화살을 메긴 채 커튼 앞을 천천히 지난다.', k:'steady', dc:21,
      ok:`화살을 메기고 커튼을 겨눈 채 걸었다. 한 걸음에 한 숨.<br><br>부풀던 커튼이 이쪽이 지날 때 부풀지 않았다. 숨을 참은 것이다.<br>다 지나고 나서 뒤에서 큰 숨소리가 났다. 돌아보지 않았다.`,
      ng:`커튼 앞에서 열차가 흔들렸다. 어깨가 커튼을 스쳤다.<br><br>안에서 손가락이 커튼 너머로 이쪽 어깨를 짚는다. 천 한 겹 사이로.<br>뛰쳐나가다 침대 사다리에 정강이를 찧었다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-22, spirit:-18 } }
  ] },

{ at:'B', t:'계단통 — 난간을 짚는 손',
  x:`계단통 가운데가 비었다. 위로 난간이 소용돌이처럼 감겨 올라간다.<br><br>
    한참 위층 난간에 손 하나가 보인다. 난간을 짚으며 내려온다. 한 층, 또 한 층.<br>
    발소리는 들리지 않는다. 손만 내려온다.<br><br>
    손이 한 층을 내려오는 데 걸리는 숨을 셌다.`,
  o:[
    { l:'① 손이 닿을 층을 셈해 먼저 그 층 문을 막는다.', k:'sense', dc:21,
      ok:`한 층에 숨 여섯. 이쪽은 두 층 아래. 손은 열두 숨 뒤에 이 층에 닿는다.<br><br>여섯 숨 만에 일행을 아래층 문으로 빼냈다. 나머지 여섯 숨에 문틈에 화살 하나를 쐐기로 박았다.<br>문 너머에서 손이 문고리를 잡는다. 돌린다. 화살이 버틴다.<br><br>쐐기 박힌 화살이 휜다. 오래는 못 버틸 것이다. 오래 버틸 필요는 없었다.`,
      ng:`숨 여섯이라고 셌다. 손이 갑자기 빨라졌다. 두 층을 한 번에.<br><br>손이 바로 위 난간에 있다. 손가락이 길다. 손톱이 없다.<br>그 손이 난간 너머로 이쪽 머리카락을 쥐었다. 뿌리쳤다. 한 움큼이 남았다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-22, spirit:-18 } },
    { l:'② 무력으로 쏘아 그 소매를 난간에 꿴다.', k:'break', dc:22, cost:{ might:25 },
      ok:`계단통 빈 데로 곧게 위를 겨눴다. 끝까지 당겼다.<br><br>화살이 소매를 꿰어 난간 철봉에 박았다. 손이 멈춘다. 당긴다. 쇠가 운다.<br>그동안 다섯 층을 내려왔다. 위에서 천 찢기는 소리가 났다. 그때는 이미 문밖이었다.`,
      ng:`위로 쏜 화살이 난간에 맞고 튕겨 아래로 떨어졌다.<br><br>쏜 화살이 이쪽으로 되돌아온다. 피하다 계단 모서리에 무릎을 찧었다.<br>위에서 손이 멈췄다. 그리고 이쪽으로 손가락 하나를 까딱였다.`,
      win:{ exp:17, dream:2 }, lose:{ hp:-28, mind:-12 } }
  ] },

{ at:'B1', t:'3번 창고 — 사슬에 매달린 팔레트',
  x:`셔터 밖에서 사슬 푸는 소리가 난다. 누가 들어오려 한다.<br><br>
    셔터 앞 천장에 팔레트 하나가 매달려 있다. 지게차 사슬 고리에 걸쳐 놓았다. 소금 자루가 실렸다.<br>
    고리를 물고 있는 쇠핀 하나가 반쯤 빠져 있다.<br><br>
    핀 머리는 엄지손톱만 하다. 스물두 걸음.`,
  o:[
    { l:'① 쇠핀 머리를 쳐서 팔레트를 셔터 앞에 떨군다.', k:'sense', dc:22,
      ok:`핀은 옆에서 쳐야 빠진다. 정면에서 치면 박힌다. 옆으로 세 걸음 돌아 각을 잡았다.<br><br>셔터가 한 뼘 올라갔다. 고무장화 앞코가 보인다. 놓았다.<br>핀이 튀고 팔레트가 떨어졌다. 소금 자루가 셔터 앞을 막아 쌓인다. 셔터가 거기서 멈췄다.<br><br>사람을 맞히지 않고 사람이 오는 길을 맞혔다. 과녁을 고르는 눈이 한 칸 넓어졌다. 이제 쏠 수 있는 것이 전부 과녁이다.`,
      ng:`정면에서 쳤다. 핀이 더 깊이 박혔다.<br><br>셔터가 무릎 높이까지 올라왔다. 고무장화가 들어온다.<br>상자 뒤로 몸을 던졌다. 손등이 상자 못에 찢겼다.`,
      win:{ exp:24, dream:3, item:'소금 덩이' }, lose:{ hp:-26, mind:-14 }, wake:1 },
    { l:'② 지게차 사슬을 풀어 팔레트를 직접 내린다.', k:'fix', dc:21,
      ok:`지게차 운전석에 올라 사슬 걸쇠를 풀었다. 팔레트가 천천히 내려온다.<br><br>셔터 앞에 딱 맞게 내려앉았다.<br>밖에서 셔터를 들어 올리던 손이 멈춘다. 한참 있다가 사슬 감는 소리가 다시 났다. 다른 데로 돌아가는 소리다.`,
      ng:`걸쇠를 푸는 순간 팔레트가 한쪽으로 기울었다. 소금 자루가 쏟아진다.<br><br>자루 하나가 등을 쳤다. 숨이 막혔다.<br>셔터 밑으로 손전등 불빛이 들어와 쏟아진 자루를 비춘다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-28, spirit:-12 } }
  ] },

{ at:'B2', t:'계단참 — 벽을 보고 선 보호사들',
  x:`계단참에 보호사 넷이 벽을 보고 서 있다. 나란히. 움직이지 않는다.<br><br>
    내려가려면 그 등 뒤를 지나야 한다. 한 사람 지날 틈이다.<br>
    아래층 계단참에 소화기가 하나 놓였다. 금속 통이다.<br><br>
    하나라도 돌아보면 넷이 다 돌아볼 것이다.`,
  o:[
    { l:'① 아래층 소화기를 쏘아 소리로 넷을 돌려세운다.', k:'sense', dc:22,
      ok:`소화기는 아래층, 난간 사이로 반만 보인다. 손잡이 쇠를 노렸다. 몸통을 맞으면 터진다.<br><br>쨍. 손잡이가 울렸다. 넷이 동시에 몸을 돌려 아래를 본다. 등이 이쪽으로 비었다.<br>그 반대편, 위쪽 비상문으로 일행을 이끌었다. 넷은 아래를 보며 천천히 내려간다.<br><br>문을 닫으며 봤다. 넷 중 하나가 이쪽을 돌아보고 있었다. 셋은 아래로, 하나는 위로.`,
      doom:{ title:'벽을 보던 사람들', what:'보호사들에게 붙잡혀 끌려갑니다', dc:17, sec:55,
        text:`화살이 소화기 몸통을 맞혔다. 하얀 가루가 폭발하듯 퍼진다.<br><br>계단통이 하얘졌다. 아무것도 안 보인다. 기침이 터진다.<br>가루 속에서 손이 나온다. 넷 다. 양팔과 양다리를 하나씩 잡는다.<br><br>들려 간다. 발이 계단을 긁는다. 아래로.`,
        dieText:`가루가 가라앉았다. 계단참에 보호사 다섯이 벽을 보고 서 있다.<br><br>나란히. 움직이지 않는다.<br>다섯째의 어깨가 아직 숨차게 오르내린다.` },
      win:{ exp:24, dream:3 } },
    { l:'② 활을 내려놓고 등 뒤를 맨손으로 지난다.', k:'hide', dc:21,
      ok:`활이 벽에 스치면 끝이다. 활을 일행에게 맡기고 맨몸으로 지났다.<br><br>보호사들 등에서 소독약 냄새가 난다. 숨을 쉬지 않는다. 넷 다.<br>다 지나고 손짓해 일행을 불렀다. 활을 돌려받았을 때 손이 떨렸다.`,
      ng:`셋째 보호사 등 뒤에서 옷깃이 스쳤다.<br><br>보호사가 돌아보지 않는다. 대신 벽에 대고 이쪽 이름을 부른다. 낮게.<br>나머지 셋이 따라 부른다. 그 소리가 계단통을 타고 한참 따라 내려왔다.`,
      win:{ exp:15, dream:2 }, lose:{ mind:-18, spirit:-18 } },
    { l:'③ 위층으로 돌아가 다른 계단을 찾는다.', k:'luck', dc:21,
      ok:`돌아섰다. 위층 복도 끝에 화물용 계단이 있다. 문이 잠기지 않았다.<br><br>문 안쪽 손잡이에 쪽지가 감겨 있다. 『여기는 아무도 안 봄.』<br>그리로 내려갔다. 아무도 보지 않았다. 정말로.`,
      ng:`위층 복도에 정각 점검이 돌고 있다. 딸깍, 딸깍.<br><br>계수기 든 간호사가 이쪽 앞에서 멈춘다. 엄지를 누른다.<br>숫자가 하나 올랐다. 계단참 보호사 하나가 벽에서 돌아섰다.`,
      win:{ exp:14, dream:1 }, lose:{ mind:-16, spirit:-16 } }
  ] },

{ at:'B3', t:'탄수차 — 석탄 위의 화부',
  x:`기관실 앞 탄수차다. 석탄이 산처럼 쌓였다. 빗물에 검게 번들거린다.<br><br>
    석탄 더미 위에 화부 하나가 삽을 들고 서 있다. 등불 하나가 그 머리 위 갈고리에 걸렸다.<br>
    기관실 창은 그 너머다.<br><br>
    화부가 삽을 든 채 이쪽을 본다. 얼굴이 등불 그늘에 있다.`,
  o:[
    { l:'① 머리 위 등불을 쏘아 탄수차를 어둡게 한다.', k:'sense', dc:21,
      ok:`등불은 흔들린다. 열차가 흔들리는 박자와 반 박자 어긋나서. 그 어긋남까지 셈에 넣었다.<br><br>등불 유리가 깨졌다. 불이 꺼진다. 석탄 더미가 통째로 검어졌다.<br>화부가 삽을 휘두르는 소리가 허공을 가른다. 그 밑으로 엎드려 석탄을 타고 넘었다.<br><br>기관실 창 아래에 닿았다. 등 뒤에서 삽이 석탄을 치는 소리가 계속 났다. 같은 자리만.`,
      ng:`등불이 반 박자 늦게 흔들렸다. 화살이 등불 고리를 맞고 튕겼다.<br><br>등불이 떨어져 석탄 위에서 깨졌다. 불이 번진다. 작게.<br>화부가 그 불빛 속에서 이쪽을 똑바로 본다. 삽이 날아와 어깨를 쳤다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, mind:-12 } },
    { l:'② 석탄을 걷어차 화부 발밑을 무너뜨린다.', k:'break', dc:22,
      ok:`석탄 더미 밑동을 발로 찼다. 계속. 젖은 석탄이 미끄러진다.<br><br>더미가 무너지며 화부가 아래로 쓸려 내려간다. 삽이 손에서 빠졌다.<br>무너진 자리를 밟고 기관실 창까지 올라갔다. 아래에서 화부가 석탄을 헤치고 일어선다. 서두르지 않는다.`,
      ng:`석탄이 무너지는 쪽이 이쪽이었다.<br><br>쏟아지는 석탄에 다리가 묻혔다. 정강이가 돌에 찍혔다.<br>위에서 화부가 내려다본다. 삽으로 석탄을 한 번 더 퍼서 이쪽으로 끼얹었다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-30, spirit:-12 } }
  ] },

{ at:'B', t:'맞은편 창 — 겨눈 쇠뇌',
  x:`골목 건너 창 하나에 불이 꺼져 있다. 창틀 위로 쇠뇌 끝이 나와 있다.<br><br>
    이쪽을 겨눈다. 일행이 창 앞을 지나면 쏠 것이다.<br>
    사수는 같은 일을 하는 사람을 안다. 겨누는 쪽도 숨을 쉰다.<br><br>
    쇠뇌 끝이 아주 조금 오르내린다.`,
  o:[
    { l:'① 저쪽 숨이 끝나는 순간을 읽고 먼저 몸을 뺀다.', k:'sense', dc:22,
      ok:`쇠뇌 끝이 오른다. 들이쉰다. 내려온다. 내쉰다. 내쉬고 멈춘 자리에서 쏜다. 이쪽도 그렇게 쏜다.<br><br>저쪽이 내쉬기 시작할 때 일행을 창 앞으로 내보냈다. 멈추기 전에 다 지났다.<br>저쪽이 멈췄을 때 창 앞에는 아무도 없었다. 쇠뇌가 철컥 소리만 내고 쏘지 않았다.<br><br>겨누는 사람의 숨이 제 숨처럼 읽혔다. 같은 일을 하는 눈은 서로를 안다. 이제는 이쪽이 먼저 안다.`,
      ng:`숨을 읽었는데 저쪽이 숨을 멈추지 않고 쐈다. 다른 버릇이다.<br><br>화살이 창틀을 맞고 튀어 일행 어깨를 스쳤다.<br>둘째 화살이 메겨지는 소리가 빗소리 사이로 들린다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-24, mind:-14 }, wake:1 },
    { l:'② 무력으로 먼저 쏘아 쇠뇌를 떨군다.', k:'break', dc:21, cost:{ might:24 },
      ok:`쇠뇌 몸통을 겨눴다. 사람 말고. 끝까지 당겼다.<br><br>쇠뇌가 창틀에서 튕겨 나가 골목으로 떨어졌다. 철판 부서지는 소리.<br>창 안에서 누가 웃는다. 낮게. 그리고 창이 닫혔다.`,
      ng:`놓는 순간 저쪽도 놓았다.<br><br>두 화살이 빗속에서 엇갈렸다. 저쪽 것이 허벅지를 스쳤다.<br>이쪽 것은 창틀에 박혔다. 창 안에서 다시 장전하는 소리가 났다.`,
      win:{ exp:17, dream:2 }, lose:{ hp:-30, spirit:-12 } }
  ] },

{ at:'B', t:'마지막 화살',
  x:`화살통에 하나 남았다.<br><br>
    앞에 잠긴 철문. 빗장이 위쪽 고리에 걸쳐 있다. 고리가 헐겁다.<br>
    뒤에서 발소리. 셋. 다 다른 박자.<br><br>
    하나로 무엇을 할지 정해야 한다.`,
  o:[
    { l:'① 마지막 화살로 빗장 고리를 친다.', k:'sense', dc:22,
      ok:`고리는 아래에서 위로 쳐야 빠진다. 무릎을 꿇고 위로 겨눴다.<br><br>숨을 다 뱉었다. 발소리 셋이 모퉁이에 닿기 직전.<br>고리가 튀고 빗장이 떨어졌다. 문이 열린다. 비가 들이친다.<br><br>하나밖에 없을 때 화살통 전부가 그 하나에 실렸다. 남은 수가 줄수록 손이 더 고요해진다. 그게 손에 남았다.`,
      ng:`고리를 맞혔다. 빠지지 않았다. 고리가 휘었을 뿐이다.<br><br>빈 화살통을 등에 지고 문을 어깨로 들이받았다.<br>세 번째에 열렸다. 어깨가 부서질 것 같다. 발소리가 바로 뒤에 있다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-28, mind:-14 }, wake:1 },
    { l:'② 화살을 아끼고 문을 맨손으로 연다.', k:'steady', dc:21,
      ok:`빗장 밑에 어깨를 넣고 들어 올렸다. 무겁다. 이를 악물었다.<br><br>빗장이 고리를 넘었다. 문이 열렸다.<br>화살은 아직 화살통에 있다. 다음 문이 있을 테니까.`,
      ng:`빗장이 들리다 말고 떨어졌다. 손가락이 끼었다.<br><br>빼는 데 한참. 손톱 하나가 까맣게 죽었다.<br>발소리가 모퉁이를 돌았다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-26, spirit:-12 } },
    { l:'③ 뒤쪽 어둠에 그냥 한 발 쏜다.', k:'luck', dc:21,
      ok:`돌아서서 발소리 한가운데로 쏘았다. 겨누지 않고.<br><br>무언가 넘어지는 소리. 발소리 셋이 둘이 됐다. 둘이 서로를 부딪고 멈춘다.<br>그 사이 빗장을 들어 올렸다. 이번엔 손이 빨랐다.`,
      ng:`화살이 벽에 맞는 소리만 났다.<br><br>발소리 셋이 멈추지 않았다. 빈손으로 빗장을 들다 놓쳤다.<br>빗장이 발등에 떨어졌다.`,
      win:{ exp:14, dream:2 }, lose:{ hp:-24, mind:-14 } }
  ] },

{ at:'B', t:'빗속의 사람 — 쏘지 않는다',
  x:`일행이 흩어졌다가 다시 모이는 중이다. 정한 자리로.<br><br>
    빗속에서 사람 하나가 걸어온다. 일행 옷이다. 일행 걸음이다. 거의.<br>
    활이 먼저 올라갔다.<br><br>
    쏘면 끝난다. 틀려도 끝난다.`,
  o:[
    { l:'① 겨눈 채 걸음을 끝까지 본다.', k:'sense', dc:21,
      ok:`쏘지 않았다. 걸음을 봤다. 일행은 오른발을 조금 끈다. 아까 계단에서 다친 발이다.<br><br>빗속의 사람은 왼발을 끈다. 다친 쪽을 거꾸로 흉내 냈다. 거울을 보고 배운 것이다.<br>활을 내리지 않고 뒤로 물러났다. 그것이 걸음을 멈추고 웃었다. 이쪽 일행의 웃음으로.<br><br>진짜 일행은 반대편 골목에서 왔다. 오른발을 끌면서.`,
      ng:`걸음이 맞아 보였다. 활을 내렸다.<br><br>가까이 온 얼굴이 일행 얼굴이다. 눈이 한 박자 늦게 깜박인다.<br>그것이 이쪽 손목을 잡았다. 뿌리쳤을 때 손목에 손가락 자국이 멍으로 남았다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-18, spirit:-18 } },
    { l:'② 일행끼리 정한 신호를 부른다.', k:'bond', dc:20,
      ok:`정해 둔 말이 있다. 묻는 말과 받는 말.<br><br>물었다. 빗속의 사람이 대답하지 않는다. 대신 이쪽이 물은 말을 그대로 따라 한다.<br>그걸로 됐다. 일행을 다른 쪽으로 불러 모았다. 그것은 빗속에 서서 계속 따라 했다.`,
      ng:`신호를 부르자 빗속의 사람이 정확히 받았다.<br><br>안심하고 다가섰다. 등 뒤에서 진짜 일행이 같은 말을 받는 소리가 났다.<br>둘 다 맞게 대답했다. 어느 쪽인지 고르는 사이 둘이 동시에 다가왔다.`,
      win:{ exp:15, dream:2 }, lose:{ mind:-16, spirit:-20 } }
  ] }
]);

// ------------------------------------------
// 추적자 (tracker) · 자원: 무력
// ------------------------------------------
kJob('tracker', 'B', [
{ at:'B', t:'젖은 바닥 — 마르는 발자국',
  x:`복도 바닥에 젖은 발자국이 있다. 일행 것이 아니다. 구두 굽이 좁다.<br><br>
    발자국 가장자리부터 마르고 있다. 가운데만 아직 번들거린다.<br>
    추적자는 쪼그려 앉아 손가락을 댄다.<br><br>
    젖은 것은 얼마나 젖었는지로 시간을 말한다.`,
  o:[
    { l:'① 마른 정도로 얼마 전에 지나갔는지 잰다.', k:'sense', dc:21,
      ok:`가장자리는 말랐다. 가운데는 미지근하다. 이 복도 공기로는 숨 이백이다. 방금이다.<br><br>그리고 발자국마다 앞꿈치보다 뒤꿈치가 덜 말랐다. 뒤로 무게를 실었다. 무언가를 끌고 가는 걸음이다.<br>그쪽으로 가지 않았다. 끄는 것은 무거운 것을 다 끌고 나서 돌아온다.<br><br>마르는 속도가 시계처럼 읽혔다. 바닥이 몇 시인지를 말한다. 그 말을 듣는 귀가 하나 더 생겼다.`,
      ng:`오래됐다고 읽었다. 가장자리가 마른 것은 히터 바람 때문이었다.<br><br>모퉁이를 도니 발자국 주인이 서 있다. 등을 보이고. 바닥에 젖은 자루를 내려놓는 중이다.<br>그가 돌아보기 전에 물러났다. 물러나다 문틀에 어깨를 박았다. 그 소리에 그가 돌아봤다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-22, spirit:-16 }, wake:1 },
    { l:'② 무력으로 발자국이 마르기 전에 따라붙는다.', k:'break', dc:21, cost:{ might:22 },
      ok:`마르기 전에 달렸다. 발자국이 지워지는 속도보다 빨리.<br><br>계단참에서 발자국이 멈춘다. 그 옆에 젖은 열쇠 하나가 떨어져 있다. 서두르다 흘렸다.<br>열쇠를 쥐고 돌아왔다. 숨이 턱까지 찼다.`,
      ng:`달리는 사이 이쪽 발자국이 그 위에 덮였다. 젖은 신발로.<br><br>어느 것이 그의 것인지 모르게 됐다. 이쪽이 이쪽을 쫓고 있었다.<br>멈췄을 때 다리가 후들거리고 아무것도 남지 않았다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-26, mind:-12 } }
  ] },

{ at:'B1', t:'3번 창고 — 대걸레 자국',
  x:`창고 바닥이 한 줄로 깨끗하다. 대걸레 폭만큼.<br><br>
    줄은 상자 사이를 지나 벽 쪽으로 간다. 표백제 냄새가 그 줄에서만 난다.<br>
    여기 사람들은 청소부라고 부른다. 하나도 남기지 않는 사람이다.<br><br>
    남기지 않으려는 사람도 걸레 자국은 남긴다.`,
  o:[
    { l:'① 걸레질 방향으로 청소부의 손과 순서를 읽는다.', k:'sense', dc:22,
      ok:`걸레 결이 오른쪽으로 휘어 있다. 오른손잡이다. 결이 앞으로 겹친다. 뒷걸음질로 닦았다. 닦은 자리를 밟지 않으려고.<br><br>그러니 줄이 시작되는 데가 그가 닦기를 마친 데다. 시작점은 배수구 덮개 앞이다. 거기서 끝내고 그리로 나갔다.<br>그는 지금 아래에 있다. 그리고 다음 줄은 저 상자 더미에서 시작할 것이다. 결이 그쪽으로 기울어 있다.<br><br>상자 더미를 피해 일행을 반대편으로 돌렸다. 쫓는 사람만 읽을 수 있는 게 아니었다. 쫓아오는 사람도 읽힌다. 읽는 손이 앞뒤를 바꿀 줄 알게 됐다.`,
      ng:`결을 거꾸로 읽었다. 시작점이라고 생각한 데로 갔다.<br><br>상자 더미 앞이다. 바닥이 아직 젖었다. 방금 닦았다.<br>상자 너머에서 양동이에 걸레 짜는 소리가 났다. 물방울이 바닥에 떨어진다. 하나, 둘. 그리고 멈췄다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-16, spirit:-18 }, wake:1 },
    { l:'② 깨끗한 줄이 지운 것을 본다.', k:'gaze', dc:21,
      ok:`닦은 줄 가장자리에 걸레가 못 미친 자국이 있다. 고무 굽. 사람 하나 몫이 아니다. 둘.<br><br>하나는 걸어왔다. 하나는 끌려왔다. 끌린 자국 끝에 단추 하나가 박혀 있다.<br>그 단추를 주머니에 넣었다. 누군가는 이 단추를 찾을 것이다.`,
      ng:`들여다보는데 표백제 냄새가 코를 찔렀다. 눈이 따갑다.<br><br>눈물이 쏟아져 한참 못 봤다.<br>다 씻고 봤을 때 이쪽이 쪼그려 앉았던 자리까지 깨끗하게 닦여 있었다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-20, mind:-16 } }
  ] },

{ at:'B2', t:'병동 복도 — 슬리퍼와 구두',
  x:`병동 복도 장판에 자국이 두 가지다.<br><br>
    슬리퍼 자국은 끌린다. 짧고 넓다. 환자 걸음이다.<br>
    구두 자국은 반듯하다. 그런데 구두 자국은 병실 문 앞에서 끝나지 않는다. 벽 앞에서 끝난다.<br><br>
    직원 아닌 직원들은 문으로 다니지 않는다.`,
  o:[
    { l:'① 구두 자국이 끝나는 벽에서 직원 통로를 찾는다.', k:'sense', dc:22,
      ok:`구두 자국은 벽 앞에서 끝나는데 뒤꿈치 자국만 깊다. 거기 서서 무언가를 밀었다.<br><br>벽 밑 걸레받이를 발끝으로 밀었다. 벽판 하나가 안으로 열린다. 좁은 통로다. 배관이 지나간다.<br>안쪽 바닥에 구두 자국이 줄지어 있다. 아래로 내려가는 철계단까지.<br><br>통로 벽에 흰 마스크가 줄지어 걸려 있다. 하나가 비었다.`,
      doom:{ title:'벽 속의 통로', what:'흰 손에 끌려 벽 속으로 들어갑니다', dc:17, sec:55,
        text:`벽판을 밀었다. 열렸다. 안이 캄캄하다.<br><br>한 발 들였다. 안쪽에서 구두 소리가 난다. 반듯하게. 이쪽으로.<br>돌아서는데 손이 어깨를 잡았다. 흰 장갑. 힘이 세다.<br><br>벽판이 등 뒤로 닫힌다. 장판 위 자국이 하나 늘었다. 끝이 벽에 닿는 슬리퍼 자국이.`,
        dieText:`정각이 됐다. 계수기가 딸깍거리며 복도를 돈다.<br><br>숫자가 맞는다. 화이트보드 숫자는 고칠 필요가 없었다.<br>벽판 안에서 구두 소리가 하나 더 늘었다.` },
      win:{ exp:24, dream:3 } },
    { l:'② 슬리퍼 자국을 밟으며 환자 걸음으로 지난다.', k:'hide', dc:21,
      ok:`발을 끌었다. 슬리퍼 자국 위로만. 고개를 숙이고.<br><br>복도 끝에서 흰 옷 하나가 이쪽을 봤다. 오래 보다가 다른 데로 고개를 돌렸다.<br>세는 사람은 걸음으로 센다. 환자 걸음은 환자로 세어진다.`,
      ng:`끌던 발이 한 번 반듯하게 디뎠다. 버릇이다.<br><br>복도 끝 흰 옷이 걸음을 멈췄다. 계수기를 들어 올린다. 누르지 않고 기다린다.<br>이쪽이 다시 발을 끌 때까지. 끝내 누르지 않았다. 그게 더 오래 마음에 걸렸다.`,
      win:{ exp:15, dream:2 }, lose:{ mind:-16, spirit:-18 } }
  ] },

{ at:'B3', t:'통로 카펫 — 눌린 털',
  x:`객차 통로에 카펫이 깔렸다. 낡았다. 털이 길다.<br><br>
    털은 밟히면 눕고, 시간이 지나면 다시 선다.<br>
    지금 누운 털이 한 줄로 이어진다. 앞 칸으로.<br><br>
    젖은 신발도 마른 신발도 털은 똑같이 눕힌다. 거기서 거짓말은 안 통한다.`,
  o:[
    { l:'① 털이 일어서는 정도로 걸음의 앞뒤를 가린다.', k:'sense', dc:21,
      ok:`털은 밟힌 쪽으로 눕는다. 이 줄은 앞으로 누웠다. 그런데 몇 걸음마다 털이 뒤로 누운 자리가 섞여 있다.<br><br>앞으로 가다 뒤로 돌아섰다가 다시 앞으로 갔다. 같은 줄 위에서. 누가 따라오나 보려고 멈춘 자리다.<br>멈춘 자리마다 좌석 등받이에 손톱자국이 있다. 등받이를 잡고 돌아본 것이다.<br><br>그는 쫓는 쪽이 아니었다. 쫓기는 쪽이었다. 무엇에게서인지는 다음 칸이 말해 줄 것이다. 털 한 줄이 사람 마음까지 말했다. 그 말을 알아듣게 됐다.`,
      ng:`털을 들여다보는 사이 열차가 흔들렸다. 앞 칸 문이 열렸다 닫혔다.<br><br>누가 들어왔다. 고개를 드니 아무도 없다.<br>발밑 카펫 털이 이쪽 발 둘레로 눕는다. 이쪽 말고 다른 발 모양으로.`,
      win:{ exp:23, dream:3 }, lose:{ mind:-16, spirit:-18 }, wake:1 },
    { l:'② 자국을 밟지 않고 좌석 팔걸이를 짚으며 간다.', k:'steady', dc:20,
      ok:`팔걸이에서 팔걸이로 짚으며 걸었다. 카펫 털을 밟지 않았다.<br><br>이쪽이 지난 것이 털에 남지 않는다. 뒤에서 털을 읽는 것이 있다면 길을 잃을 것이다.<br>마지막 팔걸이 밑에 종이봉투가 끼어 있다. 말린 버섯 한 줌. 식당칸 것이다.`,
      ng:`팔걸이 하나가 헐거웠다. 체중이 실리자 꺾였다.<br><br>좌석 위로 넘어지며 자는 승객 무릎에 손을 짚었다. 승객이 눈을 감은 채 이쪽 손을 덮는다.<br>빼는 데 한참. 손등에 손자국이 차갑게 남았다.`,
      win:{ exp:14, dream:1, item:'야생 버섯' }, lose:{ hp:-22, spirit:-16 } }
  ] },

{ at:'B', t:'뒤에서 — 쫓는 쪽의 걸음',
  x:`뒤에서 발소리가 따라온다. 모습은 안 보인다.<br><br>
    걸음 소리를 듣는다. 무게, 박자, 쉬는 자리.<br>
    걸음에도 사람이 있다.<br><br>
    한 모퉁이마다 한 번, 발소리가 멈춘다.`,
  o:[
    { l:'① 멈추는 박자를 읽어 그 사이에 꺾는다.', k:'sense', dc:21,
      ok:`멈추는 데는 늘 모퉁이 앞이다. 모퉁이를 돌기 전에 귀를 기울이는 걸음이다. 신중하다. 서두르지 않는다.<br><br>그러니 모퉁이에서는 빨라지지 않는다. 일행을 모퉁이마다 두 걸음 앞에서 꺾게 했다.<br>멈춰서 듣는 동안 이쪽은 이미 다음 복도에 있었다.<br><br>세 모퉁이 뒤 발소리가 멈춘 채 다시 걷지 않았다. 이쪽을 잃은 것이다. 아니면 기다리는 것이다.`,
      ng:`멈추는 박자라고 셌는데 이번엔 멈추지 않았다.<br><br>모퉁이를 같이 돌았다. 몇 걸음 사이를 두고 서로를 봤다.<br>눈을 맞추기 전에 뛰었다. 뛰다 미끄러져 무릎을 찧었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, mind:-14 } },
    { l:'② 빈방에 들어가 문 뒤에서 걸음이 지나가길 기다린다.', k:'hide', dc:21,
      ok:`빈방에 들어가 문 뒤에 섰다. 숨을 죽였다.<br><br>발소리가 문 앞에서 멈췄다. 오래.<br>그리고 지나갔다. 지나간 뒤 문 밑 틈으로 젖은 자국이 하나 밀려 들어와 있었다. 문 앞에서 신발을 털었던 것이다.`,
      ng:`문 뒤에 섰는데 방 안에 다른 숨소리가 있다.<br><br>먼저 숨은 사람이다. 이쪽을 보고 문을 열고 뛰쳐나갔다.<br>발소리가 그를 따라갔다. 그가 무엇을 소리쳤는지는 모른다. 소리는 금방 끊겼다.`,
      win:{ exp:15, dream:2 }, lose:{ mind:-18, spirit:-16 } }
  ] },

{ at:'B1', t:'하역장 — 빗속의 바퀴 자국',
  x:`하역장 마당에 트럭 바퀴 자국이 여러 줄이다. 빗물이 고였다.<br><br>
    깊은 자국과 얕은 자국이 섞였다.<br>
    짐을 실은 트럭은 깊게, 빈 트럭은 얕게 판다.<br><br>
    실은 트럭은 배로 가고, 빈 트럭은 정문으로 간다.`,
  o:[
    { l:'① 얕은 자국을 따라 정문 쪽으로 간다.', k:'sense', dc:21,
      ok:`깊은 자국은 다 방파제 쪽으로 꺾였다. 얕은 자국 둘이 반대로 간다.<br><br>그중 하나는 자국 안에 고인 물이 맑다. 오래됐다. 다른 하나는 흙탕이다. 방금이다.<br>맑은 쪽을 탔다. 방금 간 트럭이 돌아오는 길과 겹치지 않게.<br><br>정문 옆 경비 초소가 보인다. 불이 꺼졌다. 창문에 빗물이 줄줄 흐른다.`,
      ng:`얕은 자국을 탔다. 끝에 트럭이 서 있다. 짐칸 문이 열렸다.<br><br>빈 트럭이 아니었다. 짐을 내리고 다시 싣기 전이다.<br>짐칸 안에서 노란 비옷 둘이 이쪽을 봤다. 손에 쥔 갈고리가 젖어 있다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, mind:-12 } },
    { l:'② 무력으로 바퀴 자국 사이 진흙을 짓밟아 건넌다.', k:'steady', dc:20, cost:{ might:22 },
      ok:`자국 사이는 무릎까지 빠지는 진흙이다. 힘으로 뽑고 디뎠다.<br><br>마당 끝 철조망 밑에 개구멍이 있다. 진흙이 깊어서 아무도 이쪽으로 안 온다.<br>일행을 하나씩 끌어 건넸다. 다리가 납덩이 같다.`,
      ng:`진흙이 허벅지까지 삼켰다. 뽑을수록 더 들어간다.<br><br>일행이 끌어냈다. 신발 한 짝이 진흙에 남았다.<br>맨발로 자갈 위를 걸었다. 발바닥이 다 찢겼다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-28, spirit:-12 } }
  ] },

{ at:'B2', t:'정각 점검 — 딸깍 소리의 길',
  x:`정각이다. 복도 저쪽에서 딸깍 소리가 시작된다.<br><br>
    계수기 든 간호사가 병실을 돈다. 걸음 하나에 한 번이 아니다. 사람 하나에 한 번이다.<br>
    눈 대신 귀로 그 걸음을 따라간다.<br><br>
    딸깍 사이 간격이 길었다 짧았다 한다.`,
  o:[
    { l:'① 딸깍 간격으로 간호사의 길을 머릿속에 그린다.', k:'sense', dc:21,
      ok:`짧은 간격은 한 병실 안. 긴 간격은 병실과 병실 사이 복도. 아주 긴 간격은 모퉁이를 도는 때.<br><br>세다 보니 간호사의 길이 보인다. 701, 702, 703, 휴게실. 그리고 704 앞에서 늘 한 번 쉰다. 거기 빈 침대가 있다.<br>쉬는 그 박자에 일행을 복도 반대편으로 건넸다. 간호사는 빈 침대를 세는 동안 고개를 들지 않았다.<br><br>보지 않고 따라갔다. 소리가 발자국이 됐다. 이제 귀에도 자국이 남는다.`,
      ng:`셋째 긴 간격 다음에 딸깍 소리가 끊겼다.<br><br>어디서 멈췄는지 모른다. 숨을 죽이고 기다렸다.<br>딸깍. 바로 귀 옆에서. 이쪽이 세어졌다. 계수기 숫자가 하나 올랐다.`,
      win:{ exp:23, dream:3 }, lose:{ mind:-18, spirit:-16 }, wake:1 },
    { l:'② 빈 침대에 누워 세어지기를 기다린다.', k:'luck', dc:22,
      ok:`704호 빈 침대에 누웠다. 시트를 턱까지 끌어 올렸다.<br><br>딸깍. 간호사가 지나갔다. 세었다. 이 침대 몫으로.<br>베개 밑에 무언가 단단하다. 꿀 한 줌이 든 작은 병이다. 이 침대 주인이 아껴 둔 것이다. 돌아오지 않은 사람의 것이다.`,
      ng:`누웠다. 간호사가 와서 섰다. 세지 않는다.<br><br>명패를 본다. 이쪽 얼굴을 본다. 다시 명패를 본다.<br>계수기 대신 볼펜을 꺼내 명패 이름을 지웠다. 그리고 이쪽 이름을 적었다.`,
      win:{ exp:14, dream:1, item:'꿀 한 줌' }, lose:{ mind:-16, spirit:-20 } }
  ] },

{ at:'B3', t:'식당칸 — 식탁 위 물 자국',
  x:`식당칸 식탁마다 유리잔이 놓였다. 손님은 없다.<br><br>
    식탁보에 물 자국이 동그랗게 남았다. 잔을 들었다 놓은 자국이다.<br>
    자국마다 잔이 있다. 하나만 빼고.<br><br>
    창가 식탁에 물 자국이 하나 있는데 잔이 없다.`,
  o:[
    { l:'① 잔 없는 물 자국이 언제 생겼는지 읽는다.', k:'sense', dc:21,
      ok:`다른 자국들은 식탁보에 스며 번졌다. 오래됐다. 이 자국은 아직 동그랗다. 번지지 않았다.<br><br>방금 누가 앉아 마시고 잔을 들고 갔다. 잔을 들고 다니는 손님은 없다. 잔을 들고 다니는 것은 주방으로 가는 사람이다.<br>주방 쪽 문을 피해 반대편으로 돌았다. 돌면서 창가 의자를 만져 봤다. 따뜻하다.<br><br>의자 밑에 접시 하나가 떨어져 있다. 산나물 무침. 손대지 않았다.`,
      ng:`읽는 사이 물 자국이 하나 더 생겼다. 바로 옆에.<br><br>잔 없이. 동그랗게. 이쪽이 보고 있는 동안.<br>식탁보 아래에서 무언가 무릎을 건드렸다. 뒤로 물러나다 의자째 넘어졌다.`,
      win:{ exp:18, dream:2, item:'산나물' }, lose:{ hp:-22, spirit:-16 } },
    { l:'② 잔마다 남은 입술 자국을 본다.', k:'gaze', dc:21,
      ok:`잔마다 입술 자국이 있다. 다 다른 입술이다. 그런데 셋이 똑같다. 금 간 자리까지.<br><br>같은 사람이 셋 자리를 옮겨 다니며 마셨다. 셋 다 다른 손님인 척.<br>그 셋 자리를 이어 보면 이쪽이 지나갈 통로를 다 내려다본다.`,
      ng:`잔을 들어 비춰 보는데 잔 안에 남은 물이 출렁였다. 열차는 안 흔들렸다.<br><br>물 위에 얼굴이 비친다. 이쪽 뒤에 선 얼굴이다.<br>돌아보니 아무도 없다. 잔을 떨어뜨려 깨뜨렸다. 손바닥이 베였다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-20, mind:-16 } },
    { l:'③ 식탁보 밑으로 몸을 숨겨 칸을 지난다.', k:'hide', dc:20,
      ok:`식탁보가 바닥까지 늘어졌다. 식탁 밑에서 식탁 밑으로 건넜다.<br><br>창가 식탁 밑에서 젖은 구두 두 짝이 보였다. 사람 없이 가지런히.<br>구두 코가 이쪽을 향했다. 지나간 뒤에 보니 구두 코가 다른 쪽을 향해 있었다.`,
      ng:`식탁 밑에서 다음 식탁으로 건너는 순간 열차가 기울었다.<br><br>유리잔들이 한꺼번에 쏟아졌다. 소리가 칸을 채웠다.<br>주방 쪽 칼질 소리가 멎었다.`,
      win:{ exp:14, dream:1 }, lose:{ mind:-16, spirit:-14 } }
  ] },

{ at:'B', t:'쫓기는 길 — 거꾸로 찍는 자국',
  x:`뒤에서 무언가가 이쪽 자국을 읽으며 따라온다.<br><br>
    젖은 바닥에 일행 발자국이 고스란히 찍힌다. 지울 시간은 없다.<br>
    지울 수 없으면 바꾼다.<br><br>
    추적자는 다른 사람이 자국을 어떻게 읽는지 안다. 제가 그렇게 읽으니까.`,
  o:[
    { l:'① 일행을 제 발자국 위로 뒷걸음질 쳐 되돌리고 옆으로 뺀다.', k:'sense', dc:22,
      ok:`일행을 막다른 복도 끝에 닿을 때까지 걷게 했다. 끝에서 뒤로 돌아 각자 제 발자국을 그대로 밟고 열 걸음 돌아오게 했다.<br><br>열 걸음째 옆으로 열린 문이 있다. 거기서 뛰어 문 안으로. 문 앞에는 자국이 없다.<br>뒤에서 오던 것이 막다른 끝에 닿았다. 거기서 오래 서 있었다. 벽을 긁는 소리가 났다.<br><br>읽는 쪽에서 읽히는 쪽으로 자리를 바꿔 봤다. 읽히는 쪽에 서니 읽을 사람이 어떻게 속을지가 보인다. 남기는 자국까지 손에 쥐었다.`,
      ng:`셋째 일행이 뒷걸음질 치다 제 발자국을 빗디뎠다. 자국이 하나 겹쳐 넓어졌다.<br><br>그 하나면 충분했다. 뒤의 것이 막다른 끝으로 가지 않고 열 걸음째에서 멈췄다.<br>문을 연다. 이쪽이 숨은 문을. 다들 창으로 뛰어나갔다. 창틀 유리에 다리를 베였다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-26, mind:-14 }, wake:1 },
    { l:'② 무력으로 바닥 물을 튀기며 갈림길마다 가짜 길을 낸다.', k:'break', dc:21, cost:{ might:24 },
      ok:`갈림길마다 한 쪽으로 다섯 걸음 힘껏 밟아 물을 튀겨 놓고 돌아왔다. 다른 쪽으로 진짜로 갔다.<br><br>세 갈림길을 그렇게 했다. 숨이 찼다.<br>뒤의 것이 세 번 다 가짜 쪽으로 갔다. 갔다가 돌아오는 소리가 점점 멀어졌다.`,
      ng:`가짜 길을 내다 다리가 풀렸다. 진짜 길보다 가짜 길에 자국이 더 많이 남았다.<br><br>뒤의 것이 망설이지 않았다. 진짜 쪽으로 왔다. 덜 찍힌 쪽으로.<br>읽는 쪽은 이쪽만이 아니었다.`,
      win:{ exp:17, dream:2 }, lose:{ hp:-28, spirit:-12 } },
    { l:'③ 바닥을 버리고 배관을 타고 위로 간다.', k:'evade', dc:21,
      ok:`벽을 따라 지나는 배관을 잡고 올라탔다. 천장 밑으로 기었다.<br><br>바닥에 자국이 끊긴다. 뒤의 것이 끊긴 자리에서 멈췄다. 아래만 본다.<br>머리 위를 지나갔다. 내려다보지 않았다. 숨도 안 쉬었다.`,
      ng:`배관 이음매가 뜯겼다. 뜨거운 김이 뿜어졌다.<br><br>손등과 목덜미가 데었다. 떨어지며 바닥에 큰 자국을 남겼다.<br>뒤의 것이 그 자국 앞에서 멈췄다. 오래 들여다봤다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-28, mind:-12 } }
  ] },

{ at:'B', t:'바닥 — 일행의 핏방울',
  x:`일행 하나가 손을 베였다. 별것 아니라고 한다.<br><br>
    피가 한 방울씩 떨어진다. 다섯 걸음에 하나.<br>
    그 방울이 무엇을 말하는지 안다.<br><br>
    뒤에서 오는 것도 안다.`,
  o:[
    { l:'① 핏방울을 엉뚱한 쪽으로 이어 놓는다.', k:'sense', dc:21,
      ok:`다친 손을 감게 하고 떨어진 방울을 되짚었다. 마지막 방울에서 다른 복도로 다섯 걸음마다 한 방울씩 떨어뜨렸다. 제 손가락을 따서.<br><br>열다섯 방울. 막힌 계단까지. 거기서 손을 감았다.<br>돌아와 일행과 반대쪽으로 갔다. 한참 뒤 막힌 계단 쪽에서 무언가 철문을 두드렸다.<br><br>손가락 끝이 욱신거린다. 그만한 값이었다.`,
      ng:`방울을 이어 놓다 간격을 틀렸다. 넷 걸음에 하나.<br><br>뒤의 것은 간격을 안다. 진짜 방울과 가짜 방울을 갈랐다.<br>진짜 쪽으로 곧장 왔다. 일행을 끌고 뛰었다. 이번엔 이쪽 피가 떨어졌다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, spirit:-16 } },
    { l:'② 상처를 단단히 싸매 피를 멈춘다.', k:'heal', dc:20,
      ok:`천을 찢어 손바닥을 눌렀다. 단단히 감았다. 손목도 묶었다.<br><br>피가 멎었다. 바닥에 떨어진 방울은 신발 바닥으로 문질러 번지게 했다.<br>번진 피는 방향을 말하지 않는다.`,
      ng:`감는 사이 피가 더 났다. 천이 금방 젖었다.<br><br>그동안 바닥에 방울이 고였다. 작은 웅덩이가 됐다.<br>뒤에서 오는 것에게는 깃발 같은 웅덩이다.`,
      win:{ exp:14, dream:1, hp:8 }, lose:{ mind:-16, spirit:-14 } }
  ] },

{ at:'B1', t:'야적장 — 문 안쪽의 손톱자국',
  x:`컨테이너 하나의 문이 열려 있다. 안은 비었다.<br><br>
    문 안쪽 철판에 손톱자국이 촘촘하다. 위에서 아래로. 사람 키 높이에서 바닥까지.<br>
    자국 끝에 칠이 일어나 있다. 오래된 것과 새것이 섞였다.<br><br>
    컨테이너 위로 크레인 갈고리가 내려와 걸려 있다. 들어 올릴 준비가 됐다.`,
  o:[
    { l:'① 새 자국으로 안에 있던 사람이 언제 나갔는지 읽는다.', k:'sense', dc:22,
      ok:`새 자국은 칠 가루가 아직 바닥에 쌓였다. 바람이 들면 날아간다. 그런데 남아 있다. 문은 방금 열렸다.<br><br>안에 있던 사람은 나간 게 아니다. 문이 열린 것은 다음 사람을 넣으려고다.<br>들어가지 않았다. 일행을 컨테이너 뒤로 돌렸다.<br><br>크레인 사슬이 감기는 소리가 났다. 빈 컨테이너가 들린다. 문이 열린 채로. 안에 아무도 없는 것을 아무도 확인하지 않았다.`,
      doom:{ title:'들리는 컨테이너', what:'컨테이너째 들려 갑니다', dc:17, sec:55,
        text:`자국을 더 자세히 보려고 한 발 들였다. 손톱자국에 손가락을 대 봤다. 이쪽 손가락과 같은 크기다.<br><br>등 뒤에서 문이 닫혔다. 바깥 빗장이 걸린다.<br>바닥이 기운다. 들린다. 사슬 소리가 머리 위에서 울린다.<br><br>어둠 속에서 손이 저절로 철판을 긁고 있다. 위에서 아래로.`,
        dieText:`해무호 갑판에 컨테이너 하나가 내려졌다.<br><br>목록에 숫자가 하나 채워졌다. 『전량』.<br>컨테이너 안쪽 철판에 손톱자국이 한 줄 더 늘었다. 가장 새것이다.` },
      win:{ exp:24, dream:3 } },
    { l:'② 일행을 문 앞에 세워 문이 못 닫히게 버틴다.', k:'bond', dc:21,
      ok:`둘이 문짝을 붙들었다. 하나가 안을 봤다.<br><br>바닥 구석에 누가 남긴 것이 있다. 기름종이에 싼 말린 고기. 마지막 사람이 먹지 못하고 남겼다.<br>챙기고 나왔다. 문을 놓자 바람에 닫혔다. 빗장이 저절로 걸렸다.`,
      ng:`문짝을 붙든 손이 미끄러졌다. 비가 쇠를 미끄럽게 한다.<br><br>문이 닫히며 손가락을 찧었다.<br>빗장이 걸리기 직전에 손을 뺐다. 손톱 하나가 철판에 남았다. 새 자국 하나와 함께.`,
      win:{ exp:15, dream:2, item:'말린 고기' }, lose:{ hp:-26, spirit:-14 } }
  ] },

{ at:'B2', t:'기록 보관실 — 먼지 위 손자국',
  x:`기록 보관실 서가에 먼지가 두껍다. 손댄 사람이 없다.<br><br>
    한 칸만 먼지에 손자국이 있다. 손가락 넷. 엄지는 없다.<br>
    그 칸 서류철을 누가 꺼냈다가 다시 꽂았다.<br><br>
    손자국의 깊이를 본다. 먼지 위 손자국도 무게를 말한다.`,
  o:[
    { l:'① 손자국으로 꺼낸 사람의 키와 꺼낸 철을 짚는다.', k:'sense', dc:21,
      ok:`손자국 높이가 이쪽 어깨다. 그런데 손바닥 자국은 없고 손가락 끝만 깊다. 발끝으로 서서 꺼냈다. 키가 작다. 직원이 아니다. 환자다.<br><br>손가락 끝이 가리키는 철을 뽑았다. 『7층 재원 명부』. 한 쪽이 접혀 있다.<br>접힌 쪽에 이름들이 있다. 이름마다 가위표. 마지막 줄만 비었다. 그 줄 옆에 연필로 작게. 『계단은 세탁실 옆』.<br><br>먼지 한 칸이 사람 하나를 다 말했다. 키와 마음과 하고 싶었던 말까지. 손자국이 말을 거는 것이 들리기 시작했다.`,
      ng:`손자국에 손을 맞춰 보다 먼지를 흩뜨렸다. 손자국이 지워졌다.<br><br>재채기가 터졌다. 서가 사이에 울렸다.<br>창가 의자에서 무언가 몸을 일으키는 소리가 났다. 손전등이 켜졌다.`,
      win:{ exp:23, dream:3 }, lose:{ mind:-16, spirit:-16 }, wake:1 },
    { l:'② 먼지를 흩어 이쪽 손자국을 지운다.', k:'fix', dc:20,
      ok:`이쪽이 만진 데마다 입김을 불어 먼지를 흩었다. 고르게.<br><br>나오면서 보니 서가가 들어올 때와 똑같다.<br>다음에 누가 이 방을 읽어도 이쪽은 없다.`,
      ng:`입김을 부는데 먼지가 일어 눈에 들어갔다.<br><br>눈을 비비다 서가에 기댔다. 서가가 흔들려 서류철 셋이 쏟아졌다.<br>쏟아진 철 위에 이쪽 손자국이 선명하게 찍혔다.`,
      win:{ exp:14, dream:1 }, lose:{ hp:-20, mind:-14 } }
  ] },

{ at:'B3', t:'연결 통로 — 젖은 손잡이',
  x:`앞 칸으로 가는 연결 통로 손잡이가 젖어 있다.<br><br>
    빗물이 아니다. 따뜻하다. 땀이다.<br>
    방금 누가 이 손잡이를 꽉 쥐고 건넜다. 겁먹은 손이다.<br><br>
    연결부 철판이 덜컹거린다. 철판 사이 틈으로 선로가 보인다.`,
  o:[
    { l:'① 손잡이 땀이 식는 정도로 얼마나 앞서갔는지 재고 따라붙는다.', k:'sense', dc:22,
      ok:`땀이 아직 미지근하다. 숨 마흔. 겁먹은 사람은 다음 칸에서 멈춘다. 숨을 고르려고.<br><br>건넜다. 다음 칸 첫 좌석에 승무원 모자를 쓴 사람이 웅크리고 있다. 손을 떨면서. 사람이다. 눈이 제때 깜박인다.<br>그가 이쪽을 보고 손가락으로 앞을 가리킨다. 그리고 입 모양으로 말한다. 저 사람이 내 얼굴을 했어.<br><br>그의 품에 꿀단지가 안겨 있다. 한 줌을 덜어 이쪽 손에 쥐여 줬다.`,
      doom:{ title:'연결부 틈', what:'연결부 틈으로 끌려 내려갑니다', dc:17, sec:50,
        text:`손잡이를 잡고 서둘러 건넜다. 연결부 철판 한가운데서 열차가 굽은 길에 들어섰다.<br><br>철판이 벌어진다. 틈이 발 하나만큼 커진다. 발이 빠졌다.<br>아래에서 무언가 발목을 잡는다. 선로 쪽에서. 당긴다.<br><br>손잡이에 매달렸다. 땀으로 젖은 손잡이다. 손이 미끄러진다.`,
        dieText:`연결부 철판이 다시 맞물렸다. 덜컹, 덜컹.<br><br>손잡이는 젖어 있다. 따뜻하다.<br>다음에 건너는 사람은 겁먹은 손이 방금 지나갔다고 생각할 것이다.` },
      win:{ exp:24, dream:3, item:'꿀 한 줌' } },
    { l:'② 무력으로 연결부 철판을 눌러 붙들고 일행을 건넨다.', k:'steady', dc:21, cost:{ might:24 },
      ok:`연결부 철판 양끝에 발을 버티고 섰다. 철판이 벌어지지 않게 온몸으로 눌렀다.<br><br>일행이 하나씩 건넜다. 철판이 다리 밑에서 몇 번이나 들썩였다.<br>마지막으로 건넜다. 무릎이 덜덜 떨린다. 철판이 등 뒤에서 크게 벌어졌다 닫혔다.`,
      ng:`철판이 굽은 길에서 비틀렸다. 버티던 다리가 꺾였다.<br><br>정강이가 철판 모서리에 끼었다. 일행이 끌어냈다.<br>바지 아래가 피로 젖었다. 연결부가 다시 덜컹인다. 아무 일 없다는 듯이.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-30, spirit:-12 } }
  ] },

{ at:'B', t:'빗물 웅덩이 — 멎지 않는 파문',
  x:`처마 밑 어두운 구석에 빗물 웅덩이가 있다.<br><br>
    빗방울이 떨어지는 웅덩이는 파문이 사방으로 고르게 번진다.<br>
    이 웅덩이는 한쪽에서만 파문이 계속 인다. 처마 안쪽에서. 비가 닿지 않는 데서.<br><br>
    거기 무언가 서 있다. 물이 떨어지는 것이다. 옷자락에서.`,
  o:[
    { l:'① 파문의 간격으로 서 있는 것의 숨을 잰다.', k:'sense', dc:21,
      ok:`옷자락 물은 숨에 맞춰 떨어진다. 들이쉬면 옷이 부풀고 내쉬면 물이 떨어진다.<br><br>간격이 길다. 깊이 잠든 숨이 아니다. 기다리는 숨이다. 오래 기다릴 수 있는 숨이다.<br>그러니 서두르지 않을 것이다. 일행을 처마 바깥 빗속으로 크게 돌렸다. 비를 맞으며.<br><br>지나서 돌아봤다. 파문이 멎었다. 서 있던 것이 숨을 참고 이쪽을 보고 있다.`,
      ng:`간격을 재는 사이 파문이 멈췄다.<br><br>멈춘 웅덩이는 거울이다. 거기 이쪽 얼굴과 그 옆의 얼굴이 비쳤다.<br>옆에는 아무도 없다. 웅덩이에서 눈을 떼지 못하고 뒷걸음질 치다 넘어졌다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-18, spirit:-16 } },
    { l:'② 빗소리에 맞춰 처마 밑을 소리 없이 지난다.', k:'hide', dc:21,
      ok:`빗줄기가 굵어지는 박자에만 걸었다. 굵은 비가 발소리를 먹는다.<br><br>처마 끝에 닿았다. 웅덩이 파문이 한 번도 흐트러지지 않았다.<br>저쪽은 이쪽을 듣지 못했다. 아니면 들을 필요가 없었다.`,
      ng:`빗줄기가 갑자기 가늘어졌다. 발밑에서 자갈이 굴렀다.<br><br>웅덩이 파문이 이쪽으로 번지기 시작했다. 다가오는 것이다.<br>뛰었다. 등 뒤에서 젖은 옷자락이 펄럭이는 소리가 바로 귀 뒤까지 왔다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-22, spirit:-16 } }
  ] },

{ at:'B1', t:'야적장 — 개와 사람의 발자국',
  x:`컨테이너 사이 진흙에 개 발자국이 있다. 크다. 그 옆에 장화 자국.<br><br>
    개 발자국이 장화 앞을 오락가락한다. 줄에 묶인 개다.<br>
    개는 냄새로 찾는다. 사람은 개를 믿는다.<br><br>
    둘을 같이 읽어야 한다. 어디서 둘이 떨어지는지.`,
  o:[
    { l:'① 개가 줄을 당긴 자리와 사람이 멈춘 자리를 가른다.', k:'sense', dc:21,
      ok:`개 발자국이 깊게 패인 데는 줄을 당긴 데다. 장화 자국이 거기서 멈췄다. 사람이 개를 말렸다.<br><br>말린 자리는 늘 같은 데다. 물웅덩이 앞. 개가 물 냄새에 끌리는데 사람이 막는다. 사람은 발을 적시기 싫어한다.<br>그러니 둘이 오지 않는 데는 물웅덩이 너머다. 일행을 물웅덩이 속으로 걷게 했다. 정강이까지 젖었다. 개는 짖지 않았다.<br><br>개와 사람이 한 쌍으로 읽혔다. 쫓는 것이 둘이면 둘 사이의 틈이 보인다. 그 틈을 읽는 눈이 섰다.`,
      ng:`줄 당긴 자리를 짚다 바람이 바뀌었다. 등 뒤에서 바다로.<br><br>이쪽 냄새가 개 쪽으로 갔다. 짖는 소리. 줄 풀리는 소리.<br>컨테이너 사이로 뛰었다. 개 이빨이 종아리를 스쳤다. 바지가 찢겼다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-28, mind:-12 }, wake:1 },
    { l:'② 생선 상자 옆에 숨어 냄새를 묻는다.', k:'hide', dc:21,
      ok:`버려진 생선 상자 옆에 몸을 붙였다. 비린내가 사람 냄새를 덮는다.<br><br>개가 지나가며 상자에 코를 박았다. 오래. 그리고 지나갔다.<br>장화가 그 뒤를 따라 지나갔다. 상자 하나를 걷어찼다. 이쪽 무릎 한 뼘 앞에서 멈췄다.`,
      ng:`상자 옆에 붙었는데 개가 상자로 곧장 왔다. 상자가 아니라 상자 옆을 맡는다.<br><br>개가 으르렁댄다. 장화가 다가온다. 손전등이 켜진다.<br>상자를 개 쪽으로 엎고 뛰었다. 생선이 쏟아지는 사이 겨우 벗어났다.`,
      win:{ exp:15, dream:2 }, lose:{ mind:-16, spirit:-16 } }
  ] },

{ at:'B2', t:'세탁실 — 수레 바퀴 자국',
  x:`세탁실 바닥에 수레 바퀴 자국이 두 줄이다. 젖은 바닥에 선명하다.<br><br>
    한 줄은 깊고 한 줄은 얕다. 같은 수레다. 갈 때와 올 때.<br>
    얕은 쪽이 갈 때다. 빈 수레로 가서 무언가 싣고 왔다.<br><br>
    깊은 줄은 세탁실 안쪽 큰 문 앞에서 끝난다.`,
  o:[
    { l:'① 얕은 줄을 거슬러 수레가 어디서 싣고 왔는지 찾는다.', k:'sense', dc:21,
      ok:`얕은 줄은 세탁실 뒷문으로 이어진다. 뒷문은 철망 친 화물 승강기 앞이다. 버튼에 아래 화살표가 있다.<br><br>이 건물에서 처음 보는 아래 화살표다.<br>눌렀다. 승강기가 올라오는 소리가 난다. 아주 느리게.<br><br>세탁실 안쪽 큰 문 너머에서 무언가 수레를 미는 소리가 난다. 이쪽으로.`,
      ng:`얕은 줄을 거슬러 가다 줄이 하나 더 생겼다. 셋째 줄. 방금 난 자국이다.<br><br>바퀴가 바로 뒤에서 구른다. 돌아보니 빈 수레가 혼자 굴러온다.<br>피하다 세탁기 모서리에 허리를 박았다. 수레가 이쪽 앞에서 멈췄다. 싣기 좋은 자리에.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, spirit:-16 } },
    { l:'② 세탁물 더미를 뒤져 쓸 것을 찾는다.', k:'luck', dc:21,
      ok:`세탁물 자루 사이에 직원용 앞치마가 섞여 있다. 앞치마 주머니에 종이 봉투가 있다.<br><br>약초 뭉치. 한방 처치실 것이다. 쓴 냄새가 난다. 상처에 붙이면 낫는다.<br>앞치마 명찰에 이름이 없다. 숫자만 있다.`,
      ng:`자루를 열었다. 세탁물이 아니다. 젖은 환자복이다. 무겁다.<br><br>자루가 넘어지며 안의 것이 쏟아졌다. 환자복만. 사람은 없다. 사람 모양으로 젖었을 뿐이다.<br>그 모양이 한참 눈에서 안 떨어졌다.`,
      win:{ exp:14, dream:1, item:'약초 뭉치' }, lose:{ mind:-16, spirit:-20 } }
  ] },

{ at:'B3', t:'특실 복도 — 한 박자 늦은 발소리',
  x:`특실 복도는 카펫이 두껍다. 발소리가 작다.<br><br>
    그래도 들린다. 이쪽 발소리 뒤에 하나가 더 있다. 한 박자 늦게.<br>
    멈추면 멈춘다. 걸으면 걷는다.<br><br>
    메아리라고 하기엔 무게가 다르다.`,
  o:[
    { l:'① 이쪽 걸음 박자를 바꿔 뒤의 걸음을 떼어 낸다.', k:'sense', dc:22,
      ok:`세 걸음 걷고 반 박자 쉬고 두 걸음. 일부러 엇박으로.<br><br>뒤의 걸음이 따라 하려다 한 번 틀렸다. 이쪽이 쉰 반 박자에 걸었다. 한 걸음 많았다.<br>그 한 걸음으로 자리가 드러났다. 등 뒤 세 걸음. 오른쪽 벽 가까이. 이쪽 발뒤꿈치를 밟을 만한 자리.<br><br>왼쪽 객실 문을 열고 들어가 닫았다. 문 너머에서 걸음이 멈췄다. 따라 할 박자가 사라진 것이다.<br>따라오는 것은 따라 할 것이 있어야 따라온다. 걸음이 이제 이쪽 손에 쥐어졌다. 남의 것도, 이쪽 것도.`,
      ng:`엇박으로 걸었다. 뒤의 걸음이 틀리지 않았다. 엇박까지 그대로 따라 했다.<br><br>멈췄다. 뒤도 멈췄다. 숨소리가 목덜미에 닿는다.<br>뛰었다. 이번엔 뒤가 따라 하지 않았다. 한 박자 먼저 뛰었다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-18, spirit:-18 }, wake:1 },
    { l:'② 갑자기 돌아서서 뒤를 붙잡는다.', k:'evade', dc:21,
      ok:`세 걸음째에 몸을 틀어 뒤로 팔을 뻗었다.<br><br>손에 잡힌 것은 젖은 외투 자락이다. 안이 비었다. 외투만 바닥에 떨어진다.<br>외투 주머니에서 열쇠 하나가 굴러 나왔다. 특실 7호. 챙겼다.`,
      ng:`돌아섰다. 아무것도 없다. 팔이 허공을 저었다.<br><br>균형을 잃고 객실 문에 머리를 박았다.<br>문 안에서 누가 대답했다. 들어오세요.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-24, mind:-14 } }
  ] },

{ at:'B', t:'멈춘 발자국 — 문 앞에서',
  x:`쫓던 발자국이 문 앞에서 멈췄다. 문 안으로 들어갔다.<br><br>
    방 안은 어둡다. 나오는 발자국은 없다.<br>
    일행이 문을 노려본다. 안에 있다.<br><br>
    추적자는 문 앞 발자국 하나하나를 다시 본다.`,
  o:[
    { l:'① 발자국의 무게가 어느 쪽으로 실렸는지 다시 읽는다.', k:'sense', dc:22,
      ok:`문 앞 다섯 발자국. 앞꿈치가 문 쪽인데 무게는 뒤꿈치에 실렸다. 뒷걸음질이다.<br><br>들어간 게 아니다. 방에서 나와서 제 발자국을 거꾸로 밟고 왔다. 들어간 것처럼 보이게.<br>그러면 그것은 지금 문 안이 아니라 이쪽 뒤에 있다. 돌아보지 않고 일행을 옆 계단으로 밀었다.<br><br>계단을 내려가며 위를 봤다. 문 앞 복도 천장 그늘에서 무언가 천천히 내려오고 있었다. 이쪽이 문을 열기를 기다리던 자리에서.`,
      doom:{ title:'뒤에 선 것', what:'뒤에 서 있던 것에게 끌려갑니다', dc:17, sec:50,
        text:`발자국을 다시 읽는다. 무게가 앞에 실렸다고 읽었다. 들어갔다.<br><br>문을 열었다. 방은 비었다. 창도 없다.<br>등 뒤 복도에서 일행 하나가 숨을 들이켠다. 그리고 소리가 끊긴다.<br><br>돌아섰다. 젖은 팔이 이쪽 허리를 감는다. 당긴다. 복도 반대편 어둠으로.`,
        dieText:`문 앞 바닥에 발자국이 새로 났다. 다섯 개. 뒷걸음질.<br><br>다음에 오는 사람은 또 문 안을 노려볼 것이다.<br>안에는 아무도 없다. 그게 늘 맞는 답이다.` },
      win:{ exp:25, dream:3 } },
    { l:'② 무력으로 문을 박차고 먼저 들이닥친다.', k:'break', dc:21, cost:{ might:25 },
      ok:`문을 걷어찼다. 경첩째 뜯겼다. 방 안에 뛰어들어 불빛을 휘둘렀다.<br><br>비었다. 창이 열려 있다. 빗물이 들이친다. 창틀에 젖은 손자국.<br>창밖 철제 계단이 아래로 이어진다. 그것은 이미 나갔다. 이 길로 나가면 된다.`,
      ng:`문을 걷어찼는데 안에서 무언가 문을 받쳤다.<br><br>되튕긴 문이 이쪽 얼굴을 쳤다. 코에서 피가 쏟아진다.<br>문틈으로 젖은 손가락 넷이 나와 문짝을 천천히 닫았다.`,
      win:{ exp:17, dream:2 }, lose:{ hp:-30, mind:-12 } }
  ] },

{ at:'B', t:'빗속 — 담배도 아닌 냄새',
  x:`비가 냄새를 씻어 간다. 그래도 남는 냄새가 있다.<br><br>
    표백제. 젖은 고무. 그리고 쇠 냄새.<br>
    갈림길에서 셋 다 섞여 있다. 한쪽이 조금 진하다.<br><br>
    코로도 자국은 읽힌다.`,
  o:[
    { l:'① 진한 쪽을 피해 냄새가 엷은 길을 고른다.', k:'sense', dc:21,
      ok:`표백제는 왼쪽이 진하다. 젖은 고무도 왼쪽. 쇠 냄새만 오른쪽이 진하다.<br><br>쇠 냄새는 녹슨 철문이다. 사람 냄새가 아니다. 오른쪽으로 갔다.<br>녹슨 철문이 있다. 빗장이 녹으로 반쯤 부서졌다. 밀자 열렸다.`,
      ng:`엷은 쪽을 골랐다. 엷은 것은 바람이 냄새를 다른 데로 몰고 갔기 때문이었다.<br><br>모퉁이를 돌자 냄새가 확 진해졌다. 표백제. 눈이 따갑다.<br>바로 앞에 양동이 하나가 놓여 있다. 걸레가 걸쳐졌다. 물이 아직 출렁인다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-16, spirit:-18 } },
    { l:'② 일행 옷의 냄새를 빗물로 씻어 낸다.', k:'steady', dc:20,
      ok:`처마 밖으로 나가 비를 맞았다. 다 같이. 한참.<br><br>추웠다. 이가 딱딱 부딪쳤다.<br>다시 처마 안으로 들어왔을 때 일행에게서 아무 냄새도 나지 않았다. 비 냄새 말고는.`,
      ng:`비를 오래 맞자 몸이 굳었다. 손끝이 하얘졌다.<br><br>일행 하나가 기침을 멈추지 못한다. 기침 소리가 골목을 울린다.<br>냄새는 지웠는데 소리를 남겼다.`,
      win:{ exp:14, dream:1 }, lose:{ hp:-22, mind:-14 } },
    { l:'③ 바람이 오는 쪽에 서서 냄새를 기다린다.', k:'luck', dc:21,
      ok:`바람을 맞받는 자리에 섰다. 오는 냄새를 기다렸다.<br><br>빵 굽는 냄새가 섞여 왔다. 이 밤에. 골목 끝 지하 계단에서.<br>내려가 보니 버려진 제과점 창고다. 선반 위에 꿀 단지가 남아 있다. 한 줌 덜었다.`,
      ng:`바람이 실어 온 것은 냄새가 아니라 소리였다. 호루라기.<br><br>이쪽이 바람을 맞고 서 있으면 이쪽 냄새는 뒤로 간다. 뒤에 무엇이 있는지 생각을 못 했다.<br>뒤에서 개가 짖기 시작했다.`,
      win:{ exp:14, dream:1, item:'꿀 한 줌' }, lose:{ hp:-20, spirit:-16 } }
  ] },

{ at:'B', t:'다 왔다 — 돌아본다',
  x:`출구가 보인다. 빗속에 열린 문 하나.<br><br>
    일행이 뛰려 한다. 추적자는 한 번 돌아본다. 지나온 바닥을.<br>
    여기까지 오는 동안 쫓던 것은 늘 뒤에 있었다.<br><br>
    지금은 뒤에서 아무 소리도 나지 않는다.`,
  o:[
    { l:'① 지나온 바닥에서 뒤의 것이 마지막으로 어디 섰는지 읽는다.', k:'sense', dc:22,
      ok:`이쪽 발자국 위에 겹친 발자국이 이어지다 세 모퉁이 전에서 끊긴다. 거기서 옆으로 빠졌다.<br><br>옆으로 빠진 길은 출구 앞으로 돌아오는 길이다. 앞질러 갔다. 출구 문 옆에서 기다리려고.<br>일행을 붙잡았다. 출구로 가지 않고 그 옆 창으로 나갔다. 비를 맞으며 담을 넘었다.<br><br>담 위에서 돌아봤다. 열린 문 옆 어둠에 젖은 어깨 하나가 서 있다. 아직 기다린다.`,
      ng:`읽는 데 시간을 너무 썼다. 일행이 먼저 뛰었다.<br><br>출구 문 옆에서 팔 하나가 나와 일행 하나의 옷깃을 잡았다. 달려가 그 팔을 걷어찼다.<br>빠져나왔다. 대신 이쪽 손목에 손자국이 시퍼렇게 남았다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-26, spirit:-16 } },
    { l:'② 일행을 하나씩 세며 내보낸다.', k:'bond', dc:21,
      ok:`문 앞에 서서 하나씩 내보냈다. 얼굴을 보고, 이름을 부르고, 손을 잡고.<br><br>다 나갔다. 숫자가 맞다. 얼굴도.<br>마지막으로 이쪽이 나갔다. 문 안쪽 바닥에 이쪽 발자국만 남았다. 나가는 쪽으로.`,
      ng:`세다가 하나가 더 많았다.<br><br>얼굴을 하나씩 다시 봤다. 다 맞다. 그런데 하나가 많다.<br>어느 것인지 모른 채 다 같이 빗속으로 나갔다. 한동안 아무도 서로 눈을 마주치지 않았다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-18, spirit:-18 } },
    { l:'③ 무력으로 출구 문을 닫아 걸고 다른 길로 돈다.', k:'break', dc:21, cost:{ might:22 },
      ok:`출구 문을 힘껏 닫았다. 빗장을 걸고 쇠사슬을 감았다.<br><br>문 너머에서 무언가 문을 밀었다. 이쪽에서 막은 것이다. 밖에서 기다리던 것을.<br>뒷문으로 돌았다. 멀다. 그래도 아무도 기다리지 않는 문이다.`,
      ng:`문을 닫는데 문짝이 무겁다. 밖에서 누가 당긴다.<br><br>줄다리기를 했다. 팔이 빠질 것 같다. 문이 한 뼘씩 열린다.<br>손을 놓고 뒤로 뛰었다. 문이 활짝 열리는 소리가 등 뒤에서 났다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-28, mind:-12 } }
  ] }
]);

// ------------------------------------------
// 탐지술사 (seeker) · 자원: 마력
// ------------------------------------------
kJob('seeker', 'B', [
{ at:'B', t:'잠긴 문 — 반응 셋',
  x:`잠긴 문 앞이다. 탐지술을 문틈으로 흘려 넣었다.<br><br>
    반응이 셋 돌아온다. 둘은 따뜻하다. 숨을 쉰다.<br>
    셋째는 차갑다. 그런데 움직인다. 따뜻한 둘 사이를 오간다.<br><br>
    탐지술사는 차가운 것이 움직이는 일을 좋아하지 않는다.`,
  o:[
    { l:'① 차가운 반응의 결을 가만히 짚는다.', k:'sense', dc:21,
      ok:`세게 짚으면 저쪽이 느낀다. 마력을 실처럼 가늘게 뽑아 차가운 것 가장자리에만 댔다.<br><br>차가운 것은 사람 모양이다. 숨이 없다. 심장 자리에 쇠가 있다. 열쇠꾸러미다. 따뜻한 둘은 묶여 있다. 의자에.<br>차가운 것이 문 쪽으로 온다. 이쪽 실을 느낀 게 아니다. 시간이 된 것이다. 일행을 옆 방으로 물렸다.<br><br>문이 열리고 차가운 것이 복도로 나갔다. 그동안 이쪽 실은 한 번도 들키지 않았다. 마력이 가늘어질수록 더 많이 닿았다. 그 가늚이 손끝에 붙었다.`,
      ng:`짚는 순간 차가운 것이 멈췄다. 따뜻한 둘 사이에서.<br><br>문 쪽을 향한다. 이쪽 마력을 거꾸로 타고 온다. 머릿속이 하얗게 언다.<br>술식을 끊었다. 코피가 문고리에 떨어졌다. 문 너머에서 무언가 그 문고리를 잡았다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-16, spirit:-18 }, wake:1 },
    { l:'② 마력을 층 전체로 넓혀 다른 길을 찾는다.', k:'sense', dc:21, cost:{ mana:24 },
      ok:`문을 버리고 층 전체를 덮었다. 반응이 쏟아진다. 따뜻한 것, 차가운 것, 쇠, 물.<br><br>반응이 없는 줄이 하나 있다. 벽 속을 지나는 배관 통로다.<br>그 줄로 일행을 이끌었다. 아무것도 마주치지 않았다. 머리는 지끈거렸다.`,
      ng:`넓게 펴자 마력이 얇아졌다. 얇은 데로 무언가 들어온다.<br><br>층 전체의 차가운 것들이 한꺼번에 이쪽을 향했다. 느낌으로 안다.<br>술식을 거뒀을 때는 귀에서 피가 났다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-20, spirit:-20 } }
  ] },

{ at:'B1', t:'냉동 창고 — 언 것들 사이 하나',
  x:`냉동 창고 안에 탐지술을 폈다. 다 차갑다. 갈고리에 걸린 생선, 쌓인 상자, 얼음 바닥.<br><br>
    하나만 미지근하다. 상자 더미 맨 안쪽.<br>
    미지근한 것이 떨고 있다. 반응이 떨린다.<br><br>
    살아 있다. 살아 있는 것이 다 편은 아니다.`,
  o:[
    { l:'① 떨림의 박자로 무엇인지 가린다.', k:'sense', dc:21,
      ok:`떨림이 고르지 않다. 추워서 떠는 떨림은 고르다. 이건 두려워서 떠는 떨림이다. 숨을 참았다 몰아쉰다.<br><br>상자를 치웠다. 늙은 하역부가 웅크리고 있다. 입술이 파랗다. 손에 철사 뭉치를 쥐었다.<br>문을 바깥에서 감은 철사와 같은 것이다. 그는 감은 쪽이 아니다. 풀 줄 아는 쪽이다.<br><br>그가 철사로 문 안쪽 구멍을 쑤시자 바깥 걸쇠가 풀렸다. 나가면서 그가 언 고기 한 덩이를 이쪽 품에 밀어 넣었다.`,
      ng:`떨림이 이쪽이 다가갈수록 멈췄다. 두려운 게 아니라 기다리는 것이었다.<br><br>상자를 치우자 갈고리가 튀어나왔다. 손등을 찍고 지나갔다.<br>상자 너머 미지근한 것이 이쪽을 향해 몸을 편다.`,
      win:{ exp:18, dream:2, item:'짐승 고기' }, lose:{ hp:-26, spirit:-14 } },
    { l:'② 마력으로 일행 손끝을 덥혀 버틴다.', k:'heal', dc:20,
      ok:`일행 손을 한데 모아 쥐었다. 마력을 데워 흘렸다.<br><br>파랗던 손끝에 핏기가 돈다. 다들 주먹이 쥐어진다.<br>쥐어지는 손으로 문을 찾았다. 아까는 못 했을 일이다.`,
      ng:`데우는 마력이 손끝에서 흩어졌다. 냉기가 마력까지 먹는다.<br><br>이쪽 손이 먼저 얼었다. 감각이 없다.<br>일행 손을 놓쳤다. 놓친 줄도 몰랐다.`,
      win:{ exp:14, dream:1, hp:8 }, lose:{ hp:-24, mind:-12 } }
  ] },

{ at:'B2', t:'병실 — 침대 넷, 숨 다섯',
  x:`병실에 침대가 넷이다. 다들 잔다. 시트가 오르내린다.<br><br>
    탐지술을 깔았다. 숨이 다섯이다.<br>
    침대 넷, 숨 다섯. 하나가 남는다.<br><br>
    정각 점검이 오기 전에 저 다섯째를 알아야 한다. 점검은 숫자를 맞출 것이다.`,
  o:[
    { l:'① 숨마다 심장 박자를 짚어 다섯째를 찾는다.', k:'sense', dc:22,
      ok:`숨 넷은 심장과 박자가 맞는다. 숨 하나는 심장이 없다. 숨만 있다.<br><br>그 숨은 침대 밑에서 난다. 둘째 침대 밑. 바닥에 붙어 이쪽 숨에 박자를 맞추고 있었다. 일행 숨에.<br>일행을 문 쪽으로 물렸다. 숨을 하나씩 다르게 쉬게 했다. 침대 밑 숨이 따라 하다 박자를 놓쳤다.<br><br>숨과 심장을 따로 들었다. 하나로 들리던 것이 둘로 갈렸다. 갈라 듣는 귀가 마력 안에 생겼다.`,
      ng:`심장을 세다 이쪽 심장이 너무 크게 뛰었다. 다른 박자가 안 들린다.<br><br>다섯째 숨이 이쪽 귀 바로 뒤로 옮겨 왔다.<br>돌아보니 아무도 없다. 숨은 계속 귀 뒤에 있다. 복도에서 딸깍 소리가 다가왔다.`,
      win:{ exp:23, dream:3 }, lose:{ mind:-18, spirit:-18 }, wake:1 },
    { l:'② 잠든 얼굴을 하나씩 확인한다.', k:'gaze', dc:21,
      ok:`침대마다 시트를 살짝 내렸다. 넷 다 사람이다. 깊이 잔다. 약에 취한 잠이다.<br><br>넷째 침대 사람 손에 쪽지가 쥐여 있다. 『밑에 있어. 보지 마.』<br>보지 않았다. 일행을 데리고 조용히 나왔다.`,
      ng:`셋째 시트를 내렸다. 얼굴이 없다. 베개만 있다.<br><br>시트는 계속 오르내린다.<br>시트를 다시 덮는 손이 떨려 시트 끝을 놓쳤다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-16, spirit:-20 } },
    { l:'③ 술식을 끊고 다섯째를 모른 척한다.', k:'steady', dc:20,
      ok:`끊었다. 모르는 것은 모르는 채로 둔다.<br><br>빈 침대 하나에 일행 하나를 눕혔다. 점검이 왔다. 넷을 셌다. 다섯째는 세지 않았다.<br>점검이 나간 뒤 다섯째 숨이 조금 길어졌다. 안도하는 숨이었다.`,
      ng:`끊자 다섯째 숨이 멈췄다.<br><br>병실 전체가 조용해졌다. 넷의 숨도 같이 멈췄다.<br>정각 점검이 들어와 숫자를 셌다. 하나가 모자랐다. 간호사가 이쪽을 봤다.`,
      win:{ exp:14, dream:1 }, lose:{ mind:-16, spirit:-16 } }
  ] },

{ at:'B3', t:'객차 — 따라 뛰는 심장',
  x:`객차에 승객이 열한 명이다. 다 잔다. 탐지술을 폈다.<br><br>
    심장 열하나. 박자가 제각각이다.<br>
    그런데 걸을 때마다 하나가 박자를 바꾼다. 이쪽 심장 박자로.<br><br>
    얼굴을 바꾸는 것은 얼굴만 바꾸지 않는다.`,
  o:[
    { l:'① 이쪽 심장을 일부러 흔들어 따라오는 하나를 가려낸다.', k:'sense', dc:22,
      ok:`숨을 멈췄다. 심장이 빨라진다. 열하나 중 열은 그대로다. 하나가 같이 빨라졌다.<br><br>창가 셋째 줄. 모자를 눌러쓴 남자. 자는 척한다. 심장이 이쪽을 따라 하느라 바쁘다.<br>그 줄을 피해 반대편 통로로 일행을 보냈다. 지나는 동안 이쪽 심장을 느리게, 느리게 끌어내렸다. 그 남자 심장도 같이 내려갔다. 잠든 사람처럼.<br><br>따라 하는 것은 따라 할 것이 있어야 한다. 이쪽 심장 하나로 그것을 붙잡아 두었다. 마력보다 제 몸을 먼저 다루는 법이 섰다.`,
      ng:`숨을 멈추자 열하나가 다 빨라졌다.<br><br>모두 이쪽을 따라 한다. 객차 전체가 이쪽 심장으로 뛴다.<br>머리가 터질 것 같아 주저앉았다. 그사이 승객 하나가 눈을 떴다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-18, spirit:-18 }, wake:1 },
    { l:'② 술식을 접고 짐 선반 밑으로 몸을 낮춰 지난다.', k:'hide', dc:21,
      ok:`술식을 접었다. 마력이 없으면 이쪽 심장도 저쪽에 덜 들린다.<br><br>좌석 등받이 그늘로 몸을 낮춰 통로를 지났다.<br>마지막 줄 선반에 버려진 도시락이 있다. 산나물 무침이 반쯤 남았다. 챙겼다.`,
      ng:`몸을 낮추는데 열차가 흔들렸다. 자는 승객 무릎에 손을 짚었다.<br><br>그 승객 심장이 멈췄다. 그리고 이쪽 박자로 다시 뛰기 시작했다.<br>손을 떼고 물러났다. 손바닥이 차다.`,
      win:{ exp:15, dream:2, item:'산나물' }, lose:{ hp:-20, spirit:-18 } }
  ] },

{ at:'B', t:'철문 — 자물쇠 속의 쇠',
  x:`철문에 자물쇠가 걸렸다. 열쇠 구멍이 작다.<br><br>
    뒤에서 무언가 오고 있다. 반응이 점점 커진다.<br>
    탐지술을 열쇠 구멍에 밀어 넣었다.<br><br>
    쇠 안에 쇠가 있다. 핀 다섯. 높이가 다 다르다.`,
  o:[
    { l:'① 핀마다 높이를 짚고 머리핀으로 하나씩 밀어 올린다.', k:'sense', dc:21,
      ok:`첫째 핀은 낮다. 둘째는 높다. 셋째는 녹이 슬어 걸린다. 마력으로 짚으며 머리핀 끝으로 밀었다.<br><br>다섯째 핀이 올라가는 순간 쇠가 돌았다. 철컥.<br>뒤의 반응이 모퉁이 하나 거리에 있을 때 문이 열렸다. 넘어가서 닫았다.<br><br>문 너머에서 반응이 문에 닿았다. 그리고 문 앞에서 오래 머물렀다. 자물쇠를 같은 방식으로 짚어 보는 것처럼.`,
      ng:`셋째 핀이 녹에 걸려 꿈쩍하지 않았다. 마력을 더 밀었다.<br><br>머리핀이 부러져 구멍에 박혔다.<br>뒤의 반응이 바로 등 뒤에 있다. 일행을 끌고 옆 복도로 뛰었다. 발목이 꺾였다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, mind:-14 } },
    { l:'② 마력으로 핀을 한꺼번에 밀어 올린다.', k:'fix', dc:22, cost:{ mana:24 },
      ok:`다섯 핀에 마력을 동시에 댔다. 한 번에 밀었다.<br><br>쇠가 비명을 지르며 돌았다. 자물쇠가 떨어졌다.<br>열린 문 너머 계단에서 빗소리가 올라온다.`,
      ng:`다섯을 한꺼번에 밀자 마력이 갈래로 찢어졌다.<br><br>찢어진 마력이 자물쇠 안에서 엉켰다. 쇠가 달아오른다. 손바닥이 데었다.<br>자물쇠는 그대로다. 뜨거워졌을 뿐이다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-26, spirit:-14 } }
  ] },

{ at:'B1', t:'방파제 수로 — 물 밑의 쇠',
  x:`수로 물이 검다. 탐지술을 물 밑으로 내렸다.<br><br>
    쇠 반응이 많다. 사슬, 깡통, 닻. 대부분 차갑다.<br>
    하나는 작고 반듯하다. 열쇠 모양이다. 창살 문 밑 진흙에 박혀 있다.<br><br>
    그 옆에 큰 반응 하나. 미지근하다. 진흙 속에서 아주 천천히 숨을 쉰다.`,
  o:[
    { l:'① 미지근한 것의 숨 사이를 재고 열쇠를 건진다.', k:'sense', dc:22,
      ok:`숨이 길다. 들이쉬고 한참 멈춘다. 멈춘 동안에는 감각이 닫힌다. 자는 숨이다.<br><br>멈춘 사이에 팔을 넣었다. 진흙 속에서 열쇠를 집었다. 다음 숨이 오기 전에 뺐다.<br>창살 문 자물쇠에 맞았다. 문이 물살 쪽으로 열린다.<br><br>문을 지나며 내려다봤다. 미지근한 것의 숨이 멈춘 채 다시 시작되지 않는다. 깨어서 숨을 참고 있다.`,
      doom:{ title:'진흙 속의 숨', what:'물 밑으로 끌려 가라앉습니다', dc:17, sec:55,
        text:`숨 사이를 쟀다. 길다고 읽었다. 팔을 넣었다.<br><br>열쇠에 손가락이 닿는 순간 미지근한 것이 숨을 들이쉬지 않고 움직였다.<br>손목이 잡혔다. 진흙이 열린다. 당긴다.<br><br>얼굴이 물에 잠긴다. 검다. 열쇠는 아직 손에 쥐어져 있다.`,
        dieText:`수로 물이 잔잔해졌다.<br><br>탐지술이 남아 있었다면 물 밑에 미지근한 반응이 둘이라고 했을 것이다.<br>하나는 크고 하나는 작다. 작은 것은 점점 차가워진다. 손에 열쇠를 쥔 모양으로.` },
      win:{ exp:24, dream:3 } },
    { l:'② 물 위로 떠다니는 것 중에 쓸 것을 고른다.', k:'luck', dc:21,
      ok:`떠내려오는 자루 하나를 갈고리로 끌어 올렸다.<br><br>안에 소금 덩이가 굳어 있다. 생선 절이던 소금이다. 물이 스며 겉만 녹았다.<br>자루 끈에 꼬리표. 『해무호 적재분』. 실리지 못한 것이다.`,
      ng:`끌어 올린 자루가 무겁다. 끌려 올라오지 않는다.<br><br>반대편에서 당긴다. 자루를 놓쳤다. 갈고리째 물에 빨려 들어갔다.<br>팔이 수로 벽에 긁혀 피가 난다.`,
      win:{ exp:14, dream:1, item:'소금 덩이' }, lose:{ hp:-24, spirit:-14 } }
  ] },

{ at:'B2', t:'당직실 — 수화기 너머',
  x:`당직실 전화가 울린다. 아무도 받지 않는다.<br><br>
    전화선을 따라 탐지술을 흘렸다. 선은 벽을 지나 아래층으로 간다.<br>
    선 끝에 반응이 있다. 따뜻하지 않다. 수화기를 들고 기다린다.<br><br>
    울림이 멈추지 않는다. 받을 때까지 울 것이다.`,
  o:[
    { l:'① 선을 거슬러 저쪽이 어느 층 어느 방인지 짚는다.', k:'sense', dc:21,
      ok:`선은 두 층 아래로 내려가 복도를 지나 안쪽 방으로 들어간다. 2층. 원무과.<br><br>그 방 둘레의 반응을 짚었다. 원무과 옆이 정문 당직 데스크다. 수화기를 든 것이 정문을 지키는 것이다.<br>그것이 전화를 들고 있는 동안은 정문에 없다.<br><br>울림이 계속되는 동안 내려가기로 했다. 전화는 받지 않았다. 받지 않는 한 저쪽도 수화기를 놓지 않는다.`,
      ng:`선을 거슬러 가다 저쪽 반응에 닿았다.<br><br>울림이 멈췄다. 이쪽이 수화기를 들지 않았는데 연결됐다.<br>머릿속에서 누가 말한다. 이쪽 이름을. 또박또박. 술식을 끊어도 그 목소리가 한참 남았다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-18, spirit:-16 } },
    { l:'② 마력을 선에 흘려 저쪽 수화기를 먹통으로 만든다.', k:'steady', dc:21, cost:{ mana:22 },
      ok:`선에 마력을 흘렸다. 거칠게. 지직거리는 소리.<br><br>울림이 멎었다. 선 끝 반응이 수화기를 내려놓았다. 그리고 오래 그 자리에 섰다. 무엇을 할지 모르는 것처럼.<br>그 사이 계단을 두 층 내려갔다.`,
      ng:`흘린 마력이 선을 타고 되돌아왔다. 손끝이 탔다.<br><br>울림이 멈추지 않았다. 더 커졌다.<br>복도 끝 병실 문들이 하나씩 열리기 시작했다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-24, spirit:-16 } }
  ] },

{ at:'B3', t:'우편칸 — 등기 금고',
  x:`우편칸 구석에 등기 금고가 있다. 바닥에 볼트로 박혔다.<br><br>
    다이얼 하나, 손잡이 하나.<br>
    탐지술을 대 본다. 안에 종이 반응. 그리고 작은 쇠 하나. 열쇠다.<br><br>
    금고 안 열쇠 모양이 기관실 문 자물쇠 모양과 같다. 아까 지나며 짚어 둔 그 자물쇠.`,
  o:[
    { l:'① 다이얼 속 톱니가 맞물리는 순간을 짚는다.', k:'sense', dc:22,
      ok:`다이얼을 돌리며 마력을 톱니 사이에 댔다. 톱니마다 홈이 있다. 홈이 바늘 밑에 올 때 마력이 아주 조금 덜 걸린다.<br><br>오른쪽으로 서른하나. 왼쪽으로 일곱. 오른쪽으로 열넷.<br>손잡이가 돌았다. 안에 등기 봉투들과 열쇠. 열쇠 꼬리표에 『기관실』.<br><br>쇠의 속을 손끝처럼 더듬었다. 걸리고 덜 걸리는 차이가 숫자가 됐다. 마력이 손가락 하나만큼 정교해졌다.`,
      ng:`다이얼을 돌리는 소리가 우편칸에 울렸다. 째깍. 째깍.<br><br>자루 더미 뒤에서 같은 소리가 따라 한다. 다른 금고는 없다.<br>셋째 숫자를 놓쳤다. 따라 하던 소리가 다이얼 소리보다 먼저 멎었다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-18, spirit:-16 }, wake:1 },
    { l:'② 소화용 손도끼로 금고 경첩을 부순다.', k:'break', dc:22,
      ok:`벽에 걸린 손도끼를 들었다. 경첩만 쳤다. 다섯 번, 여섯 번.<br><br>경첩이 터졌다. 문짝이 비스듬히 벌어진다. 손을 넣어 열쇠를 꺼냈다.<br>소리가 컸다. 다음 칸에서 무언가 귀를 기울이는 반응이 느껴졌다.`,
      ng:`도끼가 경첩에 맞고 튕겼다. 손목이 울렸다.<br><br>둘째에 도끼날이 빠졌다. 금고에 흠집 하나.<br>자루 더미가 무너지며 무언가 기어 나오는 소리가 났다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-28, mind:-12 } }
  ] },

{ at:'B', t:'되짚히는 술식',
  x:`탐지술을 폈는데 무언가 실 끝을 잡았다.<br><br>
    마력이 당겨진다. 아주 조금씩. 실을 감듯이.<br>
    저쪽이 이쪽 마력을 타고 이쪽을 찾고 있다.<br><br>
    끊으면 놓친다. 놓으면 끌려온다. 따라가면 저쪽이 어디 있는지 안다.`,
  o:[
    { l:'① 실을 놓지 않고 거꾸로 따라가 저쪽 자리를 짚는다.', k:'sense', dc:22,
      ok:`실을 느슨하게 풀어 주며 따라갔다. 저쪽이 감는 만큼만.<br><br>복도 셋, 문 하나, 계단 아래. 지하 보일러실 옆. 저쪽은 거기 있다. 움직이지 않고 실만 감는다.<br>자리를 짚자마자 실을 끊었다. 저쪽 손에 빈 실만 남았다.<br><br>그 자리로는 가지 않는다. 일행을 그 반대편 계단으로 이끌었다. 머리 뒤가 오래 서늘했다.`,
      doom:{ title:'감기는 실', what:'술식을 타고 온 것에게 끌려갑니다', dc:17, sec:55,
        text:`거꾸로 따라갔다. 저쪽이 감는 속도가 갑자기 빨라졌다.<br><br>실이 끊어지지 않는다. 마력이 몸 안에서 뽑혀 나간다. 발이 저절로 걷는다. 실이 가는 쪽으로.<br>계단을 내려간다. 내 발로. 일행이 부르는 소리가 멀다.<br><br>보일러실 문이 저 아래 열려 있다. 안이 붉다.`,
        dieText:`일행이 보일러실 앞에 닿았을 때 문은 닫혀 있었다.<br><br>문틈으로 가는 실 한 가닥이 나와 있다. 만지면 미지근하다.<br>당기면 안에서 무언가 반대로 당긴다.` },
      win:{ exp:25, dream:3 } },
    { l:'② 실을 단번에 끊고 마력을 몸 안에 가둔다.', k:'steady', dc:21,
      ok:`끊었다. 마력을 몸 안으로 거두어 닫았다. 문을 잠그듯이.<br><br>저쪽 손이 허공을 감는다. 이쪽을 잃었다.<br>대가로 한동안 탐지술이 나오지 않는다. 눈먼 채로 일행 소매를 잡고 걸었다.`,
      ng:`끊는 순간 끊긴 실 끝이 이쪽으로 튀었다.<br><br>머릿속에 저쪽 손바닥이 찍혔다. 차갑다. 손가락이 여섯이다.<br>한참 아무 생각도 할 수 없었다.`,
      win:{ exp:15, dream:2 }, lose:{ mind:-18, spirit:-18 } }
  ] },

{ at:'B', t:'빗소리 — 빗방울마다 반응',
  x:`비가 세다. 탐지술을 펴면 빗방울마다 반응이 튄다.<br><br>
    수천 개의 작은 쇠, 작은 물, 작은 움직임. 다 비다.<br>
    그 사이 어딘가에 사람 하나가 있다. 비 맞으며 서 있는 것.<br><br>
    다 들으면 머리가 터진다. 하나만 듣는 법은 아직 모른다.`,
  o:[
    { l:'① 떨어지는 것을 버리고 떨어지지 않는 것만 남긴다.', k:'sense', dc:22,
      ok:`빗방울은 다 아래로 간다. 아래로 가는 반응을 하나씩 흘려보냈다. 듣지 않고 지나가게.<br><br>수천 개가 빠져나간다. 하나가 남는다. 아래로 가지 않는 것. 서 있는 것. 골목 끝 전봇대 뒤.<br>그 골목을 피했다. 다른 골목 끝에서 돌아봤다. 전봇대 뒤 반응이 처음으로 움직였다. 이쪽이 빠져나간 것을 늦게 알았다.<br><br>모든 것을 듣는 대신 하나를 남기는 법을 알았다. 버리는 쪽이 듣는 쪽보다 넓었다. 술식이 조용해졌다.`,
      ng:`흘려보내다 빗방울 하나가 남았다. 그걸 사람으로 읽었다.<br><br>빗물받이 깡통이었다. 그 골목으로 갔다.<br>진짜 사람은 반대편 골목에 있었다. 등 뒤에서 발소리가 빗소리를 뚫고 왔다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-22, mind:-16 }, wake:1 },
    { l:'② 마력으로 둘레에 얇은 막을 쳐 빗소리를 끊는다.', k:'fix', dc:21, cost:{ mana:24 },
      ok:`일행 둘레에 마력 막을 쳤다. 빗방울 반응이 막 밖에서 멎는다.<br><br>막 안이 고요하다. 그 고요 속에서 막에 닿는 것만 느꼈다.<br>막 왼쪽에 무언가 닿았다가 물러났다. 오른쪽으로 걸었다.`,
      ng:`막을 치자 빗방울이 막에 쌓인다. 무게가 된다.<br><br>막이 터졌다. 터지는 소리가 머릿속에서 났다.<br>한동안 귀가 울려 아무것도 듣지 못했다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-16, spirit:-18 } }
  ] },

{ at:'B1', t:'경매장 2층 — 사무실 금고',
  x:`경매장 2층 사무실. 책상 하나, 금고 하나, 창 하나.<br><br>
    창밖으로 비 맞는 항구가 보인다. 해무호 불빛이 조금 가까워졌다.<br>
    여기 사람들이 찾는 장부가 이 방 어딘가 있다.<br><br>
    탐지술사는 금고부터 보지 않는다. 금고는 보라고 있는 것이다.`,
  o:[
    { l:'① 방 안 종이 반응 중 하나만 따뜻한 것을 찾는다.', k:'sense', dc:21,
      ok:`종이는 다 차갑다. 그런데 하나는 손을 많이 탔다. 사람 손기름이 배어 반응이 미지근하다.<br><br>금고 안이 아니다. 책상 밑 서랍 뒤판에 붙어 있다. 꺼냈다. 장부다. 날짜와 숫자, 그리고 숫자 옆에 이름 대신 동그라미.<br>오늘 날짜 줄에 동그라미가 다섯. 둘째 줄부터 가위표가 쳐 있다.<br><br>금고는 비어 있을 것이다. 열어 보지 않았다.`,
      ng:`미지근한 종이를 찾아 서랍을 뺐다. 서랍 뒤에 실이 묶여 있었다.<br><br>실이 당겨지며 복도 쪽에서 종이 울렸다.<br>계단에서 고무장화 소리가 올라온다. 장부를 쥔 채 창문으로 뛰어내렸다. 차양에 떨어져 갈비뼈를 찧었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, mind:-12 } },
    { l:'② 책상 위 물건 놓인 자리로 앉던 사람을 읽는다.', k:'gaze', dc:21,
      ok:`펜이 왼쪽에 있다. 찻잔 손잡이도 왼쪽. 왼손잡이다.<br><br>왼손잡이는 숨길 때 왼쪽 아래를 쓴다. 책상 왼쪽 아래 서랍. 이중 바닥 밑에 열쇠가 있다.<br>열쇠 꼬리표에 『옆』. 창고 옆문 열쇠다.`,
      ng:`읽는 데 몰두하다 창 쪽을 보지 않았다.<br><br>창밖 차양 위에 누가 쪼그려 앉아 이쪽을 보고 있다. 비옷 모자 밑으로.<br>그가 창문을 두드렸다. 똑, 똑. 열어 달라는 것처럼.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-16, spirit:-18 } }
  ] },

{ at:'B2', t:'승강기 — 위쪽 화살표뿐인 단추',
  x:`승강기 단추는 위쪽 화살표 하나뿐이다. 여기는 7층보다 아래다. 그래도 위로만 간다.<br><br>
    탐지술을 승강기 통로에 흘렸다.<br>
    승강기 칸은 지금 위에 있다. 쇠줄이 팽팽하다. 칸 안에 반응이 하나. 차갑다.<br><br>
    칸 밑, 통로 바닥 쪽은 반응이 없다. 아래로 떨어진 데가 비었다.`,
  o:[
    { l:'① 쇠줄의 떨림으로 칸이 움직이는 때를 읽고 통로로 내려간다.', k:'sense', dc:22,
      ok:`쇠줄은 칸이 서 있을 때 고요하다. 움직이기 직전에 한 번 떤다. 모터가 숨을 들이쉬는 떨림이다.<br><br>고요한 동안 승강기 문을 억지로 벌렸다. 통로 벽 정비 사다리로 내려갔다. 한 층, 두 층.<br>쇠줄이 떨었다. 사다리 옆 정비 문으로 몸을 뺐다. 칸이 바로 등 뒤로 내려왔다가 다시 올라갔다.<br><br>쇳덩이의 숨을 읽었다. 숨 쉬는 것은 사람만이 아니다. 숨 쉬는 모든 것이 마력 끝에 걸린다.`,
      ng:`쇠줄이 떨지 않고 바로 움직였다. 이 승강기는 숨을 쉬지 않았다.<br><br>사다리에 매달린 채 칸이 내려오는 바람을 맞았다. 칸 밑이 머리 위 한 뼘에서 섰다.<br>칸 안 차가운 반응이 바닥 너머로 이쪽을 내려다본다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-18, spirit:-18 }, wake:1 },
    { l:'② 칸이 올라간 사이 통로로 뛰어내려 아래층 문틀을 잡는다.', k:'evade', dc:21,
      ok:`문을 벌리고 뛰어내렸다. 한 층 아래 문틀 턱을 손으로 잡았다.<br><br>매달려 문을 밀었다. 열린다. 굴러 나왔다. 5층.<br>위로만 가던 것이 처음으로 아래로 가는 길을 내줬다.`,
      ng:`문틀 턱을 잡았는데 손이 미끄러졌다. 기름이다.<br><br>한 층 더 떨어져 다음 턱에 가슴을 찧었다. 숨이 끊겼다.<br>그 턱에 겨우 걸려 매달렸다. 위에서 칸이 다시 내려오는 소리가 났다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-30, mind:-12 } }
  ] },

{ at:'B3', t:'침대칸 — 이름 붙은 침대',
  x:`침대칸 침대마다 명패가 꽂혔다. 이름이 적혀 있다.<br><br>
    한 침대 명패에 일행 하나의 이름이 있다.<br>
    그 침대에 탐지술을 댔다. 따뜻하다. 사람 하나만큼. 그런데 침대는 비어 있다.<br><br>
    시트 위에 누운 자리만큼 우묵하다.`,
  o:[
    { l:'① 빈 침대의 따뜻함이 어디로 이어지는지 짚는다.', k:'sense', dc:21,
      ok:`따뜻함이 침대에서 끝나지 않는다. 가늘게 이어진다. 통로를 지나 앞 칸으로. 사람이 방금 일어나 걸어간 따뜻함이다.<br><br>그런데 이 이름의 일행은 이쪽 옆에 서 있다.<br>따뜻함을 따라 앞 칸 문까지 갔다. 문 너머에 일행과 같은 크기의 반응이 하나 서 있다. 이쪽 일행과 똑같은 박자로 숨을 쉰다.<br><br>그 문을 열지 않았다. 옆 칸 통로로 돌아갔다. 일행의 손을 꼭 잡고.`,
      ng:`짚는 사이 일행이 명패를 뽑아 들었다. 제 이름이다. 얼굴이 하얘진다.<br><br>빈 침대의 따뜻함이 일행 쪽으로 옮겨 간다. 일행 몸에 겹친다.<br>일행이 이쪽을 본다. 눈이 한 박자 늦게 깜박인다. 다시 본다. 제때 깜박인다. 어느 쪽이 맞는지 모른다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-18, spirit:-20 } },
    { l:'② 명패를 뽑아 품에 넣고 커튼 뒤로 숨는다.', k:'hide', dc:21,
      ok:`명패를 뽑았다. 이름이 없으면 그 침대는 아무의 것도 아니다.<br><br>옆 침대 커튼 뒤로 일행과 숨었다. 통로에서 검표원이 지나간다. 명패 없는 침대 앞에서 멈췄다가 지나갔다.<br>세는 것은 명패를 센다. 사람이 아니라.`,
      ng:`명패가 꽂힌 틀에서 안 빠진다. 잡아당기는 소리가 났다.<br><br>통로 끝 검표원이 이쪽으로 걸어온다. 커튼 뒤로 숨기 전에 눈이 마주쳤다.<br>검표원이 명패를 보고 이쪽 일행을 본다. 표를 내밀라고 손을 펼친다.`,
      win:{ exp:15, dream:2 }, lose:{ mind:-16, spirit:-16 } },
    { l:'③ 침대 밑 짐칸을 뒤진다.', k:'luck', dc:21,
      ok:`침대 밑 짐칸을 열었다. 가방 하나. 일행 가방과 똑같은 가방이다.<br><br>안에 맑은 물 한 병과 꿀 한 줌이 든 작은 통. 일행이 챙겨 온 것과 똑같다.<br>일행 가방을 열어 봤다. 그쪽에도 다 있다. 둘 다 챙겼다. 이쪽 몫이 두 배가 됐다. 기분은 그렇지 않다.`,
      ng:`짐칸 문을 열자 안에서 손이 나왔다. 일행 손과 똑같은 손이다. 반지 자리까지.<br><br>그 손이 이쪽 손목을 쥐었다. 일행이 비명을 질렀다.<br>뿌리쳤다. 손목에 일행 손가락 모양으로 멍이 들었다.`,
      win:{ exp:14, dream:2, item:'꿀 한 줌' }, lose:{ hp:-22, spirit:-18 } }
  ] },

{ at:'B', t:'같은 방 — 숨은 사람',
  x:`문을 닫고 숨었다. 방이 어둡다. 일행 숨소리만 들린다.<br><br>
    탐지술을 폈다. 숨이 하나 많다.<br>
    방 구석, 캐비닛 안. 따뜻하다. 심장이 아주 빠르다. 겁에 질린 사람이다.<br><br>
    밖에서 쫓는 것이 문 앞을 지나간다. 캐비닛 안 사람이 숨을 들이켠다. 곧 소리를 낼 것이다.`,
  o:[
    { l:'① 캐비닛 속 심장 박자를 짚어 언제 소리가 터질지 잰다.', k:'sense', dc:21,
      ok:`심장이 빨라진다. 숨을 참는다. 참는 숨은 한계가 있다. 열둘. 열셋.<br><br>열다섯째에 터진다. 열넷째에 캐비닛 문을 살짝 열어 그 사람 입을 손으로 덮었다.<br>숨이 손바닥 안에서 터졌다. 소리는 나지 않았다. 문 앞 발소리가 지나갔다.<br><br>손을 떼자 그 사람이 떨면서 이쪽 손에 무언가를 쥐여 줬다. 약초 뭉치. 고맙다는 말 대신.`,
      ng:`박자를 세다 하나를 틀렸다. 손이 늦었다.<br><br>캐비닛 안에서 흐느끼는 소리가 터졌다. 문 앞 발소리가 멈췄다.<br>문고리가 돈다. 창으로 일행을 밀어냈다. 이쪽은 마지막에 나가다 창틀에 손바닥을 베였다.`,
      win:{ exp:18, dream:2, item:'약초 뭉치' }, lose:{ hp:-24, spirit:-16 } },
    { l:'② 다가가 낮게 말을 걸어 진정시킨다.', k:'bond', dc:21,
      ok:`캐비닛에 등을 대고 앉았다. 문틈에 대고 낮게 말했다. 괜찮다. 같이 나가자. 숨은 이렇게 쉬어라.<br><br>캐비닛 안 숨이 이쪽 숨을 따라 느려졌다.<br>발소리가 지나간 뒤 캐비닛 문이 열렸다. 같이 나왔다.`,
      ng:`말을 거는 순간 캐비닛 안 사람이 문을 박차고 나왔다.<br><br>이쪽을 쫓는 것으로 알았다. 비명을 지르며 문밖으로 뛰쳐나갔다.<br>복도에서 그 비명이 끊겼다. 방 안에서 아무도 움직이지 않았다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-18, spirit:-18 } }
  ] },

{ at:'B1', t:'선착장 — 빗속에서 다가오는 쇳덩이',
  x:`방파제 끝이다. 바다 쪽은 빗발과 어둠뿐이다.<br><br>
    탐지술을 바다로 펼쳤다. 큰 쇠 반응이 하나. 아주 크다. 천천히 다가온다.<br>
    해무호다. 그 안에 따뜻한 반응이 여럿. 차가운 반응이 더 많다.<br><br>
    배가 닿기 전에 선착장을 빠져나가야 한다. 배가 얼마나 남았는지 눈으로는 모른다.`,
  o:[
    { l:'① 쇳덩이가 물을 밀어내는 기운으로 남은 거리를 잰다.', k:'sense', dc:22,
      ok:`큰 쇠는 물을 밀며 온다. 밀린 물이 방파제에 먼저 닿는다. 그 닿는 박자를 셌다.<br><br>박자가 열둘에서 열하나로 줄었다. 줄어드는 빠르기로 셈하면 숨 오백.<br>오백 안에 선착장 끝 철문까지 간다. 일행을 뛰게 하지 않고 걷게 했다. 뛰면 넘어진다.<br><br>철문에 닿았을 때 배 고동이 울렸다. 셈과 반 숨 차이. 보이지 않는 것의 거리를 물의 숨으로 쟀다. 마력이 닿는 끝이 더는 끝이 아니다.`,
      ng:`물이 밀리는 박자를 셌다. 그런데 파도가 박자를 덮었다.<br><br>셈이 틀렸다. 고동이 생각보다 일찍 울렸다. 바로 등 뒤에서.<br>뱃전 불빛이 선착장을 쓸었다. 엎드렸다. 콘크리트에 턱을 찧었다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-24, mind:-14 }, wake:1 },
    { l:'② 마력으로 안개를 짙게 끌어모아 선착장을 덮는다.', k:'fix', dc:21, cost:{ mana:26 },
      ok:`빗물 섞인 바다 안개를 마력으로 끌어당겼다. 선착장 위에 흰 장막이 내려앉는다.<br><br>배 불빛이 안개에 막혀 번진다. 아무것도 비추지 못한다.<br>그 속으로 걸어 나갔다. 안개 밖으로 나왔을 때 다리가 후들거렸다.`,
      ng:`안개가 끌려오다 바람에 찢겼다.<br><br>마력이 바람에 실려 바다로 흩어진다. 배 쪽으로.<br>배 안의 차가운 반응들이 일제히 이쪽을 향했다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-16, spirit:-18 } }
  ] },

{ at:'B2', t:'한방 처치실 — 침대 밑의 흰 손',
  x:`한방 처치실이다. 약장이 벽을 채웠다. 쓴 냄새가 난다.<br><br>
    탐지술을 폈다. 처치 침대 밑에 반응이 하나. 사람 손 크기. 차갑다.<br>
    손만 있다. 팔이 이어지지 않는다. 바닥 밑으로 들어간다.<br><br>
    약장 맨 아래 칸에 약초 뭉치가 보인다. 침대 바로 옆이다.`,
  o:[
    { l:'① 손의 기운이 쉬는 틈을 재고 약장에 손을 뻗는다.', k:'sense', dc:22,
      ok:`손은 바닥을 짚고 있다. 짚은 손가락에 기운이 몰렸다 풀렸다 한다. 풀리는 사이는 숨 셋.<br><br>풀린 순간 약장 칸을 열었다. 약초 뭉치를 쥐었다. 숨 둘에 손을 뺐다.<br>셋째 숨에 손가락이 바닥을 긁었다. 이쪽 발자국이 있던 자리를.<br><br>약초에서 쑥 냄새가 난다. 상처에 붙이면 낫는다.`,
      doom:{ title:'흰 손', what:'흰 손에 발목을 잡혀 침대 밑으로 끌려갑니다', dc:17, sec:50,
        text:`숨 셋이라고 쟀다. 둘째 숨에 손이 움직였다.<br><br>발목이 잡혔다. 차갑다. 손가락이 뼈를 감는다.<br>넘어졌다. 침대 밑으로 끌린다. 바닥이 있어야 할 자리에 바닥이 없다.<br><br>손톱으로 침대 다리를 긁었다. 약초 냄새가 코를 찌른다.`,
        dieText:`처치 침대는 반듯하게 정리되어 있다. 시트에 주름 하나 없다.<br><br>침대 밑에서 차가운 반응이 둘이 됐다. 손 둘.<br>둘 다 바닥을 짚고 있다. 다음 발자국을 기다리며.` },
      win:{ exp:24, dream:3, item:'약초 뭉치' } },
    { l:'② 약초를 포기하고 일행 상처를 마력으로 다스린다.', k:'heal', dc:21,
      ok:`약장에 손대지 않았다. 일행을 문가에 앉혔다. 손바닥을 상처에 대고 마력을 흘렸다.<br><br>약초만은 못하다. 그래도 피는 멎었다.<br>침대 밑 손이 한참 이쪽 쪽을 향해 있다가 바닥 밑으로 내려갔다.`,
      ng:`마력을 흘리는데 침대 밑 손이 그 마력에 반응했다. 바닥을 짚고 이쪽으로 기어 온다.<br><br>손바닥을 거두고 일행을 끌고 나왔다. 상처가 다시 벌어졌다.<br>문을 닫자 문 밑 틈으로 손가락 끝이 나왔다가 들어갔다.`,
      win:{ exp:15, dream:2, hp:8 }, lose:{ hp:-22, spirit:-16 } }
  ] },

{ at:'B3', t:'기관실 — 빈 운전석',
  x:`기관실 창 너머가 보인다. 운전석이 비었다. 속도 손잡이가 끝까지 밀려 있다.<br><br>
    탐지술을 기관실에 폈다. 반응이 없다. 아무것도.<br>
    그런데 손잡이가 조금씩 더 밀린다. 저절로.<br><br>
    아무 반응도 없는 것이 손잡이를 밀고 있다.`,
  o:[
    { l:'① 반응이 없는 자리의 모양을 짚는다.', k:'sense', dc:22,
      ok:`반응이 없는 것은 잡히지 않는다. 대신 둘레의 반응이 그것을 피해 휜다. 공기, 열기, 쇠 냄새가.<br><br>휜 자리를 이어 보니 사람 모양이다. 운전석 옆에 서서 손잡이에 손을 얹었다.<br>그 반대편으로 몸을 돌려 기관실 문을 열었다. 비상 제동 줄을 당겼다. 사람 모양의 빈 자리가 이쪽으로 돌아섰다.<br><br>쇠바퀴가 비명을 지른다. 열차가 처음으로 느려진다.`,
      doom:{ title:'빈 자리', what:'보이지 않는 것에게 기관실 화실 쪽으로 끌려갑니다', dc:18, sec:50,
        text:`짚었다. 아무것도 없다. 정말 없다고 읽었다.<br><br>기관실 문을 열고 들어섰다. 등 뒤에서 문이 닫혔다.<br>어깨를 잡혔다. 잡은 것이 없다. 그런데 잡혔다. 화실 문 쪽으로 밀린다. 불이 붉다.<br><br>탐지술은 끝까지 아무것도 없다고 말한다.`,
        dieText:`기관실 운전석은 비어 있다.<br><br>속도 손잡이는 끝까지 밀려 있다. 이제 손 두 개가 그 손잡이를 민다.<br>탐지술이 남아 있다면 여전히 아무 반응도 없다고 할 것이다.` },
      win:{ exp:25, dream:4 } },
    { l:'② 마력을 실어 기관실 창을 깨고 제동 줄을 끌어당긴다.', k:'break', dc:21, cost:{ mana:24 },
      ok:`마력을 주먹에 모아 창을 쳤다. 유리가 터졌다. 팔을 넣어 제동 줄을 잡고 당겼다.<br><br>열차가 앞으로 쏠린다. 바퀴가 운다. 느려진다.<br>속도 손잡이가 반대로 밀려 나간다. 아무도 없는데. 그래도 느려지는 것이 더 빨랐다.`,
      ng:`창이 깨지기 전에 마력이 흩어졌다. 맨주먹이 유리에 맞았다.<br><br>손등이 찢어졌다. 유리에 금만 갔다.<br>금 너머 운전석에서 무언가 이쪽을 향해 고개를 돌리는 기척이 났다.`,
      win:{ exp:17, dream:2 }, lose:{ hp:-30, spirit:-12 } }
  ] },

{ at:'B', t:'마력이 바닥나 간다',
  x:`밤이 길다. 탐지술을 너무 많이 썼다. 손끝이 시리다.<br><br>
    마력이 바닥나면 탐지술사는 눈먼 사람이 된다.<br>
    다음 갈림길이 보인다. 어느 쪽에 무엇이 있는지 모른다.<br><br>
    남은 마력으로 한 번은 펼 수 있다. 그 한 번이 마지막일 수도 있다.`,
  o:[
    { l:'① 술식을 아끼고 귀와 코로 고른다.', k:'steady', dc:21,
      ok:`마력을 거뒀다. 귀를 열었다. 왼쪽에서 물 떨어지는 소리. 오른쪽에서 아무 소리도 안 난다.<br><br>아무 소리도 안 나는 데가 가장 위험하다. 왼쪽으로 갔다.<br>물 떨어지는 데에 빗물 받는 양동이가 있다. 맑은 빗물이 가득하다. 한 모금씩 나눠 마셨다.`,
      ng:`귀만으로 고르니 다 같은 소리다. 빗소리.<br><br>왼쪽으로 갔다. 막혔다. 돌아오는 길에 넘어져 무릎을 찧었다.<br>마력이 있었으면 안 했을 실수다.`,
      win:{ exp:14, dream:1, item:'맑은 물' }, lose:{ hp:-22, mind:-14 } },
    { l:'② 남은 마력을 짜내 한 번에 멀리 편다.', k:'sense', dc:22, cost:{ mana:28 },
      ok:`남은 마력을 다 짜냈다. 한 번. 세게. 멀리.<br><br>갈림길 둘 다 잡힌다. 왼쪽 끝에 차가운 반응 셋. 오른쪽 끝에 빈 계단.<br>오른쪽으로 갔다. 술식이 꺼지고 손끝이 저리다. 그래도 길은 맞았다.`,
      ng:`짜낸 마력이 반쯤 가다 꺼졌다. 갈림길 하나만 잡혔다. 왼쪽, 빈 듯하다.<br><br>왼쪽으로 갔다. 꺼진 마력 너머에 무엇이 있었는지는 직접 만나고 알았다.<br>뒤로 물러나다 벽에 머리를 박았다. 눈앞이 하얬다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-24, spirit:-18 } }
  ] },

{ at:'B', t:'일행 — 하나의 반응이 다르다',
  x:`습관처럼 일행에게도 탐지술을 흘렸다. 다들 따뜻하다. 숨을 쉰다.<br><br>
    하나가 조금 다르다. 따뜻한데 따뜻함이 겉에만 있다. 속이 미지근하다.<br>
    그 일행이 이쪽을 보고 웃는다. 늘 짓던 웃음이다.<br><br>
    언제부터였는지 모른다. 아까 그 복도부터였을지도.`,
  o:[
    { l:'① 속의 미지근함을 끝까지 짚어 무엇인지 가린다.', k:'sense', dc:22,
      ok:`겉의 따뜻함을 지나 안쪽을 짚었다. 아주 가늘게. 그 일행이 눈치채지 못하게.<br><br>안쪽 미지근함은 다른 것이 아니다. 그 일행 것이다. 피가 덜 돈다. 다쳤다. 옆구리. 말하지 않고 참고 있었다.<br>다가가 옷을 들쳤다. 젖은 붕대가 감겨 있다. 일행이 웃음을 거두고 고개를 숙인다. 짐이 될까 봐.<br><br>다른 것으로 읽힐 뻔한 것이 사람이었다. 반응을 읽고 나서 한 번 더 읽는 버릇이 들었다. 첫 읽기를 믿지 않는 술식이 섰다.`,
      ng:`짚는 순간 그 일행이 이쪽 손목을 잡았다. 짚는 것을 느꼈다.<br><br>눈이 차갑다. 이쪽을 의심하는 눈이다. 이쪽이 그쪽을 의심한 것처럼.<br>그 뒤로 둘은 서로 등 뒤에 서지 않았다. 일행 사이에 금이 하나 갔다.`,
      win:{ exp:23, dream:3, hp:6 }, lose:{ mind:-18, spirit:-18 }, wake:1 },
    { l:'② 아무 말 없이 그 일행 얼굴을 오래 본다.', k:'gaze', dc:21,
      ok:`봤다. 눈 깜박임이 제때다. 웃을 때 왼쪽 볼만 들린다. 늘 그랬다.<br><br>그 일행이 뭐냐고 묻는다. 대답 대신 어깨를 짚었다.<br>어깨가 떨린다. 아픈 것을 참는 떨림이다. 붕대를 다시 감아 줬다.`,
      ng:`오래 보자 그 일행 얼굴이 낯설어졌다. 아는 얼굴도 오래 보면 낯설다.<br><br>낯선 것이 이쪽 의심인지 그 얼굴인지 가릴 수 없다.<br>머리가 지끈거렸다. 한동안 아무 얼굴도 믿지 못했다.`,
      win:{ exp:15, dream:2 }, lose:{ mind:-16, spirit:-20 } },
    { l:'③ 일행 모두에게 정해 둔 말을 묻는다.', k:'bond', dc:20,
      ok:`들어오기 전에 정해 둔 말이 있다. 묻는 말, 받는 말.<br><br>하나씩 물었다. 다 받았다. 그 일행도.<br>받은 뒤에 그 일행이 작게 덧붙였다. 옆구리를 다쳤다고. 묻기를 기다렸다고.`,
      ng:`물었다. 그 일행이 받는 말을 잊었다. 머뭇거렸다.<br><br>다른 일행들이 그를 둘러싼다. 그가 뒷걸음질 친다. 진짜로 잊었을 뿐인데.<br>말리는 사이 다들 지쳤다. 아무도 서로를 다 믿지 못했다.`,
      win:{ exp:14, dream:1 }, lose:{ mind:-18, spirit:-16 } }
  ] },

{ at:'B', t:'출구 앞 — 마지막 술식',
  x:`출구가 보인다. 빗속으로 열린 문.<br><br>
    문 둘레에 탐지술을 펴 본다. 마지막으로.<br>
    문 너머 빗속에 반응이 없다. 너무 없다. 비조차 반응이 약하다.<br><br>
    무언가가 반응을 먹고 있다. 아니면 정말 비었다.`,
  o:[
    { l:'① 반응이 엷어지는 가장자리를 따라 비어 있는 모양을 그린다.', k:'sense', dc:22,
      ok:`엷은 데와 덜 엷은 데가 있다. 이으니 둥글다. 문 바로 앞, 사람 다섯이 설 만한 너비. 거기서만 비가 약하다.<br><br>우산이다. 아주 큰 검은 우산. 그 밑에 누가 서 있다. 반응을 막는 천이다.<br>문으로 나가지 않았다. 옆 창으로 일행을 내보냈다. 우산 밑 사람이 문만 바라보는 동안.<br><br>창을 넘으며 돌아봤다. 검은 우산이 아주 천천히 이쪽으로 돌아선다.`,
      ng:`엷은 데를 따라가다 마력이 다 떨어졌다. 모양을 다 그리지 못했다.<br><br>반쯤 그린 것을 믿고 문으로 나갔다. 문 앞에 검은 우산이 있다.<br>우산 밑에서 손이 나와 일행 하나 어깨를 짚었다. 떼어 내며 넘어져 팔꿈치가 깨졌다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-24, spirit:-18 } },
    { l:'② 술식을 접고 그냥 빗속으로 뛰어나간다.', k:'luck', dc:21,
      ok:`생각을 멈추고 뛰었다. 일행도 뛰었다.<br><br>문 앞을 지날 때 검은 천이 펄럭이는 소리가 났다. 아무것도 잡지 않았다.<br>빗속 큰길까지 뛰었다. 숨을 고르며 돌아보니 문 앞에 우산 하나가 뒤집혀 굴러 있다.`,
      ng:`뛰었다. 문 앞에서 무언가에 부딪혔다. 천이다. 축축하다.<br><br>천 안이 어둡다. 반응이 하나도 없는 어둠이다.<br>빠져나오려 버둥거리다 손톱이 찢겼다. 일행이 천을 걷어 끌어냈다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-26, mind:-14 } },
    { l:'③ 남은 마력을 문틀에 묶어 문을 한동안 붙들어 둔다.', k:'steady', dc:21, cost:{ mana:22 },
      ok:`문틀에 마력을 감았다. 문이 닫히지 않게. 그리고 문 앞 빈 자리가 다가오지 못하게.<br><br>일행이 문을 지나 빗속으로 나갔다. 마지막으로 이쪽이 나가며 마력을 풀었다.<br>문이 쾅 닫혔다. 문 안쪽에서 무언가 문을 두드린다. 늦었다.`,
      ng:`감은 마력이 문틀에서 미끄러졌다. 문이 닫히기 시작한다.<br><br>어깨를 문틈에 넣어 막았다. 문이 어깨를 문다.<br>일행이 다 나간 뒤 겨우 몸을 뺐다. 어깨가 퍼렇게 부었다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-28, spirit:-12 } }
  ] }
]);

// ------------------------------------------
// 보물사냥꾼 (treasure) · 자원 없음
// ------------------------------------------
kJob('treasure', 'B', [
{ at:'B', t:'빈 사무실 — 서랍의 버릇',
  x:`불 꺼진 사무실이다. 책상 셋. 서랍이 다 열려 있다. 누가 먼저 뒤졌다.<br><br>
    서류가 바닥에 흩어졌다. 급한 손이었다.<br>
    급한 손은 열린 데만 본다.<br><br>
    보물사냥꾼은 닫힌 데를 찾지 않는다. 열려 있는데 안 본 데를 찾는다.`,
  o:[
    { l:'① 열린 서랍의 바닥 밑을 더듬는다.', k:'sense', dc:21,
      ok:`서랍을 끝까지 빼냈다. 서랍 밑판 아래에 테이프로 붙인 봉투가 있다. 서랍을 뺀 사람은 서랍 안만 봤다.<br><br>봉투 안에 꿈결 조각 셋과 열쇠 하나. 열쇠 머리에 손톱으로 긁은 숫자. 2.<br>숨긴 사람은 서랍을 뒤질 사람을 알았다. 그 사람이 어디까지 볼지도.<br><br>숨긴 것보다 뒤진 손을 먼저 읽었다. 앞사람이 멈춘 자리에서 이쪽이 시작한다. 그 자리가 늘 가장 기름지다는 것을 손이 알게 됐다.`,
      ng:`서랍 밑을 더듬는데 손끝에 날이 걸렸다. 면도칼이 테이프로 붙어 있다. 위를 향해.<br><br>손가락 둘이 깊게 베였다.<br>숨긴 사람은 더듬을 사람을 알았다. 이쪽 같은 사람을.`,
      win:{ exp:22, dream:4 }, lose:{ hp:-24, mind:-12 }, wake:1 },
    { l:'② 흩어진 서류 더미를 대충 뒤진다.', k:'luck', dc:21,
      ok:`발로 서류를 헤쳤다. 종이 사이에 비닐봉지 하나.<br><br>말린 고기 몇 조각. 누가 야근하며 먹던 것이다.<br>봉지에 기름 묻은 지문이 있다. 크다. 그 손이 다시 이걸 찾으러 올지는 모른다.`,
      ng:`서류 사이에서 사진 한 장이 나왔다. 이 사무실이다. 지금처럼 어둡다.<br><br>사진 속 책상 앞에 누가 쪼그려 앉아 서류를 헤치고 있다. 이쪽 옷을 입었다.<br>사진 뒤에 오늘 날짜. 시각은 비었다.`,
      win:{ exp:14, dream:2, item:'말린 고기' }, lose:{ mind:-16, spirit:-18 } }
  ] },

{ at:'B1', t:'3번 창고 — 장부 한 권',
  x:`일은 장부 한 권이었다. 3번 창고 사무실에 있다고 했다.<br><br>
    사무실 금고 문이 열려 있다. 안은 비었다.<br>
    벽에 달력. 책상에 재떨이. 의자 등받이에 걸린 비옷 한 벌.<br><br>
    밀수꾼은 장부를 금고에 넣지 않는다. 금고는 털리라고 있는 것이다.`,
  o:[
    { l:'① 매일 손이 가는 물건 속을 본다.', k:'sense', dc:21,
      ok:`장부는 매일 쓴다. 매일 쓰는 것은 매일 손 닿는 데 둔다. 그리고 남이 손대기 싫은 데.<br><br>재떨이를 들었다. 재가 수북하다. 재떨이 밑바닥이 이중이다. 비틀자 돌아간다. 장부 대신 작은 수첩. 날짜와 숫자. 오늘 날짜에 다섯, 그 옆에 『모자라면 채울 것』.<br>수첩 맨 뒤 장에 옆문 비밀번호가 적혀 있다.<br><br>사람은 귀한 것을 더러운 데 둔다. 손대기 싫은 데. 그 버릇을 하나 더 손에 넣었다.`,
      ng:`재떨이를 들다 재를 쏟았다. 재 속에 아직 불씨가 있었다.<br><br>방금 누가 피웠다. 의자 등받이 비옷이 젖어 있다. 방금 벗었다.<br>사무실 문 밖에서 고무장화 소리가 멈췄다. 손바닥이 불씨에 데었다.`,
      win:{ exp:24, dream:4 }, lose:{ hp:-22, mind:-14 }, wake:1 },
    { l:'② 비옷 주머니를 뒤진다.', k:'gaze', dc:21,
      ok:`비옷 안주머니에 쪽지가 있다. 연필로 반듯하게. 『05:10 전량. 우산에게 보고.』<br><br>그리고 소금 덩이 하나. 굵은 소금을 뭉쳐 놓았다. 비린내 나는 손을 씻는 데 쓴 것이다.<br>쪽지는 제자리에 넣고 소금만 챙겼다.`,
      ng:`주머니에 손을 넣자 안에서 무언가 손가락을 감쌌다. 젖은 고무장갑이다. 빈 장갑.<br><br>빼려는데 장갑이 손가락에 들러붙는다. 떼어 냈다. 손등에 표백제가 묻어 살갗이 일어났다.`,
      win:{ exp:16, dream:2, item:'소금 덩이' }, lose:{ hp:-22, spirit:-14 } },
    { l:'③ 금고 안쪽 벽판을 뜯어 본다.', k:'break', dc:22,
      ok:`빈 금고 안쪽 벽판을 손톱으로 들었다. 비틀어 뜯었다.<br><br>벽판 뒤에 얇은 칸. 꿈결 조각 넷이 끼어 있다. 털린 금고에 남은 것은 턴 사람이 못 본 것이다.`,
      ng:`벽판을 뜯자 철사가 함께 당겨졌다. 천장 어딘가에서 종이 울렸다.<br><br>창고 전체에 울린다. 빗소리보다 크게.<br>사무실을 뛰쳐나오다 계단에서 굴렀다.`,
      win:{ exp:16, dream:3 }, lose:{ hp:-28, mind:-12 } }
  ] },

{ at:'B2', t:'병실 — 종이학 하나',
  x:`빈 침대 베개 위에 종이학이 하나 앉아 있다. 약 봉투로 접었다.<br><br>
    병실 사람들은 가진 것이 없다. 그래서 가진 것을 접는다.<br>
    침대 철제 다리 끝에 고무 마개가 끼워져 있다. 넷 중 하나만 새것이다.<br><br>
    넷 중 새것 하나에 눈이 간다.`,
  o:[
    { l:'① 새 고무 마개를 빼고 철제 다리 속을 본다.', k:'sense', dc:21,
      ok:`마개를 뺐다. 철제 다리 속이 비었다. 둘둘 만 종이가 들어 있다.<br><br>펴 보니 약 봉투 넷을 이은 그림이다. 7층부터 1층까지 계단. 층마다 빨간 점 하나. 점 옆에 글씨. 『세지 마. 세어지지 마.』<br>그림 끝에 꿈결 조각 둘이 테이프로 붙어 있다. 이걸 그린 사람은 나가지 못했다. 나갈 사람을 위해 남겼다.`,
      ng:`마개를 빼자 안에서 물이 쏟아졌다. 차다. 다리 속에 물이 가득 차 있었다.<br><br>물에 젖은 종이가 흘러나와 바닥에서 풀어졌다. 글씨가 번져 읽을 수 없다.<br>침대가 기울며 정강이를 찍었다.`,
      win:{ exp:18, dream:3 }, lose:{ hp:-22, mind:-14 } },
    { l:'② 종이학을 펴 본다.', k:'luck', dc:21,
      ok:`날개부터 폈다. 약 봉투다. 이름 칸이 비었다.<br><br>안에 알약 대신 꿀 한 줌이 굳어 있다. 간식으로 받은 꿀을 아껴 접어 둔 것이다.<br>종이학을 다시 접어 베개 위에 올려 두었다. 꿀만 챙겼다.`,
      ng:`종이학을 펴는 순간 옆 침대 사람이 벌떡 일어났다. 눈을 감은 채.<br><br>이쪽 손에서 종이학을 낚아챈다. 다시 접기 시작한다. 같은 자리를 계속.<br>손톱이 이쪽 손등을 길게 그었다.`,
      win:{ exp:14, dream:1, item:'꿀 한 줌' }, lose:{ hp:-20, spirit:-16 } }
  ] },

{ at:'B3', t:'객차 선반 — 무거운 가방',
  x:`선반 위에 가방이 줄지어 있다. 다들 잔다.<br><br>
    가방 하나가 작은데 끈이 팽팽하다. 무겁다.<br>
    무거운 것은 바닥에 넣는다. 그런데 이 가방은 위가 무겁다. 끈 매듭이 위쪽으로 당겨졌다.<br><br>
    가방 아래 좌석 사람이 고개를 든 채 잔다. 가방을 올려다보는 각도로.`,
  o:[
    { l:'① 가방을 내리지 않고 바닥 박음질을 손끝으로 읽는다.', k:'sense', dc:21,
      ok:`선반에 올라선 채 가방 바닥을 더듬었다. 박음질이 두 줄이다. 한 줄은 공장 것, 한 줄은 손바느질.<br><br>손바느질 줄을 손톱으로 뜯었다. 바닥과 바닥 사이에 납작한 꾸러미. 기차표 한 장과 꿈결 조각 넷. 기차표 행선지 칸에 역 이름이 적혀 있다. 이 열차 표 중에 처음 보는 적힌 칸이다. 『저녁재』.<br>박음질을 다시 눌러 두었다. 무게가 그대로다.<br><br>무거운 쪽은 거짓말을 한다. 거짓말한 쪽 반대편에 진짜가 있다. 손끝이 그걸 먼저 짚게 됐다.`,
      ng:`박음질을 뜯는 소리가 났다. 작게.<br><br>아래 좌석 사람이 눈을 떴다. 가방을 본다. 이쪽 손을 본다. 아무 말 없이 손을 뻗어 이쪽 발목을 잡았다.<br>뿌리치고 선반에서 떨어졌다. 팔걸이에 옆구리를 박았다.`,
      win:{ exp:23, dream:4 }, lose:{ hp:-26, mind:-12 }, wake:1 },
    { l:'② 가방을 낚아채고 다음 칸으로 빠진다.', k:'evade', dc:22,
      ok:`끈을 끊고 가방을 낚아챘다. 그대로 통로를 걸었다. 뛰지 않고.<br><br>다음 칸에서 열었다. 위쪽 칸에 쇳덩이. 무게를 맞추려 넣은 것이다. 아래쪽에 말린 버섯 꾸러미.<br>버섯만 챙기고 가방은 선반 위에 두었다. 누가 찾으러 오든 무게는 그대로다.`,
      ng:`가방을 낚아채는데 끈이 아래 좌석 사람 손목에 감겨 있었다.<br><br>당기자 그 사람이 딸려 일어선다. 눈을 감은 채.<br>가방을 놓고 물러났다. 그 사람은 가방을 다시 선반에 올리고 앉았다. 이쪽을 향해 고개를 든 채로.`,
      win:{ exp:15, dream:2, item:'야생 버섯' }, lose:{ mind:-16, spirit:-18 } }
  ] },

{ at:'B', t:'열린 금고 — 너무 쉬운 것',
  x:`방 한가운데 금고가 열려 있다. 안에 꿈결이 쌓였다. 불빛에 반짝인다.<br><br>
    방에 아무도 없다. 문도 열려 있다.<br>
    지키는 사람이 없는 보물은 보물이 아니다.<br><br>
    보물사냥꾼은 미끼를 안다. 미끼를 놓은 사람이 무엇을 바라는지도.`,
  o:[
    { l:'① 방바닥에서 미끼 놓은 사람이 서 있던 자리를 찾는다.', k:'sense', dc:22,
      ok:`금고 둘레 먼지가 고르다. 문에서 금고까지만 한 줄로 쓸렸다. 미끼를 놓은 사람이 걸어간 줄이다.<br><br>그 줄은 금고에서 돌아오지 않는다. 금고 옆 벽으로 간다. 벽지가 한 군데만 판판하다. 문짝이다. 안에서 기다리는 문.<br>금고에 손대지 않았다. 벽 문 앞에 의자를 비스듬히 괴었다. 열면 소리가 나게.<br><br>나가면서 문간에 떨어진 꿈결 조각 둘을 주웠다. 미끼를 놓다 흘린 것이다. 흘린 것은 미끼가 아니다.`,
      ng:`줄을 따라가다 벽 문을 찾았다. 그 순간 문이 안에서 한 뼘 열렸다.<br><br>틈으로 눈 하나가 내다본다. 이쪽이 찾은 것을 안다.<br>문이 다시 닫혔다. 그 뒤로 등 뒤가 계속 따가웠다. 그 눈이 어디서든 보는 것처럼.`,
      win:{ exp:18, dream:3 }, lose:{ mind:-18, spirit:-18 } },
    { l:'② 빨리 쓸어 담고 문으로 뛴다.', k:'luck', dc:22,
      ok:`두 손으로 쓸어 담고 뛰었다. 문을 넘는 순간 등 뒤에서 금고 문이 저절로 닫혔다.<br><br>쾅. 문이 닫히는 바람이 등을 떠밀었다.<br>주머니가 묵직하다. 운이었다. 다음엔 같은 운이 없다.`,
      doom:{ title:'닫히는 방', what:'방에 갇힌 채 벽 속의 것에게 끌려갑니다', dc:17, sec:55,
        text:`두 손으로 쓸어 담았다. 금고 바닥이 비자 철컥 소리.<br><br>방문이 닫힌다. 혼자서. 문고리가 바깥쪽에만 있다.<br>금고 옆 벽지가 갈라지며 문 하나가 열린다. 안은 어둡다. 손이 나온다.<br><br>주머니가 무겁다. 무거워서 빨리 못 뛴다.`,
        dieText:`방은 다시 정리되었다. 금고 문이 열려 있다. 안에 꿈결이 쌓였다.<br><br>아까보다 조금 많다.<br>불빛에 반짝인다. 문도 열려 있다.` },
      win:{ exp:20, dream:4 } }
  ] },

{ at:'B1', t:'냉동 창고 — 배가 부른 생선',
  x:`냉동 창고 갈고리마다 언 생선이 걸렸다. 다 같은 종류다. 크기도 비슷하다.<br><br>
    몇 마리만 배가 불룩하다.<br>
    배 부른 생선은 알을 밴 것이다. 아니면 무언가를 밴 것이다.<br><br>
    밀수꾼은 언 생선 배를 갈라 넣고 꿰맨다.`,
  o:[
    { l:'① 배 꿰맨 자국이 있는 놈만 골라 가른다.', k:'sense', dc:21,
      ok:`배를 손끝으로 쓸었다. 알 밴 놈은 배가 매끈하다. 꿰맨 놈은 실밥이 얼어 까끌하다.<br><br>까끌한 놈 하나를 내려 칼끝으로 실밥을 땄다. 기름종이 꾸러미. 안에 꿈결 조각 셋과 작은 열쇠.<br>열쇠에 쇠 꼬리표. 『2냉』. 둘째 냉동실이다.<br><br>생선 몸통은 언 짐승 고기와 함께 옆 상자에 들어 있던 것이다. 고기 한 덩이를 같이 챙겼다.`,
      ng:`실밥을 따는 칼이 언 비늘에 미끄러졌다. 손바닥을 그었다.<br><br>피가 생선 배에 떨어져 금방 언다.<br>배를 갈랐다. 안에는 알뿐이다. 손만 버렸다.`,
      win:{ exp:18, dream:3, item:'짐승 고기' }, lose:{ hp:-26, mind:-12 } },
    { l:'② 언 손을 녹이며 천천히 하나씩 본다.', k:'heal', dc:20,
      ok:`서두르지 않았다. 손을 겨드랑이에 넣어 녹이고, 한 마리 보고, 다시 녹였다.<br><br>손가락이 끝까지 말을 들었다. 넷째 생선 아가미 안에 접힌 쪽지가 있다. 『문은 철사. 안에서 구멍으로.』<br>쪽지를 쥐고 문 쪽 구멍을 찾았다.`,
      ng:`녹이는 사이 시간이 갔다. 입김이 엷어진다. 손이 녹지 않는다.<br><br>생선 하나 못 보고 손이 굳었다.<br>일행이 손을 비벼 주었다. 손등 살갗이 일어났다.`,
      win:{ exp:14, dream:1, hp:8 }, lose:{ hp:-24, spirit:-12 } }
  ] },

{ at:'B2', t:'기록 보관실 — 빠진 서류철',
  x:`기록 보관실 서가가 끝없이 이어진다. 서류철이 번호대로 꽂혔다.<br><br>
    한 칸에서 번호가 하나 빈다. 0703 다음이 0705.<br>
    빈자리에 먼지가 없다. 최근에 뺐다.<br><br>
    있는 것보다 없는 것을 먼저 센다.`,
  o:[
    { l:'① 빠진 철이 어디로 갔는지 둘레에서 찾는다.', k:'sense', dc:21,
      ok:`뺀 사람은 읽으려고 뺐다. 읽으려면 불빛이 있어야 한다. 이 방에 불빛은 창가뿐이다.<br><br>창가 경비원 의자 밑. 방석 속. 0704가 접혀 들어 있다. 경비원은 아무것도 안 하는 척 그걸 깔고 앉아 있었다.<br>방석째 들고 왔다. 펴 보니 704호 환자 기록이다. 마지막 장에 퇴원 날짜 대신 『정문 당직 교대』라고 적혀 있다.<br><br>빈자리가 가장 많은 것을 말했다. 없는 것을 세는 셈이 손에 붙었다.`,
      ng:`빈자리를 따라가다 엉뚱한 서가 끝에 닿았다.<br><br>서가 끝에 철이 하나 거꾸로 꽂혀 있다. 0704. 뽑자 뒤에서 서가가 기울었다.<br>서가 사이에 어깨가 끼었다. 일행이 끌어냈다. 서류가 산처럼 쏟아졌다.`,
      win:{ exp:23, dream:4 }, lose:{ hp:-26, mind:-14 }, wake:1 },
    { l:'② 빈자리에 다른 철을 꽂아 빠진 티를 지운다.', k:'fix', dc:20,
      ok:`옆 칸 철 하나를 빼 빈자리에 꽂았다. 번호가 이어진다.<br><br>세는 사람은 번호를 센다. 내용은 안 본다.<br>나오는 길에 정각 점검이 서가를 훑었다. 멈추지 않고 지나갔다.`,
      ng:`철을 옮겨 꽂는 사이 다른 칸이 빈다. 그 칸을 메우면 또 빈다.<br><br>한참 옮기다 손이 떨렸다.<br>등 뒤에서 누가 철 번호를 소리 내어 세기 시작했다.`,
      win:{ exp:14, dream:2 }, lose:{ mind:-16, spirit:-16 } }
  ] },

{ at:'B3', t:'식당칸 주방 — 칼 소리 너머 찬장',
  x:`식당칸 주방에서 칼질 소리가 난다. 탁, 탁, 탁. 쉬지 않는다.<br><br>
    주방 문틈으로 찬장이 보인다. 위 칸은 그릇, 아래 칸은 식재료.<br>
    요리사는 등을 보이고 도마만 본다.<br><br>
    요리사는 귀한 것을 손 닿는 데, 그러나 손님 눈이 닿지 않는 데 둔다.`,
  o:[
    { l:'① 요리사 손이 가장 자주 가는 칸을 읽는다.', k:'sense', dc:21,
      ok:`칼질 사이사이 요리사 왼손이 찬장 셋째 칸으로 간다. 무언가 집어 도마에 뿌린다. 소금이다.<br><br>그 칸 안쪽 깊이 단지가 하나 더 있다. 손이 거기까지는 안 간다. 아끼는 것이다.<br>요리사가 칼을 갈러 돌아선 사이 손을 뻗었다. 꿀단지다. 한 줌을 덜고 뚜껑을 닫았다.<br><br>칼질 소리가 다시 시작됐다. 탁, 탁. 박자가 한 번 늦었다.`,
      ng:`셋째 칸으로 손을 뻗는 순간 칼질 소리가 멈췄다.<br><br>요리사가 돌아보지 않는다. 칼을 든 채 그대로 서 있다.<br>손을 거두자 칼질 소리가 다시 났다. 그런데 도마가 아니라 문틀을 친다. 이쪽 손이 있던 자리를.`,
      win:{ exp:18, dream:2, item:'꿀 한 줌' }, lose:{ mind:-18, spirit:-16 } },
    { l:'② 바닥에 떨어진 식재료 상자를 뒤진다.', k:'luck', dc:21,
      ok:`문 앞에 상자 하나가 엎어져 있다. 쏟아진 것 중에 민물고기 두 마리. 아직 싱싱하다.<br><br>하나를 집었다. 상자 밑에 쪽지가 깔려 있다. 『오늘 손님 수 + 다섯.』<br>요리사는 넉넉히 준비했다.`,
      ng:`상자를 들자 아래에서 쥐가 쏟아졌다. 손등을 물렸다.<br><br>쥐들이 주방 안으로 달린다. 칼질 소리가 멈췄다.<br>쥐 우는 소리가 하나씩 끊겼다. 탁, 탁, 탁.`,
      win:{ exp:14, dream:1, item:'민물고기' }, lose:{ hp:-22, spirit:-14 } },
    { l:'③ 칼질 박자에 맞춰 주방을 가로지른다.', k:'hide', dc:22,
      ok:`탁. 한 걸음. 탁. 한 걸음. 칼이 도마에 닿을 때만 움직였다.<br><br>찬장 앞을 지나며 아래 칸에서 말린 버섯 한 묶음을 집었다. 탁.<br>뒷문을 지나 연결 통로로 나왔다. 칼질 소리가 계속된다. 고르게.`,
      ng:`박자가 바뀌었다. 탁, 탁, 탁탁.<br><br>이쪽 걸음이 한 번 남았다. 요리사가 칼을 든 채 고개만 돌린다.<br>찬장 문을 방패 삼아 뒤로 물러났다. 칼끝이 문짝에 박혔다. 손가락 한 마디 옆에.`,
      win:{ exp:15, dream:2, item:'야생 버섯' }, lose:{ hp:-24, mind:-14 } }
  ] },

{ at:'B', t:'복도 끝 — 벽을 보고 앉은 사람',
  x:`복도 끝 의자에 사람이 앉아 있다. 벽을 보고. 움직이지 않는다.<br><br>
    외투 어깨가 젖었다. 숨은 없다.<br>
    이 밤에 먼저 와서 끝난 사람이다.<br><br>
    끝난 사람은 끝나기 전에 무언가를 숨긴다. 들킬까 봐 가장 몸 가까이.`,
  o:[
    { l:'① 외투 안감을 손끝으로 쓸어 꿰맨 자리를 찾는다.', k:'sense', dc:21,
      ok:`주머니는 비었다. 뒤진 사람이 있었다. 주머니만 뒤졌다.<br><br>안감을 쓸었다. 옷깃 안쪽 바늘땀이 서툴다. 실 색이 다르다. 뜯었다. 납작한 열쇠와 접은 종이. 종이에 연필로 출구 하나와 가위표 둘.<br>외투를 원래대로 여몄다. 그의 얼굴은 보지 않았다.<br><br>숨긴 것을 찾았다기보다 숨긴 마음을 따라갔다. 가장 무서울 때 사람은 가장 가까운 데 둔다. 그 셈이 몸에 섰다.`,
      ng:`안감을 쓸다 그가 앞으로 기울었다. 의자가 넘어갔다.<br><br>큰 소리. 그가 바닥에 엎어졌다. 얼굴이 이쪽을 향한다. 눈을 뜨고 있다.<br>그 얼굴이 머리에서 안 떠난다. 복도 저편에서 문 하나가 열렸다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-18, spirit:-18 }, wake:1 },
    { l:'② 그를 바로 눕히고 신발 속을 본다.', k:'heal', dc:20,
      ok:`그를 바닥에 반듯이 눕혔다. 눈을 감겼다.<br><br>신발을 벗기자 깔창 밑에 꿈결 조각 둘이 있다. 걸을 때마다 밟았을 것이다.<br>신발을 다시 신겼다. 끈도 묶었다.`,
      ng:`눕히는데 몸이 무겁다. 일행과 같이 들다 허리가 삐끗했다.<br><br>신발 속은 비었다. 대신 그의 손이 이쪽 소매를 쥐고 있다. 언제부터인지 모른다.<br>손가락을 하나씩 떼어 냈다. 차갑다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-22, spirit:-16 } }
  ] },

{ at:'B', t:'무거운 주머니',
  x:`주운 것이 많다. 주머니가 묵직하다.<br><br>
    다음은 환기구를 기어 지나야 한다. 좁다.<br>
    뒤에서 무언가 다가오는 소리가 난다.<br><br>
    보물사냥꾼은 버리는 것을 가장 싫어한다. 그리고 버리지 못해 죽은 사람을 가장 많이 안다.`,
  o:[
    { l:'① 쓸모로 따져 반을 버린다.', k:'gaze', dc:21,
      ok:`하나씩 꺼냈다. 값나가는 것과 문을 여는 것. 문을 여는 것만 남겼다. 열쇠, 쪽지, 꿈결.<br><br>나머지는 환기구 앞에 쏟았다.<br>가볍게 기었다. 뒤에서 온 것이 쏟아진 것 앞에서 한참 멈췄다. 버린 것이 시간을 벌어 줬다.`,
      ng:`버린 것 중에 열쇠 하나가 섞였다. 기어가는 중에 알았다.<br><br>돌아갈 수 없다. 뒤에 그것이 있다.<br>그 열쇠가 맞을 문을 만날 때마다 생각날 것이다.`,
      win:{ exp:16, dream:3 }, lose:{ mind:-18, spirit:-14 } },
    { l:'② 다 메고 기어간다.', k:'steady', dc:21,
      ok:`이를 악물었다. 주머니를 앞으로 밀며 기었다.<br><br>팔꿈치가 다 벗겨졌다. 그래도 다 가지고 나왔다.<br>환기구 밖에서 한참 누워 숨을 골랐다. 주머니를 끌어안고.`,
      ng:`주머니가 환기구 이음매에 걸렸다. 앞으로도 뒤로도 안 간다.<br><br>뒤에서 소리가 가까워진다. 끈을 끊었다.<br>주머니는 환기구 안에 남았다. 뒤에서 온 것이 그것을 끌어가는 소리가 났다.`,
      win:{ exp:14, dream:3 }, lose:{ hp:-26, mind:-14 } }
  ] },

{ at:'B1', t:'경매장 — 낙찰된 상자',
  x:`경매판에 분필로 번호가 적혔다. 번호마다 낙찰. 상자들이 하역장 쪽에 줄을 섰다.<br><br>
    상자 하나에만 낙찰가가 비었다. 그런데 낙찰 도장이 찍혔다.<br>
    값을 매기지 않고 팔린 상자다.<br><br>
    값 없는 것이 가장 비싼 법이다.`,
  o:[
    { l:'① 상자 못 자국으로 몇 번 열렸는지 읽고 연다.', k:'sense', dc:22,
      ok:`못 머리마다 망치 자국이 둘이다. 한 번 닫았다가 다시 열고 다시 닫았다. 안을 바꿨다.<br><br>못을 하나씩 비틀어 뽑았다. 망치 자국이 하나뿐인 못 셋은 건드리지 않았다. 그 셋은 처음부터 다른 데로 이어진 못이다.<br>뚜껑을 비스듬히 들었다. 안에 작은 상자. 그 안에 꿈결 조각 넷과 장부 한 장. 낙찰자 이름 칸이 『우산』.<br><br>상자를 다시 닫았다. 못 셋은 끝까지 손대지 않았다.`,
      doom:{ title:'값 없는 상자', what:'상자 안으로 끌려 들어갑니다', dc:17, sec:55,
        text:`못을 다 뽑았다. 망치 자국이 하나뿐인 못까지.<br><br>마지막 못이 빠지는 순간 상자 옆판이 안으로 넘어갔다. 상자 안에 바닥이 없다.<br>상자는 하역장 바닥 구멍 위에 놓여 있었다. 팔을 넣고 있던 몸이 앞으로 쏠린다.<br><br>아래에서 갈고리가 소매를 건다. 당긴다.`,
        dieText:`하역장에 상자가 줄을 섰다. 낙찰가가 빈 상자 하나.<br><br>못이 다시 박혔다. 망치 자국이 셋.<br>노란 비옷 둘이 상자를 들어 트럭에 실었다. 무겁다고 서로 웃었다.` },
      win:{ exp:24, dream:4 } },
    { l:'② 옆 상자들 사이에서 떨어진 것을 줍는다.', k:'luck', dc:21,
      ok:`줄 선 상자들 사이 바닥을 훑었다. 상자 옮기다 흘린 것들.<br><br>얼음 조각 사이에 민물고기 한 마리. 장어 상자에서 빠진 것이다. 아직 꿈틀댄다.<br>그 옆에 꿈결 조각 하나. 누가 주머니에서 흘렸다.`,
      ng:`줍다 보니 상자 그늘에 노란 비옷 하나가 쪼그려 앉아 있었다. 그도 줍는 중이었다.<br><br>둘이 눈이 마주쳤다. 그가 갈고리를 든다. 이쪽은 빈손이다.<br>얼음 더미 쪽으로 몸을 던졌다. 갈고리가 등을 긁었다.`,
      win:{ exp:14, dream:2, item:'민물고기' }, lose:{ hp:-28, mind:-12 } }
  ] },

{ at:'B2', t:'직원 탈의실 — 번호 자물쇠 사물함',
  x:`4층 직원 탈의실. 사물함이 줄지어 섰다. 다 번호 자물쇠다.<br><br>
    사물함마다 이름표 대신 숫자. 하나만 이름표가 붙었다. 이름이 지워졌다.<br>
    그 사물함 손잡이가 반질반질하다.<br><br>
    자물쇠 다이얼 숫자 몇 개만 칠이 닳았다.`,
  o:[
    { l:'① 닳은 숫자와 닳은 순서로 번호를 맞힌다.', k:'sense', dc:22,
      ok:`닳은 숫자는 넷. 7, 0, 4, 1. 넷째가 가장 덜 닳았다. 늘 마지막에 돌리는 숫자는 손이 빨리 지나간다.<br><br>첫째는 가장 많이 닳은 7. 7, 0, 4, 1. 철컥.<br>안에 직원 가운 한 벌과 명찰. 명찰 숫자가 이쪽 일행 수와 같다. 가운 주머니에 정문 당직 교대표. 교대 시각은 다음 정각.<br><br>숫자가 손때로 말했다. 사람이 무엇을 자주 만지는지가 그 사람의 비밀번호다. 그걸 읽는 손이 하나 더 생겼다.`,
      ng:`7, 0, 4, 1. 안 열린다. 1, 4, 0, 7. 안 열린다.<br><br>다이얼 돌리는 소리가 탈의실에 울렸다.<br>다른 사물함 안에서 똑같이 다이얼 돌리는 소리가 대답했다. 안쪽에서.`,
      win:{ exp:24, dream:4 }, lose:{ mind:-18, spirit:-16 }, wake:1 },
    { l:'② 아무 사물함이나 손잡이를 당겨 본다.', k:'luck', dc:22,
      ok:`줄 끝 사물함 하나가 잠기지 않았다. 문이 열린다.<br><br>안에 비닐에 싼 약초 뭉치. 한방 처치실 것이다. 그리고 꿈결 조각 하나.<br>문을 닫았다. 안쪽 문에 볼펜으로 줄이 그어져 있었다. 수십 개.`,
      doom:{ title:'열린 사물함', what:'사물함 안으로 끌려 들어갑니다', dc:17, sec:50,
        text:`줄 끝 사물함이 열렸다. 안이 깊다. 사물함 깊이가 아니다.<br><br>어둠 속에서 흰 소매가 나온다. 손목을 잡는다. 당긴다.<br>어깨가 문틀에 걸린다. 사물함 문이 등을 밀며 닫힌다.<br><br>안쪽 문짝에 볼펜 줄이 수십 개다. 손이 저절로 볼펜을 찾는다.`,
        dieText:`탈의실 사물함은 다 잠겨 있다.<br><br>줄 끝 사물함 이름표에 이름이 새로 적혔다. 그리고 지워졌다.<br>안쪽 문짝에 볼펜 줄이 하나 늘었다.` },
      win:{ exp:16, dream:2, item:'약초 뭉치' } }
  ] },

{ at:'B3', t:'우편 분류칸 — 반송 자루',
  x:`우편 분류칸 선반마다 칸이 나뉘었다. 역 이름이 칸마다 붙었다.<br><br>
    맨 아래 칸은 『반송』. 자루가 가득하다.<br>
    반송되는 것은 받을 사람이 없는 것이다. 이 열차에서는 내리지 못한 사람 것이다.<br><br>
    반송 자루가 하나 더 들어올 자리가 비어 있다.`,
  o:[
    { l:'① 반송 자루 중 가장 최근 것을 골라 연다.', k:'sense', dc:21,
      ok:`꼬리표 잉크가 번지지 않은 자루. 가장 최근이다. 끈 매듭이 서툴다. 직원이 아니라 승객이 묶었다.<br><br>안에 편지 한 통과 맑은 물 한 병, 꿈결 조각 셋. 편지는 수신인 칸이 비었다. 첫 줄만 읽었다. 『이걸 찾은 사람은 앞 칸으로 가지 말고 지붕으로.』<br>편지를 접어 넣었다. 물과 꿈결을 챙겼다.`,
      ng:`가장 최근 자루를 열었다. 안에서 젖은 외투가 나왔다. 이쪽 일행 하나가 입은 것과 같다.<br><br>일행을 돌아봤다. 일행은 외투를 입고 있다. 그런데 소매가 마르지 않았다. 비는 그쳤는데.<br>자루를 닫다 손가락을 끈에 쓸렸다.`,
      win:{ exp:18, dream:3, item:'맑은 물' }, lose:{ hp:-20, mind:-16 } },
    { l:'② 자루를 다 끌어내 빈 칸 뒤를 본다.', k:'break', dc:21,
      ok:`자루를 끌어냈다. 반송 칸 벽판이 헐겁다. 뜯었다.<br><br>벽판 뒤에 작은 칸. 우편 직원이 숨겨 둔 것이다. 말린 고기와 꿈결 조각 둘.<br>직원도 내리지 못한 것이다.`,
      ng:`자루를 끌어내다 맨 아래 자루가 움직였다. 혼자서.<br><br>자루가 이쪽 쪽으로 기어 온다. 발목에 닿는다.<br>뒤로 물러나다 선반에 머리를 박았다. 선반 칸들이 우르르 쏟아졌다.`,
      win:{ exp:15, dream:2, item:'말린 고기' }, lose:{ hp:-26, spirit:-14 } }
  ] },

{ at:'B', t:'마룻바닥 — 소리가 다른 판자',
  x:`낡은 방이다. 바닥이 마룻널이다. 밟을 때마다 삐걱인다.<br><br>
    한 판자만 삐걱이지 않는다. 대신 둔하게 운다. 아래가 꽉 찼다.<br>
    밖에서 비가 세진다. 뒤에서 오는 발소리가 아직 멀다.<br><br>
    판자 하나 들어 올리는 데 숨 열.`,
  o:[
    { l:'① 판자 못이 어느 쪽이 새것인지 보고 그쪽부터 든다.', k:'sense', dc:20,
      ok:`네 귀퉁이 못 중 둘이 반짝인다. 자주 뺀 쪽이다. 그쪽으로 칼끝을 넣었다. 판자가 쉽게 들린다.<br><br>아래 칸에 깡통 셋. 하나는 말린 고기. 하나는 꿈결 조각. 하나는 비었다. 빈 깡통 바닥에 긁은 글씨. 『다 가져가지 마.』<br>하나는 남겼다. 판자를 덮었다. 숨 아홉.`,
      ng:`칼끝이 미끄러져 판자 틈에 끼었다. 빼는 데 숨 스물.<br><br>발소리가 가까워진다. 판자를 반쯤 들었다 놓쳤다. 손가락이 끼었다.<br>손톱이 까맣게 죽었다.`,
      win:{ exp:16, dream:3, item:'말린 고기' }, lose:{ hp:-24, mind:-12 } },
    { l:'② 발로 판자를 밟아 쪼개 연다.', k:'luck', dc:21,
      ok:`뒤꿈치로 내리찍었다. 판자가 두 쪽 났다.<br><br>아래 칸에 깡통이 있다. 꿈결 조각이 한 줌. 소리를 냈지만 값은 했다.<br>발소리가 빨라졌다. 깡통째 들고 뛰었다.`,
      ng:`찍은 판자가 쪼개지며 발이 빠졌다. 정강이까지.<br><br>아래 칸 깡통 모서리에 정강이가 찢겼다. 깡통은 비어 있었다.<br>발을 빼는 사이 발소리가 문 앞에 닿았다.`,
      win:{ exp:14, dream:3 }, lose:{ hp:-28, spirit:-12 } }
  ] },

{ at:'B1', t:'야적장 — 노인의 모자',
  x:`컨테이너 그늘에 노인 하나가 앉아 있다. 하역부 옷이다. 모자를 눌러썼다.<br><br>
    비를 맞으며 담배를 만다. 손이 떨린다.<br>
    노인이 이쪽을 본다. 아무 말 없이 모자를 고쳐 쓴다. 두 번.<br><br>
    두 번 고쳐 쓰는 손은 모자 안에 무언가 있을 때의 손이다.`,
  o:[
    { l:'① 노인이 모자를 만지는 손을 읽고 무엇을 바라는지 본다.', k:'sense', dc:21,
      ok:`모자를 만질 때마다 눈이 정문 쪽으로 간다. 두려운 눈이 아니다. 기다리는 눈이다.<br><br>노인은 팔 것이 있다. 팔 사람을 기다린다. 이쪽은 줄 것이 없다. 대신 일행 몫 물 한 모금을 내밀었다.<br>노인이 물을 마시고 모자를 벗었다. 안감에 꿰맨 종이 한 장. 정문 경비 교대 시각과 개구멍 자리. 노인은 그걸 이쪽 손에 쥐여 주고 모자를 다시 썼다.<br><br>숨긴 것을 훔치지 않고 숨긴 사람이 내놓게 했다. 손이 아니라 눈으로 먼저 값을 치렀다. 이 일의 다른 결이 하나 열렸다.`,
      ng:`모자에 시선이 오래 머물렀다. 노인이 그걸 봤다.<br><br>노인이 일어서서 호루라기를 문다. 불지 않는다. 이쪽을 본다. 불까 말까 재는 눈이다.<br>뒷걸음질로 물러났다. 노인은 끝내 불지 않았다. 그 대신 이쪽 얼굴을 오래 기억하는 눈이었다.`,
      win:{ exp:23, dream:3 }, lose:{ mind:-18, spirit:-16 }, wake:1 },
    { l:'② 노인 곁에 앉아 같이 비를 맞는다.', k:'bond', dc:21,
      ok:`옆에 앉았다. 아무 말도 하지 않았다. 노인이 만 담배 한 개비를 내밀었다. 사양했다.<br><br>노인이 혼잣말처럼 말한다. 셋째 줄 컨테이너는 비었다고. 문을 열면 바다 쪽 담이 보인다고.<br>일어서는 이쪽 손에 노인이 소금 덩이 하나를 쥐여 줬다. 젖지 않게 기름종이에 싸서.`,
      ng:`옆에 앉자 노인이 몸을 굳혔다. 손에 쥔 것을 숨긴다.<br><br>노인 등 뒤 컨테이너 문이 열리고 노란 비옷 둘이 나왔다. 노인이 이쪽을 가리킨다.<br>뛰었다. 등 뒤에서 노인이 미안하다고 했다.`,
      win:{ exp:15, dream:2, item:'소금 덩이' }, lose:{ hp:-24, spirit:-16 } }
  ] },

{ at:'B2', t:'휴게실 — 시든 화분',
  x:`병동 휴게실. 텔레비전이 꺼져 있다. 소파 하나, 화분 하나.<br><br>
    화분 식물이 시들었다. 그런데 흙은 젖어 있다. 누가 물을 준다. 식물에게가 아니다.<br>
    흙 표면이 한 군데만 조금 솟았다.<br><br>
    휴게실 벽시계가 정각 오 분 전이다.`,
  o:[
    { l:'① 솟은 자리 둘레 흙만 걷어 낸다.', k:'sense', dc:21,
      ok:`손가락으로 흙을 걷었다. 솟은 자리 밑에 비닐 주머니.<br><br>안에 약 봉투로 싼 꿈결 조각 넷. 그리고 계단 문 열쇠를 본뜬 비누 조각. 누가 열쇠를 비누에 눌러 본을 떴다.<br>흙을 다시 덮고 물을 조금 부었다. 젖은 흙은 젖은 흙으로 둔다.`,
      ng:`흙을 걷다 손끝에 무언가 걸렸다. 손가락이다. 흙 속에서 이쪽 손가락을 잡는다.<br><br>빼냈다. 흙이 손톱 밑에 가득하다.<br>화분 흙이 숨 쉬듯 한 번 오르내렸다.`,
      win:{ exp:18, dream:4 }, lose:{ mind:-18, spirit:-18 } },
    { l:'② 소파 쿠션 틈을 뒤진다.', k:'luck', dc:20,
      ok:`쿠션 틈에 손을 넣었다. 동전, 머리핀, 사탕 껍질.<br><br>그리고 꿀 한 줌이 든 작은 통. 뚜껑이 꼭 닫혔다. 누가 텔레비전 보며 먹던 것을 끼워 두었다.<br>머리핀도 챙겼다. 자물쇠 앞에서 쓸 데가 있다.`,
      ng:`쿠션 틈 깊은 데서 무언가 손등을 찔렀다. 바늘이다.<br><br>주삿바늘. 빈 주사기 세 개가 쿠션 속에 박혀 있었다.<br>손등이 화끈거린다. 무엇이 들어 있던 것인지 모른다.`,
      win:{ exp:14, dream:2, item:'꿀 한 줌' }, lose:{ hp:-22, mind:-14 } },
    { l:'③ 텔레비전 뒤판을 연다.', k:'gaze', dc:21,
      ok:`뒤판 나사가 하나만 남았다. 자주 열었다. 돌려 뺐다.<br><br>안에 부품이 없다. 빈 통이다. 꿈결 조각 둘과 쪽지. 『정각에 이 방 불 꺼짐. 그때 계단.』<br>벽시계를 봤다. 정각 이 분 전이다.`,
      ng:`뒤판을 열자 텔레비전이 켜졌다. 플러그가 빠져 있는데.<br><br>화면에 이 휴게실이 나온다. 위에서 내려다본 모습이다. 화면 속 이쪽이 텔레비전 뒤에 쪼그려 앉아 있다.<br>천장을 올려다봤다. 아무것도 없다. 화면 속 천장에는 무언가 있다.`,
      win:{ exp:16, dream:3 }, lose:{ mind:-16, spirit:-20 } }
  ] },

{ at:'B3', t:'특실 3호실 — 두드리는 트렁크',
  x:`특실 3호실 바닥에 트렁크가 하나 누웠다. 가죽이 낡았다. 자물쇠가 셋.<br><br>
    안에서 두드린다. 똑, 똑, 똑. 일정하게.<br>
    트렁크 손잡이에 꼬리표. 『종착 하차』.<br><br>
    트렁크 무게가 한쪽으로 쏠렸다. 두드리는 쪽 반대편이 무겁다.`,
  o:[
    { l:'① 무거운 쪽 자물쇠 하나만 연다.', k:'sense', dc:22,
      ok:`두드리는 것은 소리로 손을 부른다. 손이 가는 쪽은 두드리는 쪽이다. 그쪽은 열지 않는다.<br><br>무거운 쪽 자물쇠만 머리핀으로 땄다. 가죽 틈이 손바닥만큼 벌어진다. 손을 넣었다. 금속 상자. 꺼냈다.<br>상자 안에 꿈결 조각 넷과 기관실 시간표. 종착 직전 마지막 굽은 길에 연필로 동그라미.<br><br>두드리는 소리가 멎었다. 반대편에서 무언가 가죽을 긁기 시작했다.`,
      doom:{ title:'두드리는 트렁크', what:'트렁크 안으로 끌려 들어갑니다', dc:17, sec:55,
        text:`무거운 쪽 자물쇠를 땄다. 손을 넣었다.<br><br>무거운 쪽이 상자가 아니었다. 웅크린 무언가의 등이었다. 등이 돌아눕는다.<br>손목이 잡혔다. 두드리던 것은 미끼였다. 무거운 쪽이 진짜였다.<br><br>트렁크 뚜껑이 들린다. 안이 트렁크보다 깊다. 어깨가 들어간다.`,
        dieText:`특실 3호실 바닥에 트렁크가 누웠다. 자물쇠 셋이 다 잠겼다.<br><br>안에서 두드린다. 똑, 똑, 똑. 아까보다 조금 빠르게.<br>꼬리표가 둘이 됐다. 둘 다 『종착 하차』.` },
      win:{ exp:25, dream:4 } },
    { l:'② 트렁크를 건드리지 않고 방 안 다른 데를 뒤진다.', k:'steady', dc:21,
      ok:`두드리는 소리를 견디며 방을 훑었다. 침대 밑, 세면대 밑, 옷장 위.<br><br>옷장 위에 서류 가방 하나. 안에 말린 고기 한 묶음과 꿈결 조각 하나.<br>방을 나올 때까지 두드리는 소리가 이쪽 등을 따라왔다.`,
      ng:`두드리는 소리가 머릿속에 박혔다. 박자가 이쪽 심장과 같아졌다.<br><br>세면대 밑을 뒤지다 손이 떨려 거울을 깼다.<br>깨진 거울에 트렁크가 비친다. 뚜껑이 한 뼘 열려 있다.`,
      win:{ exp:15, dream:2, item:'말린 고기' }, lose:{ hp:-22, spirit:-18 } }
  ] },

{ at:'B', t:'거래 — 나누자는 사람',
  x:`다른 무리 하나와 마주쳤다. 셋이다. 이쪽처럼 쫓기는 얼굴이다.<br><br>
    그쪽 우두머리가 손을 들어 보인다. 빈손이다.<br>
    이쪽 주머니가 무겁다는 걸 안다. 그쪽은 출구를 안다고 한다.<br><br>
    반 나누자고 한다. 출구는 나가서 알려 주겠다고.`,
  o:[
    { l:'① 그쪽 무리가 가진 것을 먼저 읽는다.', k:'gaze', dc:21,
      ok:`셋 중 하나 신발이 말랐다. 다들 젖었는데. 처음부터 안에 있던 사람이다. 그쪽 무리도 그걸 모른다.<br><br>우두머리에게만 들리게 말했다. 당신 셋째 사람 신발을 보라고.<br>우두머리 얼굴이 굳는다. 거래는 없던 일이 됐다. 그쪽이 셋째에게서 천천히 떨어지는 사이 이쪽은 반대편으로 빠졌다.<br><br>그쪽 우두머리가 지나치며 이쪽 손에 쪽지를 쥐여 줬다. 출구 그림이다. 공짜로.`,
      ng:`읽으려고 오래 봤다. 그쪽이 그 눈길을 의심으로 읽었다.<br><br>우두머리가 손을 내린다. 셋이 퍼져 선다. 이쪽 주머니를 노린다.<br>주머니 하나를 바닥에 던져 주고 빠졌다. 반이 아니라 하나를 잃었다.`,
      win:{ exp:18, dream:3 }, lose:{ mind:-16, spirit:-18 } },
    { l:'② 반을 내주고 같이 간다.', k:'bond', dc:22,
      ok:`반을 덜어 내밀었다. 그쪽이 받았다. 그리고 앞장섰다.<br><br>정말로 출구를 알았다. 같이 나왔다. 나와서 그쪽 우두머리가 이쪽이 준 반에서 다시 반을 돌려줬다.<br>빗속에서 그가 말했다. 이 밤에 반을 내놓는 사람은 처음 봤다고.`,
      ng:`반을 내밀었다. 그쪽이 받았다. 앞장섰다. 그리고 첫 모퉁이에서 셋 다 뛰었다.<br><br>쫓아갔다. 막다른 길이다. 셋은 없다. 벽 아래 배수구 덮개가 막 닫혀 있다.<br>속은 것을 알았을 때 뒤에서 발소리가 다가왔다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-22, mind:-16 } }
  ] },

{ at:'B', t:'두 개의 빛 — 반짝이는 것과 숨긴 것',
  x:`방 하나에 두 가지가 있다.<br><br>
    탁자 위에 열린 상자. 안에 꿈결이 반짝인다. 손 닿는 데.<br>
    방 구석 벽에 걸린 낡은 액자. 사진 속 사람이 이쪽을 본다. 액자가 조금 비뚤다.<br><br>
    복도 끝에서 문 여는 소리가 하나씩 다가온다. 하나만 고를 시간이다.`,
  o:[
    { l:'① 비뚤어진 액자 뒤를 본다.', k:'sense', dc:22,
      ok:`반짝이는 것은 누가 보라고 둔 것이다. 비뚤어진 것은 누가 급하게 만진 것이다.<br><br>액자를 들었다. 뒤 벽에 금고 다이얼. 그리고 액자 뒷면에 연필로 숫자 셋. 급한 손은 번호를 가까이 적는다.<br>돌렸다. 열렸다. 꿈결 조각 넷과 이 건물 뒷문 열쇠.<br><br>반짝이는 것을 등지고 비뚤어진 것을 봤다. 이제 방에 들어서면 눈이 먼저 비뚤어진 것을 찾는다. 반짝임은 나중이다.`,
      ng:`액자를 들었다. 뒤에 아무것도 없다. 벽이다.<br><br>탁자 쪽을 봤다. 상자가 닫혀 있다. 누가 닫았다. 방에는 이쪽뿐이었다.<br>문 여는 소리가 이 방 앞에서 멈췄다.`,
      win:{ exp:24, dream:4 }, lose:{ mind:-18, spirit:-16 }, wake:1 },
    { l:'② 탁자 위 상자를 쓸어 담는다.', k:'luck', dc:21,
      ok:`쓸어 담았다. 진짜 꿈결이다. 미끼가 아니었다. 아니면 미끼치고 진짜였다.<br><br>주머니가 무거워졌다. 상자 바닥에 깔린 천 밑에 말린 고기 한 조각.<br>문 여는 소리가 옆방에서 멈췄을 때 이쪽은 창밖 처마에 있었다.`,
      ng:`쓸어 담는데 상자 바닥이 꺼졌다. 손목이 상자에 물렸다.<br><br>상자 안쪽에 쇠 이빨이 둘러져 있었다. 빼냈다. 손목에 이빨 자국이 줄지어 났다.<br>꿈결은 꺼진 바닥 아래로 다 쏟아졌다.`,
      win:{ exp:16, dream:3, item:'말린 고기' }, lose:{ hp:-26, mind:-12 } },
    { l:'③ 둘 다 버리고 창으로 빠진다.', k:'evade', dc:20,
      ok:`둘 다 버렸다. 창틀을 넘어 처마로 나갔다.<br><br>처마 끝에서 돌아보니 방에 누가 들어와 상자와 액자를 차례로 본다. 둘 다 그대로 있는 걸 보고 오래 서 있다.<br>아무것도 안 가져간 방이다. 그게 더 이상해 보일 것이다.`,
      ng:`창틀을 넘다 처마 기와가 미끄러졌다. 한 층을 떨어졌다.<br><br>쓰레기 더미 위로 떨어졌다. 어깨를 찧었다.<br>위 창에서 누가 내려다본다. 손에 상자를 들고.`,
      win:{ exp:14, dream:1 }, lose:{ hp:-28, spirit:-12 } }
  ] },

{ at:'B', t:'출구 앞 — 가져갈 하나',
  x:`출구가 보인다. 빗속으로 난 문 하나.<br><br>
    문 앞 바닥에 상자 둘이 놓였다. 하나는 무겁다. 하나는 가볍다.<br>
    둘 다 들고는 못 뛴다. 뒤에서 발소리가 뛴다.<br><br>
    보물사냥꾼은 무게로 고르지 않는다.`,
  o:[
    { l:'① 상자를 놓은 손을 읽고 하나를 고른다.', k:'sense', dc:21,
      ok:`무거운 상자는 끈이 새것이다. 오늘 묶었다. 가벼운 상자는 끈이 낡았다. 오래 지켜 온 것이다.<br><br>오늘 묶은 것은 오늘 쓸 미끼다. 가벼운 것을 들었다. 뛰었다.<br>빗속 큰길에서 열었다. 꿈결 조각 셋과 맑은 물 한 병, 그리고 접힌 사진 한 장. 이 문 앞에 서 있는 이쪽 일행이 찍혀 있다. 무거운 상자를 든 모습으로.<br><br>무거운 상자를 고른 사진이다. 고르지 않은 쪽이다.`,
      ng:`가벼운 쪽을 골랐다. 들자 바닥이 빠졌다. 빈 상자였다. 끈만 낡게 해 둔 것이다.<br><br>무거운 쪽으로 손을 뻗었다. 발소리가 바로 등 뒤다.<br>빈손으로 문을 넘었다. 넘다 문턱에 정강이를 찍었다.`,
      win:{ exp:20, dream:4, item:'맑은 물' }, lose:{ hp:-24, mind:-14 } },
    { l:'② 무거운 상자를 지고 버틴다.', k:'steady', dc:22,
      ok:`무거운 상자를 등에 졌다. 허리가 꺾일 것 같다. 이를 악물고 문을 넘었다.<br><br>빗속에서 열었다. 소금 덩이가 가득하다. 굵은 소금. 무겁다. 값은 별로 안 나간다.<br>그래도 짊어진 무게만큼은 이쪽 것이다.`,
      ng:`상자를 지고 문턱을 넘다 다리가 풀렸다.<br><br>상자가 등을 짓누른다. 일행이 상자를 걷어차 떼어 냈다.<br>상자는 문 안쪽에 남았다. 허리가 한참 펴지지 않았다.`,
      win:{ exp:15, dream:2, item:'소금 덩이' }, lose:{ hp:-28, spirit:-12 } }
  ] }
]);
